def reverse_string(s):
    """Return the characters of s in reverse order."""
    chars = []
    for i in range(len(s) - 1, -1, -1):
        chars.append(s[i])
    return "".join(chars)


def reverse_words(sentence):
    """Reverse each word of a sentence while keeping the word order."""
    words = sentence.split(" ")
    for i in range(len(words)):
        words[i] = reverse_string(words[i])
    return " ".join(words)


def is_palindrome(s):
    """True if s reads the same forwards and backwards, ignoring case."""
    cleaned = "".join(c.lower() for c in s if c.isalnum())
    return cleaned == reverse_string(cleaned)


def char_frequency(s):
    """Map each character of s to how often it occurs."""
    counts = {}
    for i in range(len(s)):
        counts[s[i]] = counts.get(s[i], 0) + 1
    return counts


def mirrored_letters(s):
    """Characters that appear at mirrored positions in s."""
    freq = char_frequency(s)
    mirrored = {}
    last = len(s) - 1
    for position in range(len(s)):
        if s[position] == s[last - position]:
            mirrored[s[position]] = freq[s[position]]
    return mirrored


def describe(s):
    """Build a multi-line report about s and its reversal."""
    lines = ["original: %r" % s, "reversed: %r" % reverse_string(s)]
    freq = char_frequency(s)
    for char in sorted(freq.keys()):
        lines.append("  %r appears %d time(s)" % (char, freq[char]))
    total = 0
    for count in freq.values():
        total += count
    lines.append("total characters: %d" % total)
    mirrored = mirrored_letters(s)
    if mirrored:
        pairs = []
        for char, count in sorted(mirrored.items()):
            pairs.append("%s=%d" % (char, count))
        lines.append("mirrored: %s" % ", ".join(pairs))
    lines.append("palindrome: %s" % is_palindrome(s))
    return "\n".join(lines)


def main():
    samples = {
        "hello": "olleh",
        "Python": "nohtyP",
        "A man, a plan, a canal: Panama": "amanaP :lanac a ,nalp a ,nam A",
    }
    for text, expected in samples.items():
        result = reverse_string(text)
        status = "ok" if result == expected else "MISMATCH"
        print("%s -> %s [%s]" % (text, result, status))
    print()
    print(describe("level"))
    print()
    print(reverse_words("hello there Python fans"))


if __name__ == "__main__":
    main()

