VOWELS = "aeiou"


def count_vowels(text):
    """Return the total number of vowels (a, e, i, o, u) in text."""
    total = 0
    lowered = text.lower()
    for i in range(len(lowered)):
        if lowered[i] in VOWELS:
            total += 1
    return total


def vowel_histogram(text):
    """Map each vowel to how many times it occurs in text."""
    counts = {}
    for vowel in VOWELS:
        counts[vowel] = 0
    lowered = text.lower()
    for i in range(len(lowered)):
        char = lowered[i]
        if char in counts:
            counts[char] += 1
    return counts


def most_common_vowels(counts):
    """Return the vowels sharing the highest non-zero count, alphabetically."""
    best = 0
    for count in counts.values():
        if count > best:
            best = count
    if best == 0:
        return []
    winners = []
    for vowel, count in counts.items():
        if count == best:
            winners.append(vowel)
    return sorted(winners)


def format_histogram(counts, width=20):
    """Build text bars for each vowel, scaled so the largest bar is `width`."""
    peak = max(counts.values())
    lines = []
    for vowel in sorted(counts.keys()):
        count = counts[vowel]
        if peak == 0:
            filled = 0
        else:
            filled = int(width * count // peak)
        bar = "#" * filled
        lines.append("%s | %-*s %d" % (vowel, width, bar, count))
    return lines


def summarize(text):
    """Return a multi-line report about the vowels found in text."""
    counts = vowel_histogram(text)
    report = ["text: %r" % text, "vowels: %d" % count_vowels(text)]
    report.extend(format_histogram(counts))
    winners = most_common_vowels(counts)
    if winners:
        report.append("most common: " + ", ".join(winners))
    else:
        report.append("most common: none")
    return report


def main():
    samples = ["Hello World", "Python", "Sequoia is a queue of vowels"]
    for index in range(len(samples)):
        if index:
            print()
        for line in summarize(samples[index]):
            print(line)


if __name__ == "__main__":
    main()

