def calculate_factorial(n):
    """Return the factorial of the non-negative integer n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def factorial_table(limit):
    """Map each value from 0 to limit inclusive to its factorial."""
    table = {}
    for value in range(limit + 1):
        table[value] = calculate_factorial(value)
    return table


def digit_counts(table):
    """Map each argument in the table to the number of digits of its factorial."""
    counts = {}
    for value, factorial in table.items():
        counts[value] = len(str(factorial))
    return counts


def growth_ratios(table):
    """Ratio of each factorial to the previous one, for arguments above zero."""
    ratios = {}
    arguments = sorted(table.keys())
    for index in range(1, len(arguments)):
        current = arguments[index]
        previous = arguments[index - 1]
        ratios[current] = table[current] // table[previous]

    return ratios


def largest_below(table, ceiling):
    """Largest argument whose factorial does not exceed the given ceiling."""
    best = None
    for value, factorial in table.items():
        if factorial <= ceiling and (best is None or value > best):
            best = value
    return best


def format_table(table):
    """Render the factorial table as aligned text lines."""
    widths = [len(str(factorial)) for factorial in table.values()]
    width = max(widths)
    lines = []
    for value in sorted(table.keys()):
        lines.append("{:>3}! = {:>{}}".format(value, table[value], width))
    return lines


def main():
    limit = 12
    table = factorial_table(limit)
    for line in format_table(table):
        print(line)

    counts = digit_counts(table)
    print("total digits:", sum(counts.values()))
    for value, count in counts.items():
        if count > 5:
            print("{}! has {} digits".format(value, count))

    ratios = growth_ratios(table)
    for value in range(1, limit + 1):
        print("{}! / {}! = {}".format(value, value - 1, ratios[value]))

    print("largest factorial under one million:", largest_below(table, 1000000))
    print("calculate_factorial(5) =", calculate_factorial(5))
    print("calculate_factorial(0) =", calculate_factorial(0))


if __name__ == "__main__":
    main()

