def sum_list(numbers):
    """Return the sum of all numbers in the list (0 for an empty list)."""
    total = 0
    for index in range(len(numbers)):
        total += numbers[index]
    return total


def running_totals(numbers):
    """Return the list of partial sums: [n0, n0+n1, ...]."""
    totals = []
    for index in range(len(numbers)):
        totals.append(sum_list(numbers[:index + 1]))
    return totals


def sum_by_group(groups):
    """Map each group name to the sum of its list of numbers."""
    sums = {}
    for name, values in groups.items():
        sums[name] = sum_list(values)
    return sums


def grand_total(group_sums):
    """Add up every group's subtotal."""
    return sum_list(list(group_sums.values()))


def largest_group(groups):
    """Name of the group holding the most numbers (empty string if none)."""
    best = ""
    best_size = -1
    for name in groups.keys():
        size = len(groups[name])
        if size > best_size:
            best = name
            best_size = size
    return best


def column_sums(rows):
    """Sum each column of a rectangular table of numbers."""
    width = 0
    for row_index in range(len(rows)):
        width = max(width, len(rows[row_index]))
    sums = []
    for column in range(width):
        column_values = [row[column] for row in rows if column < len(row)]
        sums.append(sum_list(column_values))
    return sums


def format_report(group_sums):
    """Build aligned "name: subtotal" lines plus a TOTAL line."""
    width = 0
    for name in group_sums.keys():
        width = max(width, len(name))
    lines = []
    for name, subtotal in group_sums.items():
        lines.append("{0:<{1}} : {2}".format(name, width, subtotal))
    lines.append("{0:<{1}} : {2}".format("TOTAL", width, grand_total(group_sums)))
    return lines


def main():
    print(sum_list([1, 2, 3, 4]))
    print(sum_list([]))
    print(running_totals([1, 2, 3, 4]))

    groups = {
        "monday": [4, 8, 15],
        "tuesday": [16, 23, 42, 7],
        "wednesday": [],
    }
    subtotals = sum_by_group(groups)
    for line in format_report(subtotals):
        print(line)
    print("busiest:", largest_group(groups))
    print("columns:", column_sums([[1, 2, 3], [4, 5], [6, 7, 8, 9]]))


if __name__ == "__main__":
    main()

