def find_max(numbers):
    """Return the largest integer in the non-empty list `numbers`."""
    largest = numbers[0]
    for i in range(1, len(numbers)):
        if numbers[i] > largest:
            largest = numbers[i]
    return largest


def index_of_max(numbers):
    """Return the position of the first occurrence of the largest value."""
    target = find_max(numbers)
    for i in range(len(numbers)):
        if numbers[i] == target:
            return i


def count_values(numbers):
    """Map each value in `numbers` to how many times it appears."""
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def distinct_sorted(numbers):
    """Return the distinct values of `numbers` in increasing order."""
    return sorted(count_values(numbers).keys())


def most_frequent(numbers):
    """Return the value that appears most often, breaking ties by size."""
    best = None
    best_count = 0
    for value, count in count_values(numbers).items():
        if count > best_count or (count == best_count and value > best):
            best = value
            best_count = count
    return best


def running_maxima(numbers):
    """Return the maximum of every prefix of `numbers`."""
    maxima = []
    for end in range(1, len(numbers) + 1):
        maxima.append(find_max(numbers[:end]))
    return maxima


def summarize(numbers):
    """Build a small report dictionary describing `numbers`."""
    counts = count_values(numbers)
    return {
        "maximum": find_max(numbers),
        "position": index_of_max(numbers),
        "distinct": len(counts),
        "total": sum(numbers),
        "repeats": sum(c - 1 for c in counts.values()),
        "mode": most_frequent(numbers),
    }


def format_report(numbers):
    """Render the summary of `numbers` as printable lines."""
    lines = ["numbers: " + ", ".join(str(n) for n in numbers)]
    for name, value in summarize(numbers).items():
        lines.append("  {:<9} {}".format(name + ":", value))
    lines.append("  values: " + " ".join(str(v) for v in distinct_sorted(numbers)))
    lines.append("  prefix maxima: " + " ".join(str(m) for m in running_maxima(numbers)))
    return lines


def main():
    samples = [[10, 5, 20, 8], [7], [-4, -9, -4, -12], [3, 3, 1, 9, 9, 2]]
    for index in range(len(samples)):
        print("sample", index)
        for line in format_report(samples[index]):
            print(line)


if __name__ == "__main__":
    main()

