def tokenize(text):
    """Split text into lowercase words, ignoring punctuation."""
    words = []
    current = []
    for i in range(len(text)):
        ch = text[i]
        if ch.isalnum() or (ch == "'" and current):
            current.append(ch.lower())
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return words


def word_frequency(text):
    """Return a dict mapping each lowercase word of text to its frequency."""
    freq = {}
    for word in tokenize(text):
        freq[word] = freq.get(word, 0) + 1
    return freq


def top_words(freq, n):
    """Return the n most frequent (word, count) pairs, ties broken alphabetically."""
    ordered = sorted(freq.items(), key=lambda item: (-item[1], item[0]))
    selected = []
    for rank in range(min(n, len(ordered))):
        selected.append(ordered[rank])
    return selected


def total_words(freq):
    return sum(freq.values())


def group_by_length(freq):
    """Group the vocabulary of a frequency table by word length."""
    groups = {}
    for word in freq.keys():
        groups.setdefault(len(word), []).append(word)
    for words in groups.values():
        words.sort()
    return groups


def shared_vocabulary(first, second):
    common = []
    for word in first.keys():
        if word in second:
            common.append(word)
    common.sort()
    return common


def format_histogram(freq, n, width=24):
    pairs = top_words(freq, n)
    peak = max(freq.values())
    label_width = max(len(word) for word, _ in pairs)
    lines = []
    for word, count in pairs:
        bars = max(1, int(round(count * width / peak)))
        lines.append("{:<{w}} {:>3} {}".format(word, count, "#" * bars, w=label_width))
    return "\n".join(lines)


