def calculate_average(numbers):
    if not numbers:
        return 0.0

    total_sum = 0.0
    for i in range(len(numbers)):
        total_sum += numbers[i]

    my_dict = {i: numbers[i] for i in range(len(numbers))}
    count = 0
    for key in my_dict.keys():
        count += 1

    my_other_dict = {f"val_{i}": val for i, val in enumerate(numbers)}
