def remove_duplicates(items):
    """Return a new list without duplicates, keeping first-occurrence order."""
    seen = set()
    unique = []
    for value in items:
        if value not in seen:
            seen.add(value)
            unique.append(value)
    return unique


def count_occurrences(items):
    """Map each element to the number of times it appears in items."""
    counts = {}
    for value in items:
        counts[value] = counts.get(value, 0) + 1
    return counts


def removed_count(items):
    """Number of elements that would be dropped by remove_duplicates."""
    total = 0
    for count in count_occurrences(items).values():
        total += count - 1
    return total


def first_positions(items):
    """Map each element to the index of its first occurrence."""
    firsts = {}
    for index, value in enumerate(items):
        if value not in firsts:
            firsts[value] = index
    return firsts


def duplicated_values(items):
    """Return the values that appear more than once, in first-occurrence order."""
    firsts = first_positions(items)
    repeated = [value for value, count in count_occurrences(items).items() if count > 1]
    repeated.sort(key=lambda value: firsts[value])
    return repeated


def build_rows(items):
    """Build table rows describing each distinct value of items."""
    counts = count_occurrences(items)
    firsts = first_positions(items)
    rows = [("value", "count", "first index")]
    for value in remove_duplicates(items):
        rows.append((repr(value), str(counts[value]), str(firsts[value])))
    return rows


def format_table(rows):
    """Render rows of equal length as column-aligned text lines."""
    widths = []
    for column in range(len(rows[0])):
        widths.append(max(len(row[column]) for row in rows))
    lines = []
    for row in rows:
        cells = []
        for column in range(len(widths)):
            cells.append(row[column].ljust(widths[column]))
        lines.append(" | ".join(cells).rstrip())
    return lines


def format_report(items, per_line=8):
    """Build a multi-line description of the de-duplication of items."""
    unique = remove_duplicates(items)
    lines = ["input: %r" % (items,)]
    for start in range(0, len(unique), per_line):
        chunk = unique[start:start + per_line]
        lines.append("unique[%d:%d] %s" % (start, start + len(chunk),
                                           ", ".join(repr(value) for value in chunk)))
    lines.append("dropped %d element(s)" % removed_count(items))
    repeated = duplicated_values(items)
    if repeated:
        lines.append("repeated: %s" % ", ".join(repr(value) for value in repeated))
    lines.extend(format_table(build_rows(items)))
    return "\n".join(lines)


def main():
    samples = {
        "numbers": [1, 2, 2, 3, 1, 4],
        "letters": ['a', 'b', 'a'],
        "mixed": [0, 'x', 0, None, 'x', None],
        "clean": [10, 20, 30],
    }
    totals = {}
    for name, data in samples.items():
        print("[%s]" % name)
        print(format_report(data))
        print("")
        totals[name] = len(remove_duplicates(data))

    widest = max(len(name) for name in totals)
    for name, size in totals.items():
        print("%-*s -> %d unique" % (widest, name, size))


if __name__ == "__main__":
    main()

