OPERATIONS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}


def simple_calculator(num1, operator, num2):
    """Apply one of +, -, *, / to two numbers; 'Error' on division by zero."""
    if operator not in OPERATIONS.keys():
        raise ValueError("unsupported operator: %r" % (operator,))
    if operator == '/' and num2 == 0:
        return 'Error'
    return OPERATIONS[operator](num1, num2)


def to_number(text):
    """Convert a numeric token to int when possible, otherwise to float."""
    if '.' in text or 'e' in text.lower():
        return float(text)
    return int(text)


def parse_expression(text):
    """Split '12 * -3' into (12, '*', -3)."""
    cleaned = text.replace(' ', '')
    for i in range(1, len(cleaned)):
        if cleaned[i] in OPERATIONS.keys():
            return to_number(cleaned[:i]), cleaned[i], to_number(cleaned[i + 1:])
    raise ValueError("no operator found in %r" % (text,))


def evaluate_all(expressions):
    """Evaluate textual expressions into a mapping of text to result."""
    results = {}
    for text in expressions:
        num1, operator, num2 = parse_expression(text)
        results[text] = simple_calculator(num1, operator, num2)
    return results


def count_operators(expressions):
    """Tally how often each supported operator is used."""
    counts = {}
    for operator in OPERATIONS.keys():
        counts[operator] = 0
    for text in expressions:
        counts[parse_expression(text)[1]] += 1
    return counts


def format_table(rows):
    """Align rows of equal-length string tuples into padded text lines."""
    widths = []
    for column in range(len(rows[0])):
        widths.append(max(len(row[column]) for row in rows))
    lines = []
    for row in rows:
        cells = [row[i].ljust(widths[i]) for i in range(len(row))]
        lines.append('  '.join(cells).rstrip())
    return lines


def main():
    expressions = ['10 + 5', '10 / 0', '7 - 12', '3 * -4', '9 / 2', '8 / 4']
    results = evaluate_all(expressions)
    rows = [('expression', 'result')]
    for text, value in results.items():
        rows.append((text, str(value)))
    for line in format_table(rows):
        print(line)

    failures = 0
    for value in results.values():
        if value == 'Error':
            failures += 1
    print("\n%d of %d expressions failed" % (failures, len(results)))

    for operator, count in count_operators(expressions).items():
        if count:
            print("operator %s used %d time(s)" % (operator, count))


if __name__ == '__main__':
    main()

