def is_prime(n):
    """Return True if the positive integer n is prime."""
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    if n < 4:
        return n > 1
    if n % 2 == 0:
        return False
    limit = int(n ** 0.5)
    for divisor in xrange(3, limit + 1, 2):
        if n % divisor == 0:
            return False
    return True


def primes_up_to(limit):
    """Return the list of primes not greater than limit using a sieve."""
    if limit < 2:
        return []
    flags = {number: True for number in xrange(2, limit + 1)}
    for number in xrange(2, int(limit ** 0.5) + 1):
        if flags[number]:
            for multiple in xrange(number * number, limit + 1, number):
                flags[multiple] = False
    return [number for number, prime in flags.iteritems() if prime]


def prime_factors(n):
