def tokenize(sentence):
    """Split a sentence into words, dropping surrounding punctuation."""
    punctuation = ".,;:!?\"'()[]{}"
    words = []
    for chunk in sentence.split():
        start, end = 0, len(chunk)
        for i in range(len(chunk)):
            if chunk[i] not in punctuation:
                start = i
                break
        for i in range(len(chunk) - 1, start - 1, -1):
            if chunk[i] not in punctuation:
                end = i + 1
                break
        cleaned = chunk[start:end]
        if cleaned:
            words.append(cleaned)
    return words


def find_longest_word(sentence):
    """Return the first longest word of the sentence, or '' if there is none."""
    words = tokenize(sentence)
    longest = ''
    for i in range(len(words)):
        if len(words[i]) > len(longest):
            longest = words[i]
    return longest


def length_groups(sentence):
    """Map each word length to the list of words having that length."""
    groups = {}
    for word in tokenize(sentence):
        groups.setdefault(len(word), []).append(word)
    return groups


def longest_per_initial(sentence):
    """Map each lower-cased initial letter to the longest word starting with it."""
    best = {}
    for word in tokenize(sentence):
        initial = word[0].lower()
        if len(word) > len(best.get(initial, '')):
            best[initial] = word
    return best


def format_report(sentence):
    groups = length_groups(sentence)
    lines = ['Sentence: %r' % sentence,
             'Longest word: %r' % find_longest_word(sentence)]
    total = 0
    for words in groups.values():
        total += len(words)
    lines.append('Word count: %d' % total)
    if groups:
        widest = max(groups.keys())
        for size in range(1, widest + 1):
            if size in groups:
                lines.append('  %2d: %s' % (size, ', '.join(groups[size])))
    for initial, word in sorted(longest_per_initial(sentence).items()):
        lines.append('  %s -> %s' % (initial, word))
    return '\n'.join(lines)


def main():
    samples = {
        'basic': 'The quick brown fox',
        'greeting': 'Hello world',
        'punctuated': 'Jumped over the lazy dog, twice!',
        'empty': '   ',
    }
    for name in samples.keys():
        print('[%s]' % name)
        print(format_report(samples[name]))
        print()


if __name__ == '__main__':
    main()

