def fibonacci_sequence(n):
    """Return the first n Fibonacci numbers, starting with 0 and 1."""
    if n <= 0:
        return []
    sequence = [0, 1][:n]
    for i in range(2, n):
        sequence.append(sequence[i - 1] + sequence[i - 2])
    return sequence


def digit_frequency(sequence):
    """Count how often each decimal digit appears across the whole sequence."""
    counts = {}
    for value in sequence:
        for digit in str(value):
            counts[digit] = counts.get(digit, 0) + 1
    return counts


def parity_split(sequence):
    """Group the sequence into even and odd members."""
    groups = {"even": [], "odd": []}
    for value in sequence:
        if value % 2 == 0:
            groups["even"].append(value)
        else:
            groups["odd"].append(value)
    return groups


def successive_ratios(sequence):
    """Ratio of each term to its predecessor, skipping division by zero."""
    ratios = {}
    for i in range(1, len(sequence)):
        previous = sequence[i - 1]
        if previous != 0:
            ratios[i] = sequence[i] / previous
    return ratios


def format_report(sequence):
    lines = ["Sequence: " + ", ".join(str(value) for value in sequence)]
    groups = parity_split(sequence)
    for name, members in sorted(groups.items()):
        lines.append("%s terms (%d): %s" % (name, len(members), members))
    frequency = digit_frequency(sequence)
    for digit, count in sorted(frequency.items()):
        lines.append("digit %s appears %d time(s)" % (digit, count))
    total_digits = sum(frequency.values())
    lines.append("total digits written: %d" % total_digits)
    ratios = successive_ratios(sequence)
    for index, ratio in sorted(ratios.items()):
        lines.append("ratio at index %d: %.5f" % (index, ratio))
    return "\n".join(lines)


def main():
    for n in range(1, 6):
        print("fibonacci_sequence(%d) = %s" % (n, fibonacci_sequence(n)))
    print()
    print(format_report(fibonacci_sequence(12)))


if __name__ == "__main__":
    main()

