def read_lines(filepath):
    with open(filepath, 'r') as handle:
        return handle.read().splitlines()


def count_lines_in_file(filepath):
    with open(filepath, 'r') as handle:
        return sum(1 for _ in handle)


def categorize_lines(filepath):
    counts = {'blank': 0, 'comment': 0, 'code': 0}
    for line in read_lines(filepath):
        stripped = line.strip()
        if not stripped:
            counts['blank'] += 1
        elif stripped.startswith('#'):
            counts['comment'] += 1
        else:
            counts['code'] += 1
    return counts


def length_histogram(lengths, bucket_size=20, bucket_count=4):
    buckets = {}
    for index in range(bucket_count):
        buckets[index * bucket_size] = 0
    for length in lengths:
        index = min(length // bucket_size, bucket_count - 1)
        buckets[index * bucket_size] += 1
    return buckets


def format_histogram(buckets):
    rows = []
    for start, count in buckets.items():
        rows.append('{:>4}+ {} ({})'.format(start, '#' * count, count))
    return rows


def numbered_preview(filepath, limit=5):
    lines = read_lines(filepath)
    width = len(str(len(lines)))
    preview = []
    for index in range(min(limit, len(lines))):
        preview.append('{:>{w}} | {}'.format(index + 1, lines[index], w=width))
    return preview


def summarize(filepaths):
    summary = {}
    for path in filepaths:
        stats = {'lines': count_lines_in_file(path)}
        for name, value in categorize_lines(path).items():
            stats[name] = value
        lengths = [len(line) for line in read_lines(path)]
        stats['longest'] = max(lengths) if lengths else 0
        summary[path] = stats
    return summary


def format_summary(summary):
    name_width = max(len(path) for path in summary.keys())
    first_stats = next(iter(summary.values()))
    columns = sorted(first_stats.keys())
    header = 'file'.ljust(name_width) + ''.join(c.rjust(10) for c in columns)
    rows = [header, '-' * len(header)]
    for path, stats in summary.items():
        cells = [str(stats[column]).rjust(10) for column in columns]
        rows.append(path.ljust(name_width) + ''.join(cells))
    grand_total = sum(stats['lines'] for stats in summary.values())
    rows.append('total lines: {}'.format(grand_total))
    return rows


def main():
    import sys
    paths = sys.argv[1:] or [__file__]
    summary = summarize(paths)
    for row in format_summary(summary):
        print(row)
    for path in summary.keys():
        print('\n{}:'.format(path))
        for row in numbered_preview(path):
            print(row)
        lengths = [len(line) for line in read_lines(path)]
        for row in format_histogram(length_histogram(lengths)):
            print(row)


if __name__ == '__main__':
    main()

