def merge_dictionaries(dict1, dict2):
    """Return a new dict with all pairs from both; dict2 wins on shared keys."""
    merged = {}
    for key, value in dict1.items():
        merged[key] = value
    for key, value in dict2.items():
        merged[key] = value
    return merged


def merge_many(dicts):
    """Fold a list of dictionaries left to right, later ones overriding earlier."""
    if not dicts:
        return {}
    result = dicts[0]
    for i in range(1, len(dicts)):
        result = merge_dictionaries(result, dicts[i])
    return result


def find_conflicts(dict1, dict2):
    """Map each shared key to the pair (old value, new value) when they differ."""
    conflicts = {}
    for key in dict1.keys():
        if key in dict2 and dict1[key] != dict2[key]:
            conflicts[key] = (dict1[key], dict2[key])
    return conflicts


def value_totals(merged):
    """Sum the numeric values of a merged dictionary, grouped by type name."""
    totals = {}
    for value in merged.values():
