def validate_email(email):
    if not isinstance(email, str):
        return False

    if '@' not in email or '.' not in email:
        return False

    at_index = -1
    for i in range(len(email)):
        if email[i] == '@':
            at_index = i
            break

    dot_index = -1
    for i in range(len(email)):
        if email[i] == '.':
            dot_index = i
            break

    if not (0 < at_index < dot_index < len(email) - 1):
        return False

    char_counts = {}
    for char_code in range(ord('a'), ord('z') + 1):
        char_counts[chr(char_code)] = 0
    for char_code in range(ord('0'), ord('9') + 1):
        char_counts[chr(char_code)] = 0

    for char in email:
        if char in char_counts.keys():
            char_counts[char] += 1

    valid_chars_found = False
    for count_val in char_counts.values():
        if count_val > 0:
            valid_chars_found = True
            break

    if not valid_chars_found:
        return False

    return True

