import math


def _validate(numbers):
    if len(numbers) == 0:
        raise ValueError("geometric mean is undefined for an empty list")
    for i in range(len(numbers)):
        value = numbers[i]
        if not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (i, value))
        if value <= 0:
            raise ValueError("element %d must be positive, got %r" % (i, value))


def geometric_mean(numbers):
    """Return the Nth root of the product of the N positive values."""
    _validate(numbers)
    log_sum = math.fsum(math.log(numbers[i]) for i in range(len(numbers)))
    return math.exp(log_sum / len(numbers))


def growth_factors(series):
    """Convert a series of measurements into consecutive ratios."""
    _validate(series)
    return [series[i] / series[i - 1] for i in range(1, len(series))]


def average_growth(series):
    """Average growth factor per step, which is a geometric mean of ratios."""
    factors = growth_factors(series)
    if not factors:
        return 1.0
    return geometric_mean(factors)


def summarize(datasets):
    """Map each named series to its geometric mean and average growth."""
    summary = {}
    for name, series in datasets.items():
        summary[name] = {
            "size": len(series),
            "geometric_mean": geometric_mean(series),
            "average_growth": average_growth(series),
        }
    return summary


def overall_mean(summary):
    """Geometric mean of the per-dataset geometric means."""
    means = [stats["geometric_mean"] for stats in summary.values()]
    return geometric_mean(means)


def format_report(summary):
    lines = []
    width = max(len(name) for name in summary.keys())
    for name, stats in summary.items():
        parts = []
        for label, value in stats.items():
            if label == "size":
                parts.append("n=%d" % value)
            else:
                parts.append("%s=%.4f" % (label, value))
        lines.append("%-*s  %s" % (width, name, "  ".join(parts)))
    return "\n".join(lines)


def main():
    datasets = {
        "pair": [2, 8],
        "ones": [1, 1, 1],
        "revenue": [100, 120, 150, 180],
        "population": [1000, 1100, 1210],
    }
    summary = summarize(datasets)
    print(format_report(summary))
    print("combined geometric mean: %.4f" % overall_mean(summary))
    for name in sorted(summary.keys()):
        factors = growth_factors(datasets[name])
        steps = ", ".join("%.3f" % factors[i] for i in range(len(factors)))
        print("%s steps: [%s]" % (name, steps))


if __name__ == "__main__":
    main()

