import math


def circle_area(radius):
    """Return the area of a circle with the given radius."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius ** 2


def area_table(max_radius, step=1):
    """Map each radius 0, step, 2*step, ... up to max_radius to its area."""
    table = {}
    count = int(max_radius / step) + 1
    for i in range(count):
        radius = i * step
        table[radius] = circle_area(radius)
    return table


def annulus_areas(radii):
    """Area of each ring between consecutive radii of a sorted radius list."""
    rings = {}
    for i in range(1, len(radii)):
        inner, outer = radii[i - 1], radii[i]
        rings[(inner, outer)] = circle_area(outer) - circle_area(inner)
    return rings


def total_area(table):
    total = 0.0
    for area in table.values():
        total += area
    return total


def largest_radius(table):
    best = None
    for radius in table.keys():
        if best is None or radius > best:
            best = radius
    return best


def format_table(table):
    lines = []
    for radius, area in table.items():
        lines.append("r = {0:.2f} -> area = {1:.6f}".format(radius, area))
    return lines


def radius_from_area(area, tolerance=1e-12):
    """Recover the radius of a circle from its area by bisection."""
    low, high = 0.0, max(1.0, area)
    while circle_area(high) < area:
        high *= 2
    for _ in range(200):
        mid = (low + high) / 2
        if circle_area(mid) < area:
            low = mid
        else:
            high = mid
        if high - low < tolerance:
            break
    return (low + high) / 2


def main():
    table = area_table(5, step=0.5)
    for line in format_table(table):
        print(line)

    print("unit circle area:", circle_area(1))
    print("zero radius area:", circle_area(0))
    print("largest radius tabulated:", largest_radius(table))
    print("sum of tabulated areas: {0:.6f}".format(total_area(table)))

    rings = annulus_areas([1, 2, 3, 4])
    for bounds, area in rings.items():
        print("ring {0}-{1}: {2:.6f}".format(bounds[0], bounds[1], area))

    for target in [3.141592653589793, 12.566370614359172]:
        print("area {0:.6f} comes from r = {1:.6f}".format(
            target, radius_from_area(target)))


if __name__ == "__main__":
    main()

