def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory


def apply_shipments(inventory, shipments):
    for name, amounts in shipments.items():
        for amount in amounts:
            update_inventory(inventory, name, amount)
    return inventory


def remove_depleted(inventory):
    removed = []
    for name in list(inventory.keys()):
        if inventory[name] <= 0:
            removed.append(name)
            del inventory[name]
    return removed


def total_units(inventory):
    total = 0
    for count in inventory.values():
        total += count
    return total


def low_stock(inventory, threshold):
    names = []
    for name, count in inventory.items():
        if count < threshold:
            names.append(name)
    names.sort()
    return names


def restock_plan(inventory, threshold):
    plan = {}
    for name, count in inventory.items():
        if count < threshold:
            plan[name] = threshold - count
    return plan


def format_report(inventory, threshold):
    width = 0
    for name in inventory.keys():
        if len(name) > width:
            width = len(name)
    lines = []
    flagged = set(low_stock(inventory, threshold))
    for name in sorted(inventory.keys()):
        marker = " (low)" if name in flagged else ""
        lines.append(name.ljust(width) + "  " + str(inventory[name]).rjust(4) + marker)
    lines.append("-" * (width + 6))
    lines.append("TOTAL".ljust(width) + "  " + str(total_units(inventory)).rjust(4))
    return "\n".join(lines)


def main():
    inventory = {'apple': 10, 'banana': 3, 'cherry': 0}
    shipments = {
        'apple': [5, 5],
        'banana': [-3],
        'date': [12],
    }
    apply_shipments(inventory, shipments)

    for name in remove_depleted(inventory):
        print("dropped:", name)

    weekly_picks = [('apple', -4), ('date', -2), ('elderberry', 7)]
    for name, delta in weekly_picks:
        update_inventory(inventory, name, delta)

    print(format_report(inventory, 5))

    for name, needed in sorted(restock_plan(inventory, 5).items()):
        print("order", needed, "more", name)

    counts = {}
    for count in inventory.values():
        counts[count] = counts.get(count, 0) + 1
    for count, items in sorted(counts.items()):
        print("quantity", count, "shared by", items, "item(s)")


if __name__ == "__main__":
    main()

