CATEGORY_LIMITS = {
    "Underweight": 18.5,
    "Normal weight": 25.0,
    "Overweight": 30.0,
    "Obese": float("inf"),
}


def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index rounded to two decimals."""
    if weight_kg <= 0:
        raise ValueError("weight must be positive")
    if height_m <= 0:
        raise ValueError("height must be positive")
    return round(weight_kg / height_m ** 2, 2)


def classify_bmi(bmi):
    """Map a BMI value onto its World Health Organization category."""
    for category, upper_limit in CATEGORY_LIMITS.items():
        if bmi < upper_limit:
            return category
    return "Obese"


def healthy_weight_range(height_m):
    """Return the weight bounds (kg) that keep the BMI in the normal band."""
    limits = list(CATEGORY_LIMITS.values())
    lower = limits[0] * height_m ** 2
    upper = limits[1] * height_m ** 2
    return round(lower, 1), round(upper, 1)


def bmi_chart(height_m, start_kg, stop_kg, step_kg=5):
    """Build a {weight: (bmi, category)} chart for one height."""
    chart = {}
    for weight in range(start_kg, stop_kg + 1, step_kg):
        bmi = calculate_bmi(weight, height_m)
        chart[weight] = (bmi, classify_bmi(bmi))
    return chart


def category_counts(people):
    """Count how many {name: (weight, height)} records fall in each category."""
    counts = {category: 0 for category in CATEGORY_LIMITS.keys()}
    for weight, height in people.values():
        counts[classify_bmi(calculate_bmi(weight, height))] += 1
    return counts


def format_report(people):
    lines = []
    for name, (weight, height) in people.items():
        bmi = calculate_bmi(weight, height)
        low, high = healthy_weight_range(height)
        lines.append(
            "{:<8} {:>6.2f} kg/m^2  {:<14} healthy: {}-{} kg".format(
                name, bmi, classify_bmi(bmi), low, high
            )
        )
    return "\n".join(lines)


def main():
    people = {
        "Ana": (70, 1.75),
        "Bruno": (100, 2.0),
        "Cleo": (48, 1.68),
        "Dario": (95, 1.72),
    }
    print(format_report(people))

    print("\nCategory totals")
    for category, total in category_counts(people).items():
        print("  {:<14} {}".format(category, total))

    print("\nBMI chart for 1.75 m")
    chart = bmi_chart(1.75, 50, 100, 10)
    for weight in chart.keys():
        bmi, category = chart[weight]
        print("  {:>3} kg -> {:>5.2f} ({})".format(weight, bmi, category))


if __name__ == "__main__":
    main()

