import string

WORD_CHARS = set(string.ascii_letters + string.digits + "_")


def extract_hashtags(text):
    """Return every hashtag found in *text*, without the leading '#'."""
    tags = []
    n = len(text)
    for i in range(n):
        if text[i] != "#":
            continue
        if i > 0 and text[i - 1] in WORD_CHARS:
            continue
        end = i + 1
        for j in range(i + 1, n):
            if text[j] not in WORD_CHARS:
                break
            end = j + 1
        if end > i + 1:
            tags.append(text[i + 1:end])
    return tags


def count_hashtags(texts):
    """Count how often each hashtag occurs across a sequence of texts."""
    counts = {}
    for text in texts:
        for tag in extract_hashtags(text):
            key = tag.lower()
            counts[key] = counts.get(key, 0) + 1
    return counts


def group_by_initial(counts):
    """Map the first character of each hashtag to the hashtags starting with it."""
    groups = {}
    for tag in counts.keys():
        groups.setdefault(tag[0], []).append(tag)
    for letter in groups.keys():
        groups[letter].sort()
    return groups


def top_hashtags(counts, limit):
    ranked = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ranked[:limit]


def format_report(counts, limit=3):
    lines = ["total hashtag uses: %d" % sum(counts.values()),
             "distinct hashtags: %d" % len(counts)]
    for tag, times in top_hashtags(counts, limit):
        lines.append("  %-10s %d" % (tag, times))
    for letter, tags in sorted(group_by_initial(counts).items()):
        lines.append("  %s -> %s" % (letter, ", ".join(tags)))
    return "\n".join(lines)


def main():
    posts = [
        "This is a #test with #python.",
        "No hashtags here.",
        "#Python and #pytest make a good #test suite",
        "edge cases: # alone, email@host#tail, #tag_1 and #2fast",
    ]
    for index in range(len(posts)):
        print("post %d: %s" % (index, extract_hashtags(posts[index])))
    counts = count_hashtags(posts)
    print(format_report(counts))
    repeated = {tag: times for tag, times in counts.items() if times > 1}
    print("repeated:", sorted(repeated.keys()))


if __name__ == "__main__":
    main()

