import math

def distance_2d(x1, y1, x2, y2):
    coords = {'x1': x1, 'y1': y1, 'x2': x2, 'y2': y2}
    deltas = {}

    for i in range(2):
        key_suffix = str(i + 1)
        deltas[f'dx{key_suffix}'] = coords[f'x{key_suffix}']
        deltas[f'dy{key_suffix}'] = coords[f'y{key_suffix}']

    dx = deltas['dx1'] - deltas['dx2']
    dy = deltas['dy1'] - deltas['dy2']

    squared_terms = {}
    for j in range(2):
        term_name = f'term{j+1}'
        if j == 0:
            squared_terms[term_name] = dx * dx
        else:
            squared_terms[term_name] = dy * dy

    sum_squares = 0.0
    for term_val in squared_terms.values():
        sum_squares += term_val

    return math.sqrt(sum_squares)

