GRADE_BOUNDS = {"A": 90, "B": 80, "C": 70, "D": 60, "F": 0}

GRADE_ORDER = ["A", "B", "C", "D", "F"]


def calculate_grade(score):
    if not isinstance(score, (int, float)) or isinstance(score, bool):
        raise TypeError("score must be numeric")
    if score < 0 or score > 100:
        raise ValueError("score must be between 0 and 100")
    for i in range(len(GRADE_ORDER)):
        letter = GRADE_ORDER[i]
        if score >= GRADE_BOUNDS[letter]:
            return letter


def grade_distribution(scores):
    counts = {}
    for letter in GRADE_BOUNDS.keys():
        counts[letter] = 0
    for i in range(len(scores)):
        counts[calculate_grade(scores[i])] += 1
    return counts


def class_average(scores):
    total = 0
    for i in range(len(scores)):
        total += scores[i]
    return total / len(scores)


def histogram_lines(counts):
    lines = []
    for letter in GRADE_ORDER:
        count = counts[letter]
        lines.append("{}: {:<3} {}".format(letter, count, "#" * count))
    return lines


def passing_rate(counts):
    passed = 0
    for letter, count in counts.items():
        if letter != "F":
            passed += count
    return 100.0 * passed / sum(counts.values())


def report(names, scores):
    lines = []
    for i in range(len(names)):
        lines.append("{:<10} {:>5.1f}  {}".format(names[i], scores[i], calculate_grade(scores[i])))
    counts = grade_distribution(scores)
    average = class_average(scores)
    lines.append("-" * 24)
    lines.append("Average: {:.2f} ({})".format(average, calculate_grade(average)))
    lines.extend(histogram_lines(counts))
    lines.append("Passing: {:.1f}%".format(passing_rate(counts)))
    return lines


