    """Width needed for each column, counting the header text itself."""
    widths = {}
    for i in range(len(fields)):
        widths[fields[i]] = len(fields[i])
    for record in records:
        for name, value in record.items():
            if len(value) > widths[name]:
                widths[name] = len(value)
    return widths


def format_row(row, widths):
    cells = []
    for name, width in widths.items():
        cells.append(row[name].ljust(width))
    return ' | '.join(cells)


def render_table(records, fields):
    widths = column_widths(records, fields)
    header = {}
    for name in widths.keys():
        header[name] = name
    rules = []
    for width in widths.values():
        rules.append('-' * width)
