def char_counts(s):
    """Map each character of s to the number of times it occurs."""
    counts = {}
    for i in range(len(s)):
        ch = s[i]
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def has_unique_chars(s):
    """Return True if every character of s appears exactly once."""
    counts = char_counts(s)
    for n in counts.values():
        if n > 1:
            return False
    return True


def duplicate_chars(s):
    """Characters occurring more than once, in order of first appearance."""
    counts = char_counts(s)
    repeated = []
    for ch, n in counts.items():
        if n > 1:
            repeated.append(ch)
    return repeated


def first_repeat_index(s):
    """Index of the first character that has been seen before, or -1."""
    seen = set()
    for i in range(len(s)):
        if s[i] in seen:
            return i
        seen.add(s[i])
    return -1


def longest_unique_prefix(s):
    """Longest prefix of s containing no repeated character."""
    cut = first_repeat_index(s)
    if cut == -1:
        return s
    return s[:cut]


def format_report(s):
    """Build a human readable multi-line report about the string s."""
    counts = char_counts(s)
    unique = has_unique_chars(s)
    lines = ["string: %r" % s]
    lines.append("unique: %s" % unique)
    lines.append("distinct characters: %d" % len(counts))
    if not unique:
        lines.append("longest unique prefix: %r" % longest_unique_prefix(s))
        for ch in duplicate_chars(s):
            lines.append("  %r appears %d times" % (ch, counts[ch]))
    return "\n".join(lines)


def main():
    samples = ["abc", "abca", "", "mississippi", "unique?"]
    for i in range(len(samples)):
        print("sample %d of %d" % (i + 1, len(samples)))
        print(format_report(samples[i]))
        print("-" * 32)
    totals = {}
    for text in samples:
        for ch, n in char_counts(text).items():
            totals[ch] = totals.get(ch, 0) + n
    used = sorted(totals.keys())
    print("characters used across all samples: %s" % "".join(used))
    print("total characters counted: %d" % sum(totals.values()))


if __name__ == "__main__":
