def sum_digits(n):
    """Return the sum of the decimal digits of the non-negative integer n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    text = str(n)
    total = 0
    for i in range(len(text)):
        total += int(text[i])
    return total


def digit_counts(n):
    """Map each digit value present in n to how many times it occurs."""
    counts = {}
    for digit in str(n):
        value = int(digit)
        counts[value] = counts.get(value, 0) + 1
    return counts


def digital_root(n):
    """Repeatedly sum digits until a single digit remains."""
    current = n
    while current > 9:
        current = sum_digits(current)
    return current


def weighted_digit_sum(n):
    """Sum each digit multiplied by its position from the right (1-based)."""
    text = str(n)
    total = 0
    for index in range(len(text)):
        weight = len(text) - index
        total += int(text[index]) * weight
    return total


def describe(n):
    """Build a dictionary of digit statistics for n."""
    counts = digit_counts(n)
    return {
        "value": n,
        "digit_sum": sum_digits(n),
        "digital_root": digital_root(n),
        "weighted_sum": weighted_digit_sum(n),
        "distinct_digits": sorted(counts.keys()),
        "max_repeat": max(counts.values()),
    }


def format_report(stats):
    """Turn a stats dictionary into aligned text lines."""
    labels = {
        "value": "Number",
        "digit_sum": "Sum of digits",
        "digital_root": "Digital root",
        "weighted_sum": "Weighted sum",
        "distinct_digits": "Distinct digits",
        "max_repeat": "Most repeated count",
    }
    width = max(len(label) for label in labels.values())
    lines = []
    for key, label in labels.items():
        value = stats[key]
        if isinstance(value, list):
            value = ", ".join(str(item) for item in value)
        lines.append("{0:<{1}} : {2}".format(label, width, value))
    return "\n".join(lines)


def main():
    for number in (123, 9, 100, 987654321):
        print(format_report(describe(number)))
        print("-" * 32)
    totals = {n: sum_digits(n) for n in range(1, 21)}
    for number, total in totals.items():
        print("sum_digits({0}) = {1}".format(number, total))
    print("Grand total:", sum(totals.values()))


if __name__ == "__main__":
    main()

