def is_leap_year(year):
    """Return True if `year` is a leap year in the proleptic Gregorian calendar."""
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def leap_years_in_range(start, end):
    """Return the leap years in the inclusive interval [start, end]."""
    found = []
    for year in range(start, end + 1):
        if is_leap_year(year):
            found.append(year)
    return found


def month_lengths(year):
    """Return a mapping of month number -> number of days for `year`."""
    lengths = {1: 31, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31,
               8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
    lengths[2] = 29 if is_leap_year(year) else 28
    return lengths


def days_in_year(year):
    """Total number of days in `year`, derived from its month lengths."""
    total = 0
    for days in month_lengths(year).values():
        total += days
    return total


def quarter_days(year):
    """Map each quarter (1-4) of `year` to its number of days."""
    quarters = {}
    for month, days in month_lengths(year).items():
        quarter = (month - 1) // 3 + 1
        quarters[quarter] = quarters.get(quarter, 0) + days
    return quarters


def leap_counts_by_century(start, end):
    """Map each century (e.g. 1900 for 1900-1999) to its leap year count."""
    counts = {}
    for year in leap_years_in_range(start, end):
        century = (year // 100) * 100
        counts[century] = counts.get(century, 0) + 1
    return counts


def format_month_table(year):
    """Build a printable two-column table of month numbers and their lengths."""
    lengths = month_lengths(year)
    lines = ["Month lengths for %d:" % year]
    for month in range(1, 13):
        lines.append("  %2d -> %d days" % (month, lengths[month]))
    return "\n".join(lines)


def main():
    for year in [2000, 1900, 2024, 2023, 1600]:
        verdict = "leap" if is_leap_year(year) else "common"
        print("%d is a %s year (%d days)" % (year, verdict, days_in_year(year)))

    print()
    print(format_month_table(2024))

    print()
    quarters = quarter_days(2024)
    for quarter in range(1, 5):
        print("Q%d of 2024: %d days" % (quarter, quarters[quarter]))

    print()
    for century, count in leap_counts_by_century(1800, 2099).items():
        print("%ds: %d leap years" % (century, count))

    print()
    for start in range(1980, 2030, 10):
        decade = leap_years_in_range(start, start + 9)
        print("%d-%d: %s" % (start, start + 9,
                             ", ".join(str(year) for year in decade)))


if __name__ == "__main__":
    main()

