        quarter = (month - 1) // 3 + 1
        quarters[quarter] = quarters.get(quarter, 0) + days
    return quarters


def leap_counts_by_century(start, end):
    """Map each century (e.g. 1900 for 1900-1999) to its leap year count."""
    counts = {}
    for year in leap_years_in_range(start, end):
        century = (year // 100) * 100
        counts[century] = counts.get(century, 0) + 1
    return counts


def format_month_table(year):
    """Build a printable two-column table of month numbers and their lengths."""
    lengths = month_lengths(year)
    lines = ["Month lengths for %d:" % year]
    for month in xrange(1, 13):
        lines.append("  %2d -> %d days" % (month, lengths[month]))
    return "\n".join(lines)


