def multiplication_table(n):
    """Print the n x n multiplication table and return it as a list of lists."""
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    table = []
    for row in range(1, n + 1):
        table.append([row * col for col in range(1, n + 1)])
    for line in format_table(table):
        print(line)
    return table


def column_widths(table):
    """Return the width needed by the widest entry of each column."""
    widths = []
    for col in range(len(table[0])):
        widths.append(max(len(str(row[col])) for row in table))
    return widths


def format_table(table):
    """Render the table as a list of right-aligned text rows."""
    widths = column_widths(table)
    lines = []
    for row in table:
        cells = [str(row[col]).rjust(widths[col]) for col in range(len(row))]
        lines.append(" ".join(cells))
    return lines


def row_totals(table):
    """Map each 1-based row number to the sum of that row."""
    totals = {}
    for index in range(len(table)):
        totals[index + 1] = sum(table[index])
    return totals


def diagonal(table):
    """Return the squares found on the main diagonal."""
    return [table[i][i] for i in range(len(table))]


def report(table):
    """Summarise the table: row sums, grand total, squares, largest row."""
    totals = row_totals(table)
    lines = ["Row sums:"]
    for row_number, total in totals.items():
        lines.append("  row {0}: {1}".format(row_number, total))
    lines.append("Grand total: {0}".format(sum(totals.values())))
    lines.append("Squares: {0}".format(", ".join(str(sq) for sq in diagonal(table))))
    biggest = max(totals.keys(), key=lambda key: totals[key])
    lines.append("Largest row: {0}".format(biggest))
    return "\n".join(lines)


def main(argv):
    sizes = [int(arg) for arg in argv[1:]] or [2, 5]
    for position in range(len(sizes)):
        if position:
            print("")
