BEATS = {
    'rock': 'scissors',
    'paper': 'rock',
    'scissors': 'paper',
}


def normalize(choice):
    """Return a canonical choice name, accepting abbreviations and odd casing."""
    if not isinstance(choice, str):
        raise TypeError('choice must be a string, got %r' % (choice,))
    cleaned = choice.strip().lower()
    for name in BEATS.keys():
        if name == cleaned or name.startswith(cleaned) and cleaned:
            return name
    raise ValueError('unknown choice: %r' % (choice,))


def rock_paper_scissors(player1_choice, player2_choice):
    """Play one round and report the outcome as a sentence."""
    first = normalize(player1_choice)
    second = normalize(player2_choice)
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return 'Player 1 wins!'
    return 'Player 2 wins!'


def play_match(p1_choices, p2_choices):
    """Play as many rounds as both players supplied and tally the results."""
    rounds = min(len(p1_choices), len(p2_choices))
    tally = {'Player 1 wins!': 0, 'Player 2 wins!': 0, "It's a tie!": 0}
    for index in range(rounds):
        outcome = rock_paper_scissors(p1_choices[index], p2_choices[index])
        tally[outcome] += 1
    return tally


def losing_choices():
    """Map each choice to the choices that defeat it."""
    counters = {}
    for winner, loser in BEATS.items():
        counters.setdefault(loser, []).append(winner)
    return counters


def format_tally(tally):
    total = sum(tally.values())
    lines = ['Rounds played: %d' % total]
    for outcome, count in tally.items():
        share = 100.0 * count / total if total else 0.0
        lines.append('  %-16s %2d (%5.1f%%)' % (outcome, count, share))
    return '\n'.join(lines)


def main():
    p1 = ['rock', 'paper', 'Scissors', 'r', 'paper']
    p2 = ['scissors', 'rock', 'scissors', 'paper', 'scissors']
    for index in range(len(p1)):
        print('Round %d: %s vs %s -> %s'
              % (index + 1, p1[index], p2[index],
                 rock_paper_scissors(p1[index], p2[index])))
    print(format_tally(play_match(p1, p2)))
    for choice, winners in losing_choices().items():
        print('%s is beaten by %s' % (choice, ', '.join(winners)))


if __name__ == '__main__':
    main()

