UNIT_ORDER = ('hours', 'minutes', 'seconds')
UNIT_SECONDS = {'hours': 3600, 'minutes': 60, 'seconds': 1}


def split_duration(seconds):
    """Break a second count into a dict of hours, minutes and seconds."""
    remaining = seconds
    parts = {}
    for name in UNIT_ORDER:
        parts[name] = remaining // UNIT_SECONDS[name]
        remaining %= UNIT_SECONDS[name]
    return parts


def seconds_to_hms(seconds):
    """Convert a total number of seconds into 'HH:MM:SS'."""
    if isinstance(seconds, bool) or not isinstance(seconds, int):
        raise TypeError('seconds must be an integer')
    if seconds < 0:
        raise ValueError('seconds must not be negative')
    parts = split_duration(seconds)
    fields = []
    for name in UNIT_ORDER:
        fields.append(str(parts[name]).zfill(2))
    return ':'.join(fields)


def hms_to_seconds(text):
    """Convert 'HH:MM:SS' back into a total number of seconds."""
    fields = text.split(':')
    if len(fields) != len(UNIT_ORDER):
        raise ValueError('expected three colon-separated fields')
    total = 0
    for index in range(len(fields)):
        total += int(fields[index]) * UNIT_SECONDS[UNIT_ORDER[index]]
    return total


def format_table(table):
    """Render a {seconds: 'HH:MM:SS'} mapping as aligned text lines."""
    label_width = 0
    for total in table.keys():
        label_width = max(label_width, len(str(total)))
    lines = []
    for total, text in table.items():
        lines.append('%s s -> %s' % (str(total).rjust(label_width), text))
    return lines


def hour_histogram(table):
    """Count how many durations fall into each 'HH' bucket."""
    buckets = {}
    for text in table.values():
        hour = text.split(':')[0]
        buckets[hour] = buckets.get(hour, 0) + 1
    return buckets


def main():
    samples = [0, 59, 90, 3661, 45296, 86399]
    table = {}
    for total in samples:
        table[total] = seconds_to_hms(total)

    for line in format_table(table):
        print(line)

    for total, text in table.items():
        if hms_to_seconds(text) != total:
            print('round trip failed for %d (%s)' % (total, text))

    buckets = hour_histogram(table)
    print('durations per hour bucket:')
    for hour in sorted(buckets.keys()):
        print('  %s:xx:xx %s' % (hour, '*' * buckets[hour]))
    print('total durations: %d' % sum(buckets.values()))


if __name__ == '__main__':
    main()

