def flatten_deep(nested):
    """Flatten every level of nesting, however deep."""
    flat = []
    for item in nested:
        if isinstance(item, list):
            flat.extend(flatten_deep(item))
        else:
            flat.append(item)
    return flat


def sublist_lengths(list_of_lists):
    """Map each sublist index to the number of items it holds."""
    lengths = {}
    for index in xrange(len(list_of_lists)):
        lengths[index] = len(list_of_lists[index])
    return lengths


def count_values(flat):
    counts = {}
    for value in flat:
        counts[value] = counts.get(value, 0) + 1
    return counts


def repeated_values(counts):
    repeated = []
    for value, count in counts.iteritems():
        if count > 1:
            repeated.append(value)
    return repeated


def position_map(list_of_lists):
    """Map each item to the (row, column) places where it occurs."""
    positions = {}
    for row in xrange(len(list_of_lists)):
        inner = list_of_lists[row]
        for col in xrange(len(inner)):
            positions.setdefault(inner[col], []).append((row, col))
    return positions


def format_report(list_of_lists):
    flat = flatten_list(list_of_lists)
    lengths = sublist_lengths(list_of_lists)
    counts = count_values(flat)
    positions = position_map(list_of_lists)
    lines = ["flattened: %r" % (flat,)]
    lines.append("sublists: %d, items: %d" % (len(lengths), sum(lengths.itervalues())))
    for index in sorted(lengths.iterkeys()):
        lines.append("  [%d] holds %d item(s)" % (index, lengths[index]))
    for value in repeated_values(counts):
        lines.append("  %r appears at %s" % (value, positions[value]))
    deep = flatten_deep(list_of_lists)
    if len(deep) != len(flat):
        lines.append("  nested deeper: %r" % (deep,))
    return "\n".join(lines)


def main():
    samples = [
        [[1, 2], [3, 4, 5]],
        [[]],
        [["a"], ["b", "a"], []],
        [[1, [2, 3]], [4]],
    ]
    for number in xrange(len(samples)):
        print("sample %d" % number)
        print(format_report(samples[number]))
        print()


if __name__ == "__main__":
    main()

