def portfolio_value(stocks, prices):
    """Total market value of a portfolio of {'ticker': quantity}."""
    total = 0
    for ticker, quantity in stocks.items():
        total += quantity * prices[ticker]
    return total


def missing_prices(stocks, prices):
    """Tickers held in the portfolio for which no price is quoted."""
    absent = []
    for ticker in stocks.keys():
        if ticker not in prices:
            absent.append(ticker)
    return sorted(absent)


def priced_portfolio(stocks, prices):
    """Drop holdings that cannot be priced, so the value is well defined."""
    return {t: q for t, q in stocks.items() if t in prices}


def allocation(stocks, prices):
    """Fraction of total value contributed by each holding."""
    total = portfolio_value(stocks, prices)
    if total == 0:
        return {ticker: 0.0 for ticker in stocks.keys()}
    weights = {}
    for ticker, quantity in stocks.items():
        weights[ticker] = quantity * prices[ticker] / total
    return weights


def value_history(stocks, price_history):
    """Portfolio value for each day of a {'ticker': [price, ...]} series."""
    lengths = {len(series) for series in price_history.values()}
    if len(lengths) > 1:
        raise ValueError("price series have differing lengths")
    days = lengths.pop() if lengths else 0
    totals = []
    for day in range(days):
        prices = {t: series[day] for t, series in price_history.items()}
        totals.append(portfolio_value(priced_portfolio(stocks, prices), prices))
    return totals


def format_report(stocks, prices):
    lines = ["ticker   qty      value   weight"]
    weights = allocation(stocks, prices)
    for ticker, weight in sorted(weights.items()):
        quantity = stocks[ticker]
        value = quantity * prices[ticker]
        lines.append("%-8s %4d %10.2f %7.1f%%" % (ticker, quantity, value, 100 * weight))
    lines.append("total %24.2f" % portfolio_value(stocks, prices))
    return "\n".join(lines)


def main():
    stocks = {'AAPL': 10, 'GOOG': 5, 'MSFT': 8}
    prices = {'AAPL': 150, 'GOOG': 1000}
    print(portfolio_value({'AAPL': 10, 'GOOG': 5}, prices))
    print(portfolio_value({}, {}))
    for ticker in missing_prices(stocks, prices):
        print("no quote for %s, excluded" % ticker)
    tradable = priced_portfolio(stocks, prices)
    print(format_report(tradable, prices))
    history = {'AAPL': [150, 152, 149], 'GOOG': [1000, 1010, 1025]}
    totals = value_history(stocks, history)
    for day in range(len(totals)):
        print("day %d: %.2f" % (day + 1, totals[day]))


if __name__ == "__main__":
    main()

