DIGIT_VALUES = {'0': 0, '1': 1}


def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into its decimal value (11)."""
    text = binary_string.strip()
    if not text:
        raise ValueError("binary string must contain at least one digit")
    value = 0
    for i in range(len(text)):
        digit = text[i]
        if digit not in DIGIT_VALUES:
            raise ValueError("invalid binary digit %r at index %d" % (digit, i))
        value = value * 2 + DIGIT_VALUES[digit]
    return value


def digit_counts(binary_string):
    """Count how often each binary digit occurs in the string."""
    counts = {}
    for digit in DIGIT_VALUES.keys():
        counts[digit] = 0
    text = binary_string.strip()
    for i in range(len(text)):
        counts[text[i]] += 1
    return counts


def set_bit_weights(binary_string):
    """Map the index of every '1' to the power of two it contributes."""
    text = binary_string.strip()
    width = len(text)
    weights = {}
    for i in range(width):
        if text[i] == '1':
            weights[i] = 2 ** (width - 1 - i)
    return weights


def convert_all(binary_strings):
    """Convert a sequence of binary strings into a {string: decimal} mapping."""
    results = {}
    for i in range(len(binary_strings)):
        results[binary_strings[i]] = binary_to_decimal(binary_strings[i])
    return results


def summarize(results):
    """Build report lines with the binary strings right-aligned."""
    width = 0
    for text in results.keys():
        width = max(width, len(text))
    lines = []
    for text, decimal in results.items():
        lines.append("%*s -> %d" % (width, text, decimal))
    lines.append("largest decimal value: %d" % max(results.values()))
    return lines


def main():
    samples = ['1', '1011', '0', '11111111', '100000']
    results = convert_all(samples)
    for line in summarize(results):
        print(line)
    for text in results.keys():
        parts = []
        for digit, amount in digit_counts(text).items():
            parts.append("%s=%d" % (digit, amount))
        print("%s digits: %s" % (text, ", ".join(parts)))
    weights = set_bit_weights('1011')
    for index, weight in weights.items():
        print("1011: bit at index %d adds %d" % (index, weight))
    print("sum of weights: %d" % sum(weights.values()))


if __name__ == '__main__':
    main()

