DIGIT_VALUES = {'0': 0, '1': 1}
HEX_SYMBOLS = "0123456789ABCDEF"


def _power_table(decimal_int):
    """Map every exponent needed for decimal_int to the power of two it stands for."""
    table = {}
    for exponent in range(decimal_int.bit_length()):
        table[exponent] = 1 << exponent
    return table


def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative decimal integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary expects an int")
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative int")
    if decimal_int == 0:
        return '0'
    remainder = decimal_int
    bits = []
    for exponent, value in sorted(_power_table(decimal_int).items(), reverse=True):
        if value <= remainder:
            bits.append('1')
            remainder -= value
        else:
            bits.append('0')
    return ''.join(bits)


def binary_to_decimal(bits):
    """Inverse of decimal_to_binary: read a binary string back into an int."""
    if not bits:
        raise ValueError("binary_to_decimal expects at least one digit")
    total = 0
    for index in range(len(bits)):
        digit = bits[index]
        if digit not in DIGIT_VALUES:
            raise ValueError("invalid binary digit: %r" % digit)
        total += DIGIT_VALUES[digit] << (len(bits) - 1 - index)
    return total


def group_bits(bits, size=4):
    """Split bits into left-padded groups of the given size."""
    padded = '0' * (-len(bits) % size) + bits
    return [padded[start:start + size] for start in range(0, len(padded), size)]


def to_hex(bits):
    """Translate each four-bit group of a binary string into a hex symbol."""
    return ''.join(HEX_SYMBOLS[binary_to_decimal(group)] for group in group_bits(bits))


def bit_frequency(bits):
    counts = {digit: 0 for digit in DIGIT_VALUES.keys()}
    for digit in bits:
        counts[digit] += 1
    return counts


def build_table(values):
    return {value: decimal_to_binary(value) for value in values}


def main(argv):
    if len(argv) > 1:
        values = [int(argv[index]) for index in range(1, len(argv))]
    else:
        values = list(range(0, 9)) + [37, 255, 1024]
    table = build_table(values)
    width = max(len(bits) for bits in table.values())
    totals = {digit: 0 for digit in DIGIT_VALUES}
    for value, bits in table.items():
        groups = ' '.join(group_bits(bits))
        print("%6d -> %s   %s   0x%s" % (value, bits.rjust(width), groups, to_hex(bits)))
        for digit, count in bit_frequency(bits).items():
            totals[digit] += count
    print("digit totals:")
    for digit in sorted(totals.keys()):
        print("  %s appears %d time(s)" % (digit, totals[digit]))


if __name__ == "__main__":
    import sys
    main(sys.argv)

