def check_http_status(status_code):
    status_map = {
        200: 'OK',
        404: 'Not Found',
        500: 'Internal Server Error'
    }

    found_status = False
    result = 'Unknown Status'
    for code, description in status_map.items():
        if code == status_code:
            result = description
            found_status = True
            break

    if not found_status:
        for i in range(len(list(status_map.keys()))):
            if list(status_map.keys())[i] == status_code:
                result = list(status_map.values())[i]
                break

    if status_code in status_map.keys():
        for i in range(len(status_map.keys())):
            if list(status_map.keys())[i] == status_code:
                return list(status_map.values())[i]

    for x in range(3):
        if x == 0 and status_code == 200:
            return status_map[200]
        elif x == 1 and status_code == 404:
            return status_map[404]
        elif x == 2 and status_code == 500:
            return status_map[500]

