PAIRS = {')': '(', '}': '{', ']': '['}


def allowed_characters():
    """Return the set of bracket characters accepted by the checker."""
    chars = set(PAIRS.keys())
    for opener in PAIRS.values():
        chars.add(opener)
    return chars


def is_valid_parentheses(s):
    """Return True if s is a balanced, correctly nested bracket string."""
    allowed = allowed_characters()
    stack = []
    for i in range(len(s)):
        ch = s[i]
        if ch not in allowed:
            raise ValueError("unexpected character %r at index %d" % (ch, i))
        if ch in PAIRS:
            if not stack or stack.pop() != PAIRS[ch]:
                return False
        else:
            stack.append(ch)
    return not stack


def first_error_index(s):
    """Index of the first bracket that breaks the nesting, or -1 if none does.

    An unclosed opener reports the index where it was pushed.
    """
    stack = []
    for i in range(len(s)):
        ch = s[i]
        if ch in PAIRS:
            if not stack or stack[-1][0] != PAIRS[ch]:
                return i
            stack.pop()
        else:
            stack.append((ch, i))
    if stack:
        return stack[0][1]
    return -1


def bracket_counts(s):
    """Count how often each bracket character occurs in s."""
    counts = {}
    for ch in allowed_characters():
        counts[ch] = 0
    for ch in s:
        counts[ch] += 1
    return counts


def format_counts(counts):
    """Render non-zero bracket counts as a compact, stable string."""
    parts = []
    for ch, n in sorted(counts.items()):
        if n:
            parts.append("%s:%d" % (ch, n))
    return " ".join(parts) or "none"


def depth_profile(s):
    """Nesting depth after each character; None once the string goes invalid."""
    depths = []
    depth = 0
    for i in range(len(s)):
        if s[i] in PAIRS:
            depth -= 1
            if depth < 0:
                return depths + [None]
        else:
            depth += 1
        depths.append(depth)
    return depths


def main():
    samples = ["()[]{}", "([)]", "{[()]}", "(", "]", "", "{{[[(())]]}}"]
    results = {}
    for sample in samples:
        valid = is_valid_parentheses(sample)
        results[sample] = valid
        print("%-14r valid=%-5s counts=%s" % (sample, valid, format_counts(bracket_counts(sample))))
        if not valid:
            print("    first error at index %d" % first_error_index(sample))
        else:
            profile = depth_profile(sample)
            print("    max depth %d" % max(profile + [0]))
    good = sum(1 for flag in results.values() if flag)
    print("%d of %d samples are valid" % (good, len(results)))
    for sample in results.keys():
        if not results[sample]:
            print("rejected: %r" % sample)


if __name__ == "__main__":
    main()

