import math


def calculate_std_dev(numbers):
    n = len(numbers)
    total = 0.0
    for i in range(n):
        total += numbers[i]
    mean = total / n
    squared_error = 0.0
    for i in range(n):
        diff = numbers[i] - mean
        squared_error += diff * diff
    return math.sqrt(squared_error / (n - 1))


def calculate_mean(numbers):
    total = 0.0
    for i in range(len(numbers)):
        total += numbers[i]
    return total / len(numbers)


def summarize(datasets):
    summary = {}
    for name, numbers in datasets.items():
        summary[name] = {
            "count": len(numbers),
            "mean": calculate_mean(numbers),
            "std_dev": calculate_std_dev(numbers),
        }
    return summary


def z_scores(numbers):
    mean = calculate_mean(numbers)
    std_dev = calculate_std_dev(numbers)
    if std_dev == 0.0:
        return [0.0 for _ in range(len(numbers))]
    scores = []
    for i in range(len(numbers)):
        scores.append((numbers[i] - mean) / std_dev)
    return scores


def find_outliers(datasets, threshold=1.5):
    flagged = {}
    for name in datasets.keys():
        numbers = datasets[name]
        scores = z_scores(numbers)
        extreme = []
        for i in range(len(scores)):
            if abs(scores[i]) > threshold:
                extreme.append(numbers[i])
        if extreme:
            flagged[name] = extreme
    return flagged


def format_summary(summary):
    lines = []
    for name, stats in summary.items():
        lines.append(
            "{:<10} n={:<3} mean={:>8.3f} sd={:>8.3f}".format(
                name, stats["count"], stats["mean"], stats["std_dev"]
            )
        )
    return "\n".join(lines)


def main():
    datasets = {
        "ramp": [1, 2, 3, 4, 5],
        "flat": [10, 10, 10],
        "mixed": [4, 8, 15, 16, 23, 42],
    }
    summary = summarize(datasets)
    print(format_summary(summary))

    widest = max(summary.values(), key=lambda stats: stats["std_dev"])
    print("largest spread: sd={:.3f}".format(widest["std_dev"]))

    flagged = find_outliers(datasets)
    for name, values in flagged.items():
        print("{} outliers: {}".format(name, values))


if __name__ == "__main__":
    main()

