import random


def roll_dice(num_dice, sides):
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    if sides < 1:
        raise ValueError("sides must be at least 1")
    results = []
    for _ in range(num_dice):
        results.append(random.randint(1, sides))
    return results


def roll_many(num_rolls, num_dice, sides):
    totals = {}
    for _ in range(num_rolls):
        total = sum(roll_dice(num_dice, sides))
        totals[total] = totals.get(total, 0) + 1
    return totals


def expected_range(num_dice, sides):
    return num_dice, num_dice * sides


def relative_frequencies(counts):
    trials = sum(counts.values())
    freqs = {}
    for total, count in counts.items():
        freqs[total] = count / float(trials)
    return freqs


def most_common_total(counts):
    best_total = None
    best_count = -1
    for total, count in counts.items():
        if count > best_count:
            best_total = total
            best_count = count
    return best_total, best_count


def histogram_lines(counts, num_dice, sides, width=40):
    low, high = expected_range(num_dice, sides)
    peak = max(counts.values())
    lines = []
    for total in range(low, high + 1):
        count = counts.get(total, 0)
        bar = "#" * int(round(width * count / float(peak)))
        lines.append("%4d | %-*s %d" % (total, width, bar, count))
    return lines


def main():
    num_dice, sides, trials = 3, 6, 5000
    sample = roll_dice(num_dice, sides)
    print("One roll of %d d%d: %s (sum %d)" % (num_dice, sides, sample, sum(sample)))

    counts = roll_many(trials, num_dice, sides)
    for line in histogram_lines(counts, num_dice, sides):
        print(line)

    top_total, top_count = most_common_total(counts)
    print("Most common total: %d (%d times)" % (top_total, top_count))

    freqs = relative_frequencies(counts)
    for total in sorted(freqs.keys()):
        print("P(total = %2d) = %.4f" % (total, freqs[total]))

    missing = [t for t in range(num_dice, num_dice * sides + 1) if t not in counts]
    if missing:
        print("Totals never rolled:", missing)


if __name__ == "__main__":
    main()

