def normalize(text):
    """Lower-case the text and drop spaces so comparisons ignore both."""
    return "".join(ch.lower() for ch in text if not ch.isspace())


def letter_counts(text):
    """Return a frequency dictionary of the normalized characters of text."""
    counts = {}
    for ch in normalize(text):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def is_anagram(s1, s2):
    """True if s1 and s2 use the same characters with the same frequencies."""
    first = letter_counts(s1)
    second = letter_counts(s2)
    if len(first) != len(second):
        return False
    for ch, n in first.items():
        if second.get(ch, 0) != n:
            return False
    return True


def signature(text):
    """A canonical form: sorted characters, so anagrams share a signature."""
    counts = letter_counts(text)
    parts = []
    for ch in sorted(counts.keys()):
        parts.append(ch * counts[ch])
    return "".join(parts)


def group_anagrams(words):
    """Map each signature to the list of given words sharing it."""
    groups = {}
    for word in words:
        groups.setdefault(signature(word), []).append(word)
    return groups


def anagram_pairs(words):
    """All index pairs (i, j) with i < j whose words are anagrams."""
    pairs = []
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if is_anagram(words[i], words[j]):
                pairs.append((i, j))
    return pairs


def describe_counts(text):
    """Render the letter frequencies of text as 'a:1, b:2' plus a total."""
    counts = letter_counts(text)
    rendered = ", ".join("%s:%d" % (ch, n) for ch, n in sorted(counts.items()))
    total = sum(counts.values())
    return "%s (%d letters)" % (rendered, total)


def main():
    checks = [("listen", "silent"), ("hello", "world"), ("Dormitory", "Dirty Room")]
    for left, right in checks:
        print("%-12s %-12s -> %s" % (left, right, is_anagram(left, right)))

    words = ["stressed", "desserts", "cat", "act", "tac", "dog"]
    for key, group in group_anagrams(words).items():
        if len(group) > 1:
            print("signature %-10s shared by %s" % (key, ", ".join(group)))

    for i, j in anagram_pairs(words):
        print("words %d and %d match: %s / %s" % (i, j, words[i], words[j]))

    for word in ["listen", "Dirty Room"]:
        print("%s -> %s" % (word, describe_counts(word)))


if __name__ == "__main__":
    main()

