def validate_event(start, end):
    """Ensure a single (start, end) pair is a usable integer interval."""
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("event times must be integers")
    if start >= end:
        raise ValueError("event start must come before its end")
    return start, end


def validate_schedule(schedule):
