def product_list(numbers):
    """Return the product of all numbers in the list (1 for an empty list)."""
    product = 1
    for i in range(len(numbers)):
        value = numbers[i]
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("element %d is not a number: %r" % (i, value))
        product *= value
    return product


def running_products(numbers):
    """Return the list of partial products: [n0, n0*n1, n0*n1*n2, ...]."""
    partials = []
    for end in range(1, len(numbers) + 1):
        partials.append(product_list(numbers[:end]))
    return partials


def classify(numbers):
    """Count how many entries are negative, zero or positive."""
    counts = {"negative": 0, "zero": 0, "positive": 0}
    for value in numbers:
        if value < 0:
            counts["negative"] += 1
        elif value == 0:
            counts["zero"] += 1
        else:
            counts["positive"] += 1
    return counts


def predict_sign(numbers):
    """Determine the sign of the product from the counts alone."""
    counts = classify(numbers)
    if counts["zero"]:
        return 0
    return -1 if counts["negative"] % 2 else 1


def products_by_group(groups):
    """Map each group name to the product of its numbers."""
    results = {}
    for name, values in groups.items():
        results[name] = product_list(values)
    return results


def format_counts(counts):
    parts = []
    for label, amount in counts.items():
        parts.append("%s=%d" % (label, amount))
    return ", ".join(parts)


def format_report(groups):
    products = products_by_group(groups)
    lines = []
    for name in products.keys():
        values = groups[name]
        lines.append("%s: %r" % (name, values))
        lines.append("  product   : %r" % products[name])
        lines.append("  sign      : %d" % predict_sign(values))
        lines.append("  counts    : %s" % format_counts(classify(values)))
        lines.append("  partials  : %r" % running_products(values))
    total = 1
    for value in products.values():
        total *= value
    lines.append("product of all group products: %r" % total)
    return "\n".join(lines)


def main():
    groups = {
        "example1": [1, 2, 3, 4],
        "example2": [5, -2, 0],
        "mixed": [2.5, -4, -1, 3],
    }
    print(format_report(groups))


if __name__ == "__main__":
    main()

