def count_uppercase(text):
    """Return the number of uppercase letters in text."""
    count = 0
    for i in range(len(text)):
        if text[i].isupper():
            count += 1
    return count


def uppercase_frequency(text):
    """Map each uppercase letter found in text to how often it occurs."""
    freq = {}
    for i in range(len(text)):
        letter = text[i]
        if letter.isupper():
            freq[letter] = freq.get(letter, 0) + 1
    return freq


def sorted_letters(freq):
    """Return the uppercase letters of freq in alphabetical order."""
    return sorted(freq.keys())


def total_from_frequency(freq):
    """Recompute the uppercase count from a frequency mapping."""
    total = 0
    for occurrences in freq.values():
        total += occurrences
    return total


def most_common_letters(freq):
    """Return every uppercase letter reaching the highest frequency."""
    if not freq:
        return []
    top = max(freq.values())
    winners = []
    for letter, occurrences in freq.items():
        if occurrences == top:
            winners.append(letter)
    return sorted(winners)


def format_frequency(freq):
    """Render a frequency mapping as 'A x2, B x1'."""
    parts = []
    for letter in sorted_letters(freq):
        parts.append("%s x%d" % (letter, freq[letter]))
    return ", ".join(parts) if parts else "(none)"


def report(text):
    """Build a multi-line report about the uppercase letters in text."""
    freq = uppercase_frequency(text)
    lines = ["text: %r" % text,
             "uppercase count: %d" % count_uppercase(text),
             "letters: %s" % format_frequency(freq)]
    if total_from_frequency(freq) > 0:
        lines.append("most common: %s" % ", ".join(most_common_letters(freq)))
    return "\n".join(lines)


def main():
    samples = ["Hello World", "python is fun", "ABBA and CCCC", ""]
    for index in range(len(samples)):
        print("sample %d" % (index + 1))
        print(report(samples[index]))
        print()
    grand_total = {}
    for text in samples:
        for letter, occurrences in uppercase_frequency(text).items():
            grand_total[letter] = grand_total.get(letter, 0) + occurrences
    print("combined: %s" % format_frequency(grand_total))
    print("combined count: %d" % total_from_frequency(grand_total))


if __name__ == "__main__":
    main()

