def validate_numbers(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    if len(numbers) == 0:
        raise ValueError("numbers must not be empty")
    for i in range(len(numbers)):
        value = numbers[i]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element at index %d is not a number: %r" % (i, value))
    return True


def find_smallest(numbers):
    validate_numbers(numbers)
    smallest_number = numbers[0]
    for i in range(1, len(numbers)):
        if numbers[i] < smallest_number:
            smallest_number = numbers[i]
    return smallest_number


def index_of_smallest(numbers):
    smallest_number = find_smallest(numbers)
    for i in range(len(numbers)):
        if numbers[i] == smallest_number:
            return i


def smallest_per_group(groups):
    minima = {}
    for name, values in groups.items():
        minima[name] = find_smallest(values)
    return minima


def overall_smallest(groups):
    minima = smallest_per_group(groups)
    return find_smallest(list(minima.values()))


def groups_reaching_minimum(groups):
    minima = smallest_per_group(groups)
    target = find_smallest(list(minima.values()))
    winners = []
    for name in minima.keys():
        if minima[name] == target:
            winners.append(name)
    return winners


def format_report(groups):
    minima = smallest_per_group(groups)
    width = 0
    for name in minima.keys():
        if len(name) > width:
            width = len(name)
    lines = []
    for name, value in minima.items():
        position = index_of_smallest(groups[name])
        lines.append("%-*s  min=%-8s at index %d" % (width, name, value, position))
    lines.append("overall minimum: %s" % overall_smallest(groups))
    lines.append("groups at overall minimum: %s" % ", ".join(groups_reaching_minimum(groups)))
    return "\n".join(lines)


def main():
    print(find_smallest([5, 2, 8, 1]))
    print(find_smallest([-10, 0, 3]))
    readings = {
        "morning": [5, 2, 8, 1],
        "afternoon": [-10, 0, 3],
        "evening": [7.5, 2.25, -10, 4],
    }
    print(format_report(readings))
    for name, values in readings.items():
        spread = find_smallest(values), max(values)
        print("%s: range %s to %s over %d readings" % (name, spread[0], spread[1], len(values)))


if __name__ == "__main__":
    main()

