def char_frequency(text):
    """Count characters in text, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    frequency_map = {}
    for char in text.lower():
        frequency_map[char] = frequency_map.get(char, 0) + 1
    return frequency_map


def total_characters(frequency_map):
    """Total number of counted characters."""
    total = 0
    for count in frequency_map.values():
        total += count
    return total


def most_common(frequency_map, limit=3):
    """Return up to `limit` (char, count) pairs, highest count first."""
    pairs = []
    for char, count in frequency_map.items():
        pairs.append((char, count))
    pairs.sort(key=lambda pair: (-pair[1], pair[0]))
    return pairs[:limit]


def distinct_letters(frequency_map):
    """Alphabetic keys of the map, in alphabetical order."""
    letters = []
    for char in frequency_map.keys():
        if char.isalpha():
            letters.append(char)
    letters.sort()
    return letters


def histogram_lines(frequency_map, mark="#"):
    """Build one text line per character, showing its count as a bar."""
    lines = []
    for char, count in frequency_map.items():
        label = "' '" if char.isspace() else char
        lines.append("{0} | {1} ({2})".format(label, mark * count, count))
    return lines


def frequency_report(text):
    """Human readable summary of the character frequencies in text."""
    frequency_map = char_frequency(text)
    report = ["Input: {0!r}".format(text),
              "Characters counted: {0}".format(total_characters(frequency_map)),
              "Distinct letters: {0}".format("".join(distinct_letters(frequency_map)))]
    top = most_common(frequency_map)
    for rank in range(1, len(top) + 1):
        char, count = top[rank - 1]
        report.append("#{0} most frequent: {1!r} x {2}".format(rank, char, count))
    report.extend(histogram_lines(frequency_map))
    return "\n".join(report)


def main():
    samples = ["hello", "Python", "Mississippi River"]
    for index in range(len(samples)):
        print(frequency_report(samples[index]))
        if index < len(samples) - 1:
            print("-" * 32)


if __name__ == "__main__":
    main()

