def build_index(items):
    """Map each value to the list of positions where it occurs."""
    index = {}
    for position in range(len(items)):
        index.setdefault(items[position], []).append(position)
    return index


def list_difference(list1, list2):
    """Return the elements of list1 that do not appear in list2."""
    second = build_index(list2)
    difference_list = []
    for position in range(len(list1)):
        value = list1[position]
        if value not in second:
            difference_list.append(value)
    return difference_list


def difference_counts(list1, list2):
    """Count how often each missing value occurs in list1."""
    second = build_index(list2)
    counts = {}
    for value, positions in build_index(list1).items():
        if value not in second:
            counts[value] = len(positions)
    return counts


def shared_elements(list1, list2):
    """Map each shared value to its total number of occurrences."""
    second = build_index(list2)
    shared = {}
    for value, positions in build_index(list1).items():
        if value in second:
            shared[value] = len(positions) + len(second[value])
    return shared


def format_report(list1, list2):
    """Build a multi-line description of the difference between two lists."""
    difference_list = list_difference(list1, list2)
    counts = difference_counts(list1, list2)
    shared = shared_elements(list1, list2)
    lines = ["difference: %r" % (difference_list,)]
    for value, count in counts.items():
        lines.append("  only in first: %r x%d" % (value, count))
    for value in sorted(shared.keys(), key=repr):
        lines.append("  in both: %r" % (value,))
    lines.append("  missing total: %d" % sum(counts.values()))
    lines.append("  shared occurrences: %d" % sum(shared.values()))
    return "\n".join(lines)


def main():
    cases = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [2]),
        ([], [7, 8]),
    ]
    for number in range(len(cases)):
        first, second = cases[number]
        print("case %d: %r vs %r" % (number + 1, first, second))
        print(format_report(first, second))
        print("")


if __name__ == "__main__":
    main()

