def nth_fibonacci(n):
    """Return the nth Fibonacci number, with the sequence starting 0, 1, 1, 2, ..."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    previous, current = 0, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous


def fibonacci_table(limit):
    """Build a dict mapping each index 0..limit to its Fibonacci number."""
    table = {0: 0}
    if limit >= 1:
        table[1] = 1
    for index in range(2, limit + 1):
        table[index] = table[index - 1] + table[index - 2]
    return table


def digit_counts(table):
    """Count how many Fibonacci numbers in the table have each digit length."""
    counts = {}
    for number in table.values():
        width = len(str(number))
        counts[width] = counts.get(width, 0) + 1
    return counts


def even_indices(table):
    """Return the sorted indices whose Fibonacci number is even."""
    found = []
    for index, number in table.items():
        if number % 2 == 0:
            found.append(index)
    return sorted(found)


def ratio_series(table):
    """Approximate the golden ratio from consecutive entries of the table."""
    indices = sorted(table.keys())
    ratios = {}
    for position in range(1, len(indices)):
        lower = table[indices[position - 1]]
        if lower:
            ratios[indices[position]] = table[indices[position]] / lower
    return ratios


def format_report(limit):
    lines = ["Fibonacci numbers up to index %d" % limit]
    table = fibonacci_table(limit)
    for index in range(limit + 1):
        lines.append("  F(%d) = %d" % (index, table[index]))
    lines.append("Even-valued indices: %s" % even_indices(table))
    for width, count in sorted(digit_counts(table).items()):
        lines.append("  %d numbers have %d digit(s)" % (count, width))
    ratios = ratio_series(table)
    for index in sorted(ratios.keys())[-3:]:
        lines.append("  F(%d)/F(%d) = %.6f" % (index, index - 1, ratios[index]))
    return "\n".join(lines)


def main():
    print(format_report(12))
    checks = {0: 0, 6: 8, 10: 55}
    for n, expected in checks.items():
        result = nth_fibonacci(n)
        status = "ok" if result == expected else "MISMATCH"
        print("nth_fibonacci(%d) = %d (%s)" % (n, result, status))


if __name__ == "__main__":
    main()

