import io
import sys


def count_file_lines(filepath):
    """Return the number of lines in the file at *filepath*."""
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        return sum(1 for _ in handle)


def classify_lines(filepath):
    """Split the lines of a file into blank, comment and code counts."""
    counts = {"blank": 0, "comment": 0, "code": 0}
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                counts["blank"] += 1
            elif stripped.startswith("#"):
                counts["comment"] += 1
            else:
                counts["code"] += 1
    return counts


def bucket_labels(width, bucket_count):
    """Build a mapping of bucket index -> human readable range label."""
    labels = {}
    for index in range(bucket_count - 1):
        labels[index] = "{0}-{1}".format(index * width, (index + 1) * width - 1)
    labels[bucket_count - 1] = "{0}+".format((bucket_count - 1) * width)
    return labels


def length_buckets(filepath, width=20, bucket_count=5):
    """Count lines per length bucket, keyed by bucket index."""
    buckets = {index: 0 for index in range(bucket_count)}
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            length = len(line.rstrip("\r\n"))
            buckets[min(length // width, bucket_count - 1)] += 1
    return buckets


def format_counts(counts):
    """Render a name -> number mapping as aligned "name: value" rows."""
    width = max(len(name) for name in counts.keys())
