import io
import sys


def count_file_lines(filepath):
    """Return the number of lines in the file at *filepath*."""
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        return sum(1 for _ in handle)


def classify_lines(filepath):
    """Split the lines of a file into blank, comment and code counts."""
    counts = {"blank": 0, "comment": 0, "code": 0}
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                counts["blank"] += 1
            elif stripped.startswith("#"):
                counts["comment"] += 1
            else:
                counts["code"] += 1
    return counts


def bucket_labels(width, bucket_count):
    """Build a mapping of bucket index -> human readable range label."""
    labels = {}
    for index in xrange(bucket_count - 1):
        labels[index] = "{0}-{1}".format(index * width, (index + 1) * width - 1)
    labels[bucket_count - 1] = "{0}+".format((bucket_count - 1) * width)
    return labels


def length_buckets(filepath, width=20, bucket_count=5):
    """Count lines per length bucket, keyed by bucket index."""
    buckets = {index: 0 for index in xrange(bucket_count)}
    with io.open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            length = len(line.rstrip("\r\n"))
            buckets[min(length // width, bucket_count - 1)] += 1
    return buckets


def format_counts(counts):
    """Render a name -> number mapping as aligned "name: value" rows."""
    width = max(len(name) for name in counts.iterkeys())
    return ["{0:<{1}} : {2}".format(name, width, value) for name, value in counts.iteritems()]


def percentages(counts, total):
    """Convert absolute counts into percentages of *total*."""
    if total == 0:
        return {key: 0.0 for key in counts.iterkeys()}
    return {key: 100.0 * value / total for key, value in counts.iteritems()}


def main(argv):
    paths = argv[1:]
    if not paths:
        print("usage: {0} FILE [FILE ...]".format(argv[0]))
        return 1
    totals = {path: count_file_lines(path) for path in paths}
    labels = bucket_labels(20, 5)
    for path, line_count in totals.iteritems():
        print("{0}: {1} lines".format(path, line_count))
        for row in format_counts(classify_lines(path)):
            print("  " + row)
        shares = percentages(length_buckets(path), line_count)
        for index, share in shares.iteritems():
            bar = "#" * int(round(share / 5.0))
            print("  {0:>7} chars {1:5.1f}% {2}".format(labels[index], share, bar))
    if len(paths) > 1:
        print("total lines: {0}".format(sum(totals.itervalues())))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

