def update_dict(dict1, dict2):
    """Return a new dict with dict1's entries overridden/extended by dict2."""
    merged_dict = {}
    for key, value in dict1.items():
        merged_dict[key] = value
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def classify_keys(dict1, dict2):
    """Split dict2's keys into those that overwrite dict1 and those that are new."""
    overwritten = []
    added = []
    for key in dict2.keys():
        if key in dict1:
            overwritten.append(key)
        else:
            added.append(key)
    return overwritten, added


def changed_values(dict1, dict2):
    """Map each overwritten key to its (old, new) value pair."""
    changes = {}
    for key, new_value in dict2.items():
        if key in dict1 and dict1[key] != new_value:
            changes[key] = (dict1[key], new_value)
    return changes


def merge_all(dicts):
    """Fold a sequence of dicts left to right, returning the merged result."""
    if not dicts:
        return {}
    merged_dict = dicts[0]
    for index in range(1, len(dicts)):
        merged_dict = update_dict(merged_dict, dicts[index])
    return merged_dict


def format_table(mapping):
    """Render a mapping as aligned 'key : value' lines."""
    if not mapping:
        return "(empty)"
    width = max(len(str(key)) for key in mapping.keys())
    lines = []
    for key, value in mapping.items():
        lines.append("{0} : {1}".format(str(key).ljust(width), value))
    return "\n".join(lines)


def describe_merge(dict1, dict2):
    """Build a human readable report about merging dict2 into dict1."""
    overwritten, added = classify_keys(dict1, dict2)
    changes = changed_values(dict1, dict2)
    report = ["merged:", format_table(update_dict(dict1, dict2))]
    report.append("overwritten keys: " + ", ".join(str(k) for k in overwritten))
    report.append("new keys: " + ", ".join(str(k) for k in added))
    for key, pair in changes.items():
        report.append("  {0}: {1} -> {2}".format(key, pair[0], pair[1]))
    return "\n".join(report)


def main():
    pairs = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
    ]
    for position in range(len(pairs)):
        first, second = pairs[position]
        print("Example {0}".format(position + 1))
        print(describe_merge(first, second))
        print()

    stages = [{'a': 1}, {'b': 2}, {'a': 9, 'c': 3}]
    combined = merge_all(stages)
    print("merge_all result:")
    print(format_table(combined))
    for key in combined.keys():
        print("final key: {0}".format(key))


if __name__ == "__main__":
    main()

