_MONTH_LENGTHS = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
                  7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}

_MONTH_NAMES = {1: 'January', 2: 'February', 3: 'March', 4: 'April',
                5: 'May', 6: 'June', 7: 'July', 8: 'August',
                9: 'September', 10: 'October', 11: 'November', 12: 'December'}


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return _MONTH_LENGTHS[month]


def parse_date(date_str):
    parts = date_str.split('-')
    expected_lengths = (4, 2, 2)
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    for i in range(3):
        if len(parts[i]) != expected_lengths[i] or not parts[i].isdigit():
            raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
    if month not in _MONTH_LENGTHS:
        raise ValueError("month out of range in %r" % date_str)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError("day out of range in %r" % date_str)
    return year, month, day


def day_number(year, month, day):
    total = 0
    for yr in range(1, year):
        total += 366 if is_leap(yr) else 365
    for mo in range(1, month):
        total += days_in_month(year, mo)
    return total + day


def days_remaining(start_date_str, end_date_str):
    start = day_number(*parse_date(start_date_str))
    end = day_number(*parse_date(end_date_str))
    return end - start


def month_breakdown(start_date_str, end_date_str):
    year, month, day = parse_date(start_date_str)
    cursor = day_number(year, month, day)
    end = day_number(*parse_date(end_date_str))
    breakdown = {}
    while cursor < end:
        next_year, next_month = (year + 1, 1) if month == 12 else (year, month + 1)
        boundary = min(day_number(next_year, next_month, 1), end)
        breakdown['%04d-%02d' % (year, month)] = boundary - cursor
        cursor = boundary
        year, month = next_year, next_month
    return breakdown


def format_breakdown(breakdown):
    lines = []
    for key, count in sorted(breakdown.items()):
        lines.append('%s %-9s %3d days' % (key, _MONTH_NAMES[int(key[5:])], count))
    return lines


def countdown_report(start_date_str, targets):
    lines = []
    for label, target in targets.items():
        lines.append('%-18s %s %6d days' % (label, target, days_remaining(start_date_str, target)))
    return lines


def main():
    print(days_remaining('2023-01-01', '2023-01-05'))
    print(days_remaining('2023-12-31', '2024-01-01'))

    start = '2024-02-20'
    targets = {'end of quarter': '2024-03-31',
               'summer start': '2024-06-21',
               'new year': '2025-01-01'}
    for line in countdown_report(start, targets):
        print(line)

    spread = month_breakdown(start, targets['new year'])
    for line in format_breakdown(spread):
        print(line)
    print('total', sum(spread.values()), 'days')


if __name__ == '__main__':
    main()

