ALPHABET = 'abcdefghijklmnopqrstuvwxyz'

ENGLISH_FREQ = {
    'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7,
    's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0, 'c': 2.8,
    'u': 2.8, 'm': 2.4, 'w': 2.4, 'f': 2.2, 'g': 2.0, 'y': 2.0,
    'p': 1.9, 'b': 1.5, 'v': 1.0, 'k': 0.8, 'j': 0.15, 'x': 0.15,
    'q': 0.10, 'z': 0.07,
}


def build_shift_table(shift):
    """Map each ciphertext letter to its plaintext letter for the given shift."""
    shift %= 26
    table = {}
    for i in range(26):
        table[ALPHABET[i]] = ALPHABET[(i - shift) % 26]
    return table


def decrypt_caesar(text, shift):
    table = build_shift_table(shift)
    decrypted_text = ''
    for ch in text:
        decrypted_text += table.get(ch, ch)
    return decrypted_text


def letter_counts(text):
    counts = {}
    for ch in text:
        if ch in ENGLISH_FREQ:
            counts[ch] = counts.get(ch, 0) + 1
    return counts


def score_english(text):
    """Higher score means the letter mix looks more like ordinary English."""
    counts = letter_counts(text)
    total = sum(counts.values())
    if total == 0:
        return 0.0
    score = 0.0
    for letter, n in counts.items():
        score += ENGLISH_FREQ[letter] * (n / total)
    return score


def guess_shift(text):
    scores = {}
    for shift in range(26):
        scores[shift] = score_english(decrypt_caesar(text, shift))
    return max(scores.keys(), key=lambda shift: scores[shift])


def format_report(text, top=3):
    candidates = {}
    for shift in range(26):
        candidates[shift] = decrypt_caesar(text, shift)
    ranked = sorted(candidates.items(), key=lambda pair: -score_english(pair[1]))
    lines = []
    for shift, plain in ranked[:top]:
        lines.append('shift {:2d}: {}'.format(shift, plain))
    return '\n'.join(lines)


def main():
    known = {'khoor': 3, 'wkhuh': 3, 'jrrgeb': 3}
    for cipher, shift in known.items():
        print('{} -> {}'.format(cipher, decrypt_caesar(cipher, shift)))

    intercepted = 'wkhuh lv d vhfuhw phvvdjh klgghq khuh'
    best = guess_shift(intercepted)
    print('\nbest shift for intercepted text: {}'.format(best))
    print(decrypt_caesar(intercepted, best))
    print('\ntop candidates:')
    print(format_report(intercepted))


if __name__ == '__main__':
    main()

