SCHEMES = {'http://': 80, 'https://': 443}


def split_scheme(url):
    """Return (scheme, remainder) if url starts with a supported scheme, else (None, url)."""
    for scheme in SCHEMES.iterkeys():
        if url.startswith(scheme):
            return scheme, url[len(scheme):]
    return None, url


def has_inner_dot(remainder):
    """True if the part after the scheme contains a '.' that separates two non-empty labels."""
    for i in xrange(1, len(remainder) - 1):
        if remainder[i] == '.' and remainder[i - 1] != '.':
            return True
    return False


def has_illegal_characters(remainder):
    """True if the remainder contains whitespace or control characters."""
    for ch in remainder:
        if ch.isspace() or ord(ch) < 32:
            return True
    return False


def is_valid_url(url):
    if not isinstance(url, str):
        return False
    scheme, remainder = split_scheme(url)
    if scheme is None:
        return False
    if has_illegal_characters(remainder):
        return False
    host = remainder.split('/')[0]
    return has_inner_dot(host)


def default_port(url):
    """Return the conventional port for the url's scheme, or None for unsupported schemes."""
    for scheme, port in SCHEMES.iteritems():
        if url.startswith(scheme):
            return port
    return None


def check_all(urls):
    results = {}
    for url in urls:
        results[url] = is_valid_url(url)
    return results


def summarize(results):
    counts = {'valid': 0, 'invalid': 0}
    for ok in results.itervalues():
        key = 'valid' if ok else 'invalid'
        counts[key] += 1
    return counts


def format_report(results):
    width = max([len(url) for url in results.iterkeys()] + [0])
    lines = []
    for url, ok in results.iteritems():
        port = default_port(url)
        suffix = '' if port is None else ' (port %d)' % port
        lines.append('%-*s %s%s' % (width, url, 'VALID' if ok else 'INVALID', suffix))
    return lines


def main():
    samples = [
        'https://www.example.com',
        'ftp://invalid-url',
        'http://example.org/path/to/page',
        'http://localhost',
        'https://bad host.com',
        'http://.com',
    ]
    results = check_all(samples)
    for line in format_report(results):
        print(line)
    counts = summarize(results)
    for label, total in counts.iteritems():
        print('%s: %d' % (label, total))


if __name__ == '__main__':
    main()

