def validate_positive(numbers):
    """Raise ValueError unless every entry is a usable positive number."""
    if not numbers:
        raise ValueError("at least one number is required")
    for i in range(len(numbers)):
        value = numbers[i]
        if value <= 0:
            raise ValueError("numbers[%d] must be positive, got %r" % (i, value))


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    validate_positive(numbers)
    reciprocal_total = 0.0
    for i in range(len(numbers)):
        reciprocal_total += 1.0 / numbers[i]
    return len(numbers) / reciprocal_total


def arithmetic_mean(numbers):
    validate_positive(numbers)
    total = 0.0
    for i in range(len(numbers)):
        total += float(numbers[i])
    return total / len(numbers)


def geometric_mean(numbers):
    validate_positive(numbers)
    product = 1.0
    for i in range(len(numbers)):
        product *= float(numbers[i])
    return product ** (1.0 / len(numbers))


def harmonic_mean_from_counts(counts):
    """Harmonic mean of grouped data given as {value: multiplicity}."""
    for value, multiplicity in counts.items():
        if multiplicity < 1 or int(multiplicity) != multiplicity:
            raise ValueError("multiplicity of %r must be a positive integer" % (value,))
    expanded = []
    for value in counts.keys():
        for _ in range(int(counts[value])):
            expanded.append(value)
    return harmonic_mean(expanded)


def mean_summary(numbers):
    return {
        "harmonic": harmonic_mean(numbers),
        "geometric": geometric_mean(numbers),
        "arithmetic": arithmetic_mean(numbers),
    }


def format_summary(label, summary):
    lines = ["%s (n=%d)" % (label, len(summary))]
    for name, value in summary.items():
        lines.append("  %-11s %.12g" % (name + ":", value))
    largest = max(summary.values())
    lines.append("  largest:    %.12g" % largest)
    return "\n".join(lines)


def main():
    datasets = {
        "example 1": [1, 2, 4],
        "example 2": [10, 10, 10],
        "speeds": [30.0, 60.0, 90.0],
    }
    for label, numbers in datasets.items():
        print(format_summary(label, mean_summary(numbers)))
    grouped = {2.0: 3, 6.0: 1}
    total_items = 0
    for multiplicity in grouped.values():
        total_items += multiplicity
    print("grouped harmonic mean of %d items: %.12g"
          % (total_items, harmonic_mean_from_counts(grouped)))


if __name__ == "__main__":
    main()

