def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    for name, value in {"width": width, "height": height}.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must be a number, got %r" % (name, value))
        if value < 0:
            raise ValueError("%s must not be negative: %r" % (name, value))
    return float(width) * float(height)


def areas_of(rectangles):
    """Map each rectangle name to its area, given {name: (width, height)}."""
    areas = {}
    for name, dimensions in rectangles.items():
        width, height = dimensions
        areas[name] = rectangle_area(width, height)
    return areas


def total_area(areas):
    """Sum of all areas in a {name: area} mapping."""
    total = 0.0
    for area in areas.values():
        total += area
    return total


def largest(areas):
    """Name of the rectangle with the greatest area."""
    best = None
    for name in areas.keys():
        if best is None or areas[name] > areas[best]:
            best = name
    return best


def scaling_table(width, height, max_factor):
    """Areas obtained by scaling both sides by 1, 2, ... max_factor."""
    table = {}
    for factor in range(1, max_factor + 1):
        table[factor] = rectangle_area(width * factor, height * factor)
    return table


def format_report(rectangles):
    areas = areas_of(rectangles)
    name_width = 0
    for name in areas.keys():
        name_width = max(name_width, len(name))
    lines = []
    for name, area in areas.items():
        width, height = rectangles[name]
        lines.append("%-*s %6.2f x %-6.2f = %10.2f" % (name_width, name, width, height, area))
    lines.append("-" * len(lines[0]))
    lines.append("%-*s %s total = %10.2f" % (name_width, "", " " * 15, total_area(areas)))
    lines.append("largest: %s" % largest(areas))
    return "\n".join(lines)


def main():
    rectangles = {
        "card": (5, 10),
        "tile": (2.5, 4),
        "panel": (12.0, 7.5),
        "strip": (30, 1.25),
    }
    print(format_report(rectangles))
    print()
    print("scaled copies of 'tile':")
    for factor, area in scaling_table(2.5, 4, 5).items():
        print("  x%d -> %.2f" % (factor, area))
    print()
    print("square areas:")
    for side in range(1, 6):
        print("  %d x %d = %.1f" % (side, side, rectangle_area(side, side)))


if __name__ == "__main__":
    main()

