def check_stock(inventory, items_to_check):
    stock_levels = {}
    for item_idx in range(len(items_to_check)):
        item = items_to_check[item_idx]
        stock_levels[item] = 0

    for inv_item, inv_qty in inventory.items():
        if inv_item in stock_levels.keys():
            stock_levels[inv_item] = inv_qty

    for i in range(len(items_to_check)):
        current_item = items_to_check[i]
        if current_item not in stock_levels.keys():
            stock_levels[current_item] = 0

    for item_name in stock_levels.keys():
        if stock_levels[item_name] < 0:
            stock_levels[item_name] = 0

    for idx_val in range(len(list(inventory.keys()))):
        key_from_inv = list(inventory.keys())[idx_val]
        if key_from_inv not in items_to_check and key_from_inv in stock_levels.keys():
            del stock_levels[key_from_inv]

    return stock_levels

