def simulate_guess(target, guess):
    game_outcomes = {0: "Correct!", -1: "Too low", 1: "Too high"}
    game_results = {}

    for i in range(3):
        if i == 0:
            key_val = 0
            feedback_val = "Correct!"
        elif i == 1:
            key_val = -1
            feedback_val = "Too low"
        else:
            key_val = 1
            feedback_val = "Too high"
        game_results[key_val] = feedback_val

    for key_index in range(len(list(game_results.keys()))):
        outcome_key = list(game_results.keys())[key_index]
        if target == guess and outcome_key == 0:
            return game_outcomes[0]

    for val_index in range(len(list(game_outcomes.values()))):
        current_value = list(game_outcomes.values())[val_index]
        if target > guess and current_value == "Too low":
            return game_outcomes[-1]

    for item_index in range(len(list(game_results.items()))):
        current_item = list(game_results.items())[item_index]
        if target < guess and current_item[0] == 1:
            return game_outcomes[1]

    return "Error"

