GENDER_OFFSETS = {'male': 5.0, 'female': -161.0}

ACTIVITY_FACTORS = {
    'sedentary': 1.2,
    'light': 1.375,
    'moderate': 1.55,
    'active': 1.725,
    'very_active': 1.9,
}


def calculate_bmr(gender, weight_kg, height_cm, age_years):
    key = str(gender).strip().lower()
    if key not in GENDER_OFFSETS:
        valid = ', '.join(sorted(GENDER_OFFSETS.keys()))
        raise ValueError('gender must be one of: ' + valid)
    for name, value in {'weight_kg': weight_kg, 'height_cm': height_cm,
                        'age_years': age_years}.items():
        if value <= 0:
            raise ValueError(name + ' must be positive, got ' + repr(value))
    bmr = 10.0 * weight_kg + 6.25 * height_cm - 5.0 * age_years
    return bmr + GENDER_OFFSETS[key]


def daily_needs(gender, weight_kg, height_cm, age_years):
    bmr = calculate_bmr(gender, weight_kg, height_cm, age_years)
    needs = {}
    for level, factor in ACTIVITY_FACTORS.items():
        needs[level] = bmr * factor
    return needs


def bmr_by_age_range(gender, weight_kg, height_cm, start_age, end_age, step=10):
    table = {}
    for age in range(start_age, end_age + 1, step):
        table[age] = calculate_bmr(gender, weight_kg, height_cm, age)
    return table


def weight_sensitivity(gender, base_weight, height_cm, age_years, steps=3):
    rows = []
    for i in range(-steps, steps + 1):
        weight = base_weight + 5.0 * i
        if weight <= 0:
            continue
        rows.append((weight, calculate_bmr(gender, weight, height_cm, age_years)))
    return rows


def format_needs(needs):
    lines = []
    width = max(len(level) for level in needs.keys())
    for level, calories in needs.items():
        lines.append('  ' + level.ljust(width) + '  ' + format(calories, '.1f') + ' kcal')
    return '\n'.join(lines)


def main():
    people = [
        ('male', 70.0, 175.0, 30),
        ('female', 60.0, 160.0, 25),
    ]
    for index in range(len(people)):
        gender, weight, height, age = people[index]
        bmr = calculate_bmr(gender, weight, height, age)
        print('Person %d: %s, %.0f kg, %.0f cm, %d y -> BMR %.1f kcal/day'
              % (index + 1, gender, weight, height, age, bmr))
        print(format_needs(daily_needs(gender, weight, height, age)))

    print('\nBMR vs age (male, 70 kg, 175 cm):')
    for age, bmr in bmr_by_age_range('male', 70.0, 175.0, 20, 60).items():
        print('  age %d: %.1f kcal/day' % (age, bmr))

    print('\nBMR vs weight (female, 160 cm, 25 y):')
    for weight, bmr in weight_sensitivity('female', 60.0, 160.0, 25):
        print('  %.1f kg: %.1f kcal/day' % (weight, bmr))


if __name__ == '__main__':
    main()

