from string import ascii_letters, digits

VALID_CHARS = set(ascii_letters + digits + "_")


def extract_mentions(text):
    """Return the mention names (without '@') found in text, in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    mentions_list = []
    length = len(text)
    for i in range(length):
        if text[i] != "@":
            continue
        if i > 0 and text[i - 1] in VALID_CHARS:
            continue
        end = i + 1
        while end < length and text[end] in VALID_CHARS:
            end += 1
        if end > i + 1:
            mentions_list.append(text[i + 1:end])
    return mentions_list


def mention_counts(texts):
    """Count how often each mention appears across several messages."""
    counts = {}
    for text in texts:
        for name in extract_mentions(text):
            counts[name] = counts.get(name, 0) + 1
    return counts


def mention_index(texts):
    """Map each mention to the indexes of the messages containing it."""
    index = {}
    for position in range(len(texts)):
        for name in extract_mentions(texts[position]):
            slots = index.setdefault(name, [])
            if position not in slots:
                slots.append(position)
    return index


def total_mentions(counts):
    return sum(counts.values())


def top_mentions(counts, limit):
    ranked = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ranked[:limit]


def format_report(counts, index):
    if not counts:
        return "no mentions found"
    width = max(len(name) for name in counts.keys())
    lines = []
    for name, times in sorted(counts.items()):
        messages = ", ".join(str(pos) for pos in index[name])
        lines.append("@{} {:>3}x  in messages: {}".format(name.ljust(width), times, messages))
    return "\n".join(lines)


def main():
    messages = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "email me at foo@bar.com, thanks @user1!",
        "@user3 and @user1 are talking to @user2",
    ]
    for i in range(len(messages)):
        print("[{}] {} -> {}".format(i, messages[i], extract_mentions(messages[i])))
    counts = mention_counts(messages)
    index = mention_index(messages)
    print()
    print(format_report(counts, index))
    print("total mentions:", total_mentions(counts))
    for name, times in top_mentions(counts, 2):
        print("top: @{} ({})".format(name, times))


if __name__ == "__main__":
    main()

