def manhattan_distance(p1, p2):
    """Return the Manhattan distance between two points in the plane."""
    if len(p1) != 2 or len(p2) != 2:
        raise ValueError("both points must have exactly two coordinates")
    total = 0.0
    for i in range(2):
        total += abs(float(p1[i]) - float(p2[i]))
    return total


def distance_matrix(points):
    """Return a list of rows holding pairwise Manhattan distances."""
    matrix = []
    for i in range(len(points)):
        row = []
        for j in range(len(points)):
            row.append(manhattan_distance(points[i], points[j]))
        matrix.append(row)
    return matrix


def nearest_named_point(target, named_points):
    """Return (name, distance) of the labelled point closest to target."""
    best_name = None
    best_distance = None
    for name, point in named_points.items():
        distance = manhattan_distance(target, point)
        if best_distance is None or distance < best_distance:
            best_name = name
            best_distance = distance
    return best_name, best_distance


def total_route_length(named_points, route):
    """Sum the Manhattan distances along a route given as point names."""
    missing = [name for name in route if name not in named_points]
    if missing:
        raise KeyError("unknown point name(s): " + ", ".join(missing))
    length = 0.0
    for step in range(len(route) - 1):
        length += manhattan_distance(named_points[route[step]],
                                     named_points[route[step + 1]])
    return length


def bounding_box(named_points):
    """Return ((min_x, min_y), (max_x, max_y)) covering all points."""
    xs = [point[0] for point in named_points.values()]
    ys = [point[1] for point in named_points.values()]
    return (min(xs), min(ys)), (max(xs), max(ys))


def format_matrix(labels, matrix):
    """Render a distance matrix as aligned text lines."""
    lines = ["      " + "".join("%6s" % label for label in labels)]
    for i in range(len(labels)):
        cells = "".join("%6.1f" % matrix[i][j] for j in range(len(labels)))
        lines.append("%6s%s" % (labels[i], cells))
    return lines


def main():
    print(manhattan_distance((1, 1), (4, 5)))
    print(manhattan_distance((0, 0), (-2, -3)))

    depots = {"A": (0.0, 0.0), "B": (3.0, 4.0), "C": (-2.0, 1.5), "D": (5.0, -1.0)}
    labels = sorted(depots.keys())
    points = [depots[label] for label in labels]
    for line in format_matrix(labels, distance_matrix(points)):
        print(line)

    for label, point in depots.items():
        print("%s at (%.1f, %.1f)" % (label, point[0], point[1]))

    name, distance = nearest_named_point((1.0, 1.0), depots)
    print("nearest depot to (1.0, 1.0): %s at %.1f" % (name, distance))

    route = ["A", "B", "D", "C"]
    print("route %s length %.1f" % ("->".join(route), total_route_length(depots, route)))

    low, high = bounding_box(depots)
    print("bounding box %s to %s" % (low, high))


if __name__ == "__main__":
    main()

