def cubes_up_to(limit):
    """Return the cubes of every integer from 0 to limit inclusive."""
    if limit < 0:
        raise ValueError("limit must be non-negative")
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def cube_map(limit):
    """Map each integer up to limit onto its cube."""
    cubes = cubes_up_to(limit)
    return {n: cubes[n] for n in range(limit + 1)}


def cube_root_of(value, limit):
    """Return the integer whose cube is value, or None if it is not in range."""
    for root, cube in cube_map(limit).items():
        if cube == value:
            return root
    return None


def cube_sum(limit):
    """Sum of all cubes up to limit."""
    return sum(cube_map(limit).values())


def digit_sums(limit):
    """Map each cube to the sum of its decimal digits."""
    table = {}
    for cube in cube_map(limit).values():
        table[cube] = sum(int(digit) for digit in str(cube))
    return table


def palindromic_cubes(limit):
    """Cubes up to limit whose decimal representation reads the same backwards."""
    found = []
    for cube in cube_map(limit).values():
        text = str(cube)
        if all(text[i] == text[-1 - i] for i in range(len(text) // 2)):
            found.append(cube)
    return sorted(found)


def format_table(limit, width=6):
    """Render n, n**3 and the digit sum of n**3 as aligned text rows."""
    sums = digit_sums(limit)
    header = "n".rjust(width) + "cube".rjust(width) + "digits".rjust(width)
    rows = [header]
    for n, cube in cube_map(limit).items():
        cells = [str(n), str(cube), str(sums[cube])]
        rows.append("".join(cell.rjust(width) for cell in cells))
    return "\n".join(rows)


def main():
    print(cubes_up_to(3))
    print(cubes_up_to(0))
    print(format_table(9))
    print("total:", cube_sum(9))
    print("palindromes:", palindromic_cubes(30))
    for value in (8, 1000, 1001):
        root = cube_root_of(value, 30)
        if root is None:
            print(value, "is not a cube of 0..30")
        else:
            print(value, "=", root, "cubed")
    for cube, total in digit_sums(12).items():
        if total >= 9:
            print("digit-heavy cube:", cube, "->", total)


if __name__ == "__main__":
    main()

