def weighted_average(values, weights):
    """Return the weighted average of *values* using *weights*."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    weighted_sum = 0.0
    weight_total = 0.0
    for i in range(len(values)):
        if weights[i] < 0:
            raise ValueError("weights must not be negative")
        weighted_sum += values[i] * weights[i]
        weight_total += weights[i]
    if weight_total == 0:
        raise ValueError("the sum of the weights must not be zero")
    return weighted_sum / weight_total


def normalized_weights(weight_by_category):
    """Rescale a mapping of weights so that the values sum to 1.0."""
    total = sum(weight_by_category.values())
    if total == 0:
        raise ValueError("the sum of the weights must not be zero")
    return {name: weight / total for name, weight in weight_by_category.items()}


def missing_categories(scores, weight_by_category):
    """Categories that carry weight but have no score for this student."""
    return [name for name in weight_by_category.keys() if name not in scores]


def category_average(scores, weight_by_category):
    """Weighted average of one student's scores over the weighted categories."""
    gaps = missing_categories(scores, weight_by_category)
    if gaps:
        raise KeyError("missing scores for: " + ", ".join(gaps))
    values = []
    weights = []
    for name, weight in weight_by_category.items():
        values.append(scores[name])
        weights.append(weight)
    return weighted_average(values, weights)


def class_report(students, weight_by_category):
    """Build report lines: one per student plus the class average."""
    shares = normalized_weights(weight_by_category)
    columns = list(shares.keys())
    header = "student".ljust(10)
    for i in range(len(columns)):
        header += "{:>10}".format("{} {:.0%}".format(columns[i], shares[columns[i]]))
    lines = [header + "{:>10}".format("final"), "-" * len(header + " " * 10)]
    finals = {}
    for student, scores in students.items():
        finals[student] = category_average(scores, weight_by_category)
        row = student.ljust(10)
        for column in columns:
            row += "{:>10.1f}".format(scores[column])
        lines.append(row + "{:>10.2f}".format(finals[student]))
    head_count = [1.0] * len(finals)
    lines.append("class average: {:.2f}".format(
        weighted_average(list(finals.values()), head_count)))
    return lines


def main():
    print(weighted_average([10, 20, 30], [1, 2, 1]))
    print(weighted_average([5, 10], [0.5, 0.5]))
    weight_by_category = {"homework": 2.0, "midterm": 3.0, "final": 5.0}
    students = {
        "ada": {"homework": 95.0, "midterm": 88.0, "final": 91.0},
        "brian": {"homework": 70.0, "midterm": 82.0, "final": 78.5},
        "clara": {"homework": 88.0, "midterm": 79.0, "final": 94.0},
    }
    for line in class_report(students, weight_by_category):
        print(line)


if __name__ == "__main__":
    main()

