import random

DIGITS = "0123456789"

_rng = random.SystemRandom()


def generate_pin(length):
    """Return a random numeric PIN of the requested length as a string."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an int")
    if length < 1:
        raise ValueError("length must be at least 1")
    pin_chars = []
    for _ in range(length):
        pin_chars.append(_rng.choice(DIGITS))
    return "".join(pin_chars)


def digit_counts(pin):
    """Map each digit character to how many times it occurs in the PIN."""
    counts = {}
    for digit in pin:
        counts[digit] = counts.get(digit, 0) + 1
    return counts


def is_weak(pin):
    """A PIN is weak when it repeats one digit or runs in strict sequence."""
    for count in digit_counts(pin).values():
        if count == len(pin):
            return True
    ascending = True
    descending = True
    for index in range(1, len(pin)):
        step = int(pin[index]) - int(pin[index - 1])
        if step != 1:
            ascending = False
        if step != -1:
            descending = False
    return ascending or descending


def generate_strong_pin(length, attempts=100):
    """Generate a PIN that is not obviously weak, falling back after attempts."""
    pin = generate_pin(length)
    for _ in range(attempts):
        if not is_weak(pin):
            break
        pin = generate_pin(length)
    return pin


def digit_frequency(pins):
    """Total digit usage across a batch of PINs, including unused digits."""
    totals = {}
    for digit in DIGITS:
        totals[digit] = 0
    for pin in pins:
        for digit, count in digit_counts(pin).items():
            totals[digit] += count
    return totals


def format_report(totals):
    """Render the frequency table, most used digits first."""
    lines = []
    grand_total = sum(totals.values())
    for digit, count in sorted(totals.items(), key=lambda item: (-item[1], item[0])):
        share = 100.0 * count / grand_total if grand_total else 0.0
        lines.append("{}: {:>4} ({:5.1f}%)".format(digit, count, share))
    return "\n".join(lines)


def main():
    for length in range(4, 9):
        print("length {} -> {}".format(length, generate_strong_pin(length)))
    batch = [generate_strong_pin(6) for _ in range(200)]
    print(format_report(digit_frequency(batch)))


if __name__ == "__main__":
    main()

