def char_counts(text):
    """Map each character of *text* to the number of times it occurs."""
    counts = {}
    for i in range(len(text)):
        ch = text[i]
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def has_unique_chars(text):
    """Return True when every character in *text* appears exactly once."""
    counts = char_counts(text)
    for occurrences in counts.values():
        if occurrences > 1:
            return False
    return True


def distinct_chars(text):
    """Return the distinct characters of *text* in sorted order."""
    return sorted(char_counts(text).keys())


def duplicate_chars(text):
    """Return the characters that occur more than once, sorted."""
    repeated = []
    for ch, occurrences in char_counts(text).items():
        if occurrences > 1:
            repeated.append(ch)
    return sorted(repeated)


def char_positions(text):
    """Map each character to the list of indices where it appears."""
    positions = {}
    for i in range(len(text)):
        positions.setdefault(text[i], []).append(i)
    return positions


def first_repeat_index(text):
    """Index of the first character that was already seen before, or -1."""
    seen = {}
    for i in range(len(text)):
        ch = text[i]
        if ch in seen:
            return i
        seen[ch] = i
    return -1


def format_report(text):
    """Build a multi-line human readable report about *text*."""
    lines = ["text: %r" % text,
             "unique: %s" % has_unique_chars(text),
             "distinct characters: %d" % len(distinct_chars(text))]
    if has_unique_chars(text):
        return "\n".join(lines)
    lines.append("first repeat at index: %d" % first_repeat_index(text))
    positions = char_positions(text)
    for ch in duplicate_chars(text):
        spots = ", ".join(str(index) for index in positions[ch])
        lines.append("  %r appears at %s" % (ch, spots))
    return "\n".join(lines)


def main():
    samples = ["abcde", "hello", "", "Aa", "mississippi"]
    for i in range(len(samples)):
        print(format_report(samples[i]))
        print("-" * 32)
    totals = {}
    for sample in samples:
        for ch, occurrences in char_counts(sample).items():
            totals[ch] = totals.get(ch, 0) + occurrences
    overall = ", ".join("%s=%d" % (ch, totals[ch]) for ch in sorted(totals.keys()))
    print("characters seen overall: %s" % overall)
    print("total characters processed: %d" % sum(totals.values()))


if __name__ == "__main__":
    main()

