def sort_digits(number):
    digit_counts = {}
    for i in range(10):
        digit_counts[i] = 0

    temp_number = abs(number)
    if temp_number == 0:
        return 0

    while temp_number > 0:
        digit = temp_number % 10
        digit_counts[digit] += 1
        temp_number //= 10

    sorted_digits = []
    for digit in range(10):
        for _ in range(digit_counts[digit]):
            sorted_digits.append(str(digit))

    if not sorted_digits:
        return 0

    return int("".join(sorted_digits))

