def is_divisible_by_3_and_5(number):
    """Return True when number is a multiple of both 3 and 5."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    is_divisible = number % 3 == 0 and number % 5 == 0
    return is_divisible


def classify(number):
    """Label a number by which of 3 and 5 divide it."""
    divisors = {3: number % 3 == 0, 5: number % 5 == 0}
    hits = [d for d, ok in divisors.items() if ok]
    if len(hits) == 2:
        return "both"
    for divisor in divisors.keys():
        if divisor in hits:
            return "only %d" % divisor
    return "neither"


def scan_range(start, stop):
    """Map every integer in [start, stop) to its classification."""
    labels = {}
    for number in range(start, stop):
        labels[number] = classify(number)
    return labels


def tally(labels):
    """Count how often each classification occurs."""
    counts = {"both": 0, "only 3": 0, "only 5": 0, "neither": 0}
    for label in labels.values():
        counts[label] += 1
    return counts


def multiples(limit, count):
    """First `count` positive multiples of 15 not exceeding `limit`."""
    found = []
    for candidate in range(15, limit + 1, 15):
        if len(found) == count:
            break
        if is_divisible_by_3_and_5(candidate):
            found.append(candidate)
    return found


def format_report(counts, total):
    lines = []
    for label, amount in counts.items():
        share = 100.0 * amount / total
        lines.append("%-8s %4d  %5.1f%%" % (label, amount, share))
    return "\n".join(lines)


