    counts = tally(labels)
    print(format_report(counts, len(labels)))

    both = [number for number, label in labels.items() if label == "both"]
    print("multiples of 15 in 1..100:", both)

    print("first five multiples of 15:", multiples(200, 5))

    columns = 10
    for row in range(0, 30, columns):
        marks = []
        for offset in range(columns):
            value = row + offset + 1
            marks.append("X" if is_divisible_by_3_and_5(value) else ".")
        print("".join(marks))


