def validate_records(dict_list, key):
    """Check that every record is a dict containing `key`; return the missing indices."""
    missing = []
    for i in range(len(dict_list)):
        record = dict_list[i]
        if not isinstance(record, dict):
            raise TypeError("element %d is not a dict" % i)
        if key not in record:
            missing.append(i)
    return missing


def sort_dicts_by_key(dict_list, key):
    """Return a new list with the dicts ordered by the value stored under `key`."""
    missing = validate_records(dict_list, key)
    if missing:
        raise KeyError("key %r absent from records %s" % (key, missing))
    return sorted(dict_list, key=lambda record: record[key])


def collect_columns(dict_list):
    """Column names in first-seen order across all records."""
    columns = []
    for record in dict_list:
