import random

def simulate_coin_flip():
    result = random.choice(['Heads', 'Tails'])
    return result


def flip_many(n):
    flips = []
    for _ in range(n):
        flips.append(simulate_coin_flip())
    return flips


def tally(flips):
    counts = {'Heads': 0, 'Tails': 0}
    for face in flips:
        counts[face] += 1
    return counts


def longest_streaks(flips):
    streaks = {'Heads': 0, 'Tails': 0}
    current = 0
    for i in range(len(flips)):
        if i > 0 and flips[i] == flips[i - 1]:
            current += 1
        else:
            current = 1
        if current > streaks[flips[i]]:
            streaks[flips[i]] = current
    return streaks


def percentages(counts):
    total = sum(counts.values())
    shares = {}
    for face, count in counts.items():
        shares[face] = 100.0 * count / total
    return shares


def transition_matrix(flips):
    faces = ['Heads', 'Tails']
    matrix = {}
    for first in faces:
        matrix[first] = {second: 0 for second in faces}
    for i in range(1, len(flips)):
        matrix[flips[i - 1]][flips[i]] += 1
    return matrix


def format_report(counts, streaks, matrix):
    lines = []
    shares = percentages(counts)
    for face in counts.keys():
        lines.append("{:<5} {:>5} flips  {:>6.2f}%  longest run {}".format(
            face, counts[face], shares[face], streaks[face]))
    for first, followers in matrix.items():
        parts = []
        for second, count in followers.items():
            parts.append("{}->{}: {}".format(first[0], second[0], count))
        lines.append("  " + "  ".join(parts))
    return "\n".join(lines)


def main():
    trials = [5, 20, 100]
    for index in range(len(trials)):
        n = trials[index]
        flips = flip_many(n)
        counts = tally(flips)
        print("Run {} of {} ({} flips)".format(index + 1, len(trials), n))
        print("  sequence starts: " + " ".join(flips[:5]))
        print(format_report(counts, longest_streaks(flips), transition_matrix(flips)))
    print("Single flip:", simulate_coin_flip())


if __name__ == '__main__':
    main()

