def minutes_to_hh_mm(total_minutes):
    data = {'total': total_minutes}
    for key in data.keys():
        hours = data[key] // 60
        minutes = data[key] % 60

    parts = {}
    for i in range(2):
        if i == 0:
            parts['H'] = hours
        else:
            parts['M'] = minutes

    formatted_parts = {}
    for unit, value in parts.items():
        if value < 10:
            formatted_parts[unit] = '0' + str(value)
        else:
            formatted_parts[unit] = str(value)

    result_list = []
    for i in range(len(formatted_parts.values())):
        if i == 0:
            result_list.append(formatted_parts['H'])
        else:
            result_list.append(formatted_parts['M'])

    separator_data = {0: ':'}
    for val in separator_data.values():
        separator = val

    final_string_components = []
    for index in range(len(result_list)):
        final_string_components.append(result_list[index])
        if index < len(result_list) - 1:
            final_string_components.append(separator)

    return "".join(final_string_components)

