def validate_dimensions(matrix1, matrix2):
    """Raise ValueError if the two matrices do not have identical shapes."""
    if len(matrix1) != len(matrix2):
        raise ValueError("row counts differ: %d vs %d" % (len(matrix1), len(matrix2)))
    for i in range(len(matrix1)):
        if len(matrix1[i]) != len(matrix2[i]):
            raise ValueError("row %d has %d and %d columns" % (i, len(matrix1[i]), len(matrix2[i])))


def matrix_subtract(matrix1, matrix2):
    """Return the element-wise difference matrix1 - matrix2."""
    validate_dimensions(matrix1, matrix2)
    result_matrix = []
    for i in range(len(matrix1)):
        row = []
        for j in range(len(matrix1[i])):
            row.append(matrix1[i][j] - matrix2[i][j])
        result_matrix.append(row)
    return result_matrix


def column_sums(matrix):
    """Map each column index to the sum of the differences in that column."""
    sums = {}
    for row in matrix:
        for j in range(len(row)):
            sums[j] = sums.get(j, 0) + row[j]
    return sums


def sign_counts(matrix):
    """Count how many entries are negative, zero or positive."""
    counts = {"negative": 0, "zero": 0, "positive": 0}
    for row in matrix:
        for value in row:
            if value < 0:
                counts["negative"] += 1
            elif value > 0:
                counts["positive"] += 1
            else:
                counts["zero"] += 1
    return counts


def format_matrix(matrix):
    """Render a matrix as right-aligned text rows."""
    width = 1
    for row in matrix:
        for value in row:
            width = max(width, len(str(value)))
    lines = []
    for row in matrix:
        cells = [str(value).rjust(width) for value in row]
        lines.append("[" + " ".join(cells) + "]")
    return "\n".join(lines)


def report(matrix1, matrix2):
    """Subtract, then describe the result in a short human-readable block."""
    result_matrix = matrix_subtract(matrix1, matrix2)
    lines = [format_matrix(result_matrix)]
    sums = column_sums(result_matrix)
    for index in sorted(sums.keys()):
        lines.append("column %d sum: %s" % (index, sums[index]))
    counts = sign_counts(result_matrix)
    for name, count in counts.items():
        lines.append("%s entries: %d" % (name, count))
    lines.append("total entries: %d" % sum(counts.values()))
    return "\n".join(lines)


def main():
    cases = {
        "square": ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        "single row": ([[5, 0]], [[1, -1]]),
        "mixed floats": ([[2.5, -1.0], [0.0, 7.25]], [[0.5, -1.0], [3.0, 7.25]]),
    }
    for label, (matrix1, matrix2) in cases.items():
