def validate_input(nested_dict, separator):
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    if not isinstance(separator, str) or separator == "":
        raise ValueError("separator must be a non-empty string")
    for outer_key, value in nested_dict.items():
        if isinstance(value, dict):
            if not isinstance(outer_key, str):
                raise TypeError("keys of nested sections must be strings")
            for inner_key in value.keys():
                if not isinstance(inner_key, str):
                    raise TypeError("inner keys must be strings")
                if isinstance(value[inner_key], dict):
                    raise ValueError("only one level of nesting is supported")


def make_unique(key, taken, separator):
    if key not in taken:
        return key
    for suffix in range(2, len(taken) + 3):
        candidate = "{}{}{}".format(key, separator, suffix)
        if candidate not in taken:
            return candidate


def flatten_dict(nested_dict, separator):
    validate_input(nested_dict, separator)
    flattened_dict = {}
    for outer_key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                joined = "{}{}{}".format(outer_key, separator, inner_key)
                flattened_dict[make_unique(joined, flattened_dict, separator)] = inner_value
        else:
            flattened_dict[make_unique(outer_key, flattened_dict, separator)] = value
    return flattened_dict


def unflatten_dict(flat_dict, separator):
    restored = {}
    for key, value in flat_dict.items():
        parts = key.split(separator, 1)
        if len(parts) == 2:
            restored.setdefault(parts[0], {})[parts[1]] = value
        else:
            restored[key] = value
    return restored


def summarize(flat_dict):
    counts = {}
    for value in flat_dict.values():
        name = type(value).__name__
        counts[name] = counts.get(name, 0) + 1
    return counts


def format_report(flat_dict, separator):
    keys = list(flat_dict.keys())
    width = 0
    for key in keys:
        width = max(width, len(key))
    lines = []
    for index in range(len(keys)):
        key = keys[index]
        lines.append("{:>2}. {}  = {!r}".format(index + 1, key.ljust(width), flat_dict[key]))
    for type_name, count in summarize(flat_dict).items():
        lines.append("   {} value(s) of type {}".format(count, type_name))
    lines.append("   separator used: {!r}".format(separator))
    return "\n".join(lines)


def main():
    samples = [
        ({'a': 1, 'b': {'c': 2, 'd': 3}}, '_'),
        ({'x': {'y': 10}}, '.'),
        ({'cfg': {'host': 'localhost', 'port': 8080}, 'debug': True}, ':'),
    ]
    for position in range(len(samples)):
        nested, separator = samples[position]
        flat = flatten_dict(nested, separator)
        print("sample {}: {}".format(position + 1, flat))
        print(format_report(flat, separator))
        round_trip = unflatten_dict(flat, separator)
        for section, value in round_trip.items():
            if isinstance(value, dict):
                print("   section {} holds {}".format(section, sorted(value.keys())))
        print("   round trip matches input: {}".format(round_trip == nested))


if __name__ == "__main__":
    main()

