def reverse_word(word):
    """Return the characters of a single word in reverse order."""
    chars = []
    for i in range(len(word) - 1, -1, -1):
        chars.append(word[i])
    return ''.join(chars)


def reverse_each_word(sentence):
    """Reverse the characters of each word while keeping the word order."""
    words = sentence.split(' ')
    for i in range(len(words)):
        words[i] = reverse_word(words[i])
    return ' '.join(words)


def letter_counts(sentence):
    """Map each letter of the sentence (lower-cased) to how often it occurs."""
    counts = {}
    for ch in sentence:
        if ch.isalpha():
            key = ch.lower()
            counts[key] = counts.get(key, 0) + 1
    return counts


def format_counts(counts):
    """Render a letter-frequency mapping as 'a: 1, b: 2' in alphabetic order."""
    parts = []
    for letter, amount in sorted(counts.items()):
        parts.append('{}: {}'.format(letter, amount))
    return ', '.join(parts)


def total_letters(counts):
    """Number of alphabetic characters described by a frequency mapping."""
    return sum(counts.values())


def word_lengths(sentence):
    """Map the position of every word in the sentence to its length."""
    words = sentence.split(' ')
    lengths = {}
    for i in range(len(words)):
        lengths[i] = len(words[i])
    return lengths


def symmetric_words(sentence):
    """Map positions to words that read the same after being reversed."""
    words = sentence.split(' ')
    found = {}
    for position, length in word_lengths(sentence).items():
        word = words[position]
        if length > 0 and reverse_word(word) == word:
            found[position] = word
    return found


def describe(sentence):
    """Build a multi-line report about a sentence and its reversed form."""
    counts = letter_counts(sentence)
    lines = ['input   : ' + sentence,
             'reversed: ' + reverse_each_word(sentence),
             'letters : {} ({} distinct)'.format(total_letters(counts), len(counts)),
             'freq    : ' + format_counts(counts),
             'alphabet: ' + ''.join(sorted(counts.keys()))]
    mirrored = symmetric_words(sentence)
    for position in sorted(mirrored.keys()):
        lines.append('word {} is its own reverse: {}'.format(position, mirrored[position]))
    return '\n'.join(lines)


