def validate_transaction(buy_price, sell_price, quantity):
    """Reject inputs that cannot describe a real stock transaction."""
    prices = {"buy_price": buy_price, "sell_price": sell_price}
    for name, value in prices.items():
        if value < 0:
            raise ValueError("{} must not be negative".format(name))
    if quantity <= 0:
        raise ValueError("quantity must be a positive number of shares")


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the profit (positive) or loss (negative) of one transaction."""
    validate_transaction(buy_price, sell_price, quantity)
    return round((sell_price - buy_price) * quantity, 2)


def split_into_lots(quantity, lot_count):
    """Spread a share count over lot_count lots as evenly as possible."""
    if lot_count <= 0:
        raise ValueError("lot_count must be positive")
    base, remainder = divmod(quantity, lot_count)
    return [base + (1 if i < remainder else 0) for i in range(lot_count)]


def lot_profits(buy_price, sell_price, lots):
    """Profit of each lot when the whole position is traded at one price."""
    return [calculate_stock_profit(buy_price, sell_price, size) for size in lots]


def cumulative_profits(profits):
    """Running total of realised profit after each lot is sold."""
    running = []
    total = 0.0
    for i in range(len(profits)):
        total = round(total + profits[i], 2)
        running.append(total)
    return running


def summarize_portfolio(trades):
    """Map every symbol in trades to the profit of its transaction."""
    summary = {}
    for symbol, (buy_price, sell_price, quantity) in trades.items():
        summary[symbol] = calculate_stock_profit(buy_price, sell_price, quantity)
    return summary


def total_profit(summary):
    return round(sum(summary.values()), 2)


def ranked_symbols(summary):
    """Symbols ordered from the biggest gain to the biggest loss."""
    return sorted(summary.keys(), key=lambda symbol: -summary[symbol])


def format_report(summary):
    width = max(len(symbol) for symbol in summary.keys())
    lines = ["{:<{w}}  {:>12}".format("SYMBOL", "P/L", w=width)]
    for symbol in ranked_symbols(summary):
        lines.append("{:<{w}}  {:>12.2f}".format(symbol, summary[symbol], w=width))
    lines.append("{:<{w}}  {:>12.2f}".format("TOTAL", total_profit(summary), w=width))
    return "\n".join(lines)


def main():
    trades = {
        "AAA": (10.0, 12.0, 100),
        "BBB": (15.0, 13.0, 50),
        "CCC": (7.25, 7.90, 400),
    }
    summary = summarize_portfolio(trades)
    print(format_report(summary))

    symbol = ranked_symbols(summary)[0]
    buy_price, sell_price, quantity = trades[symbol]
    lots = split_into_lots(quantity, 4)
    running = cumulative_profits(lot_profits(buy_price, sell_price, lots))
    print("\nStaged exit for {}:".format(symbol))
    for i in range(len(lots)):
        print("  lot {}: {:>4} shares, cumulative P/L {:>9.2f}".format(i + 1, lots[i], running[i]))


if __name__ == "__main__":
    main()

