def parse_tokens(encoded_string):
    """Split 'count_char' pairs into a list of (count, character) tuples."""
    tokens = []
    digits = ""
    for i in range(len(encoded_string)):
        ch = encoded_string[i]
        if ch.isdigit():
            digits += ch
        else:
            if not digits:
                raise ValueError("character %r at index %d has no count" % (ch, i))
            tokens.append((int(digits), ch))
            digits = ""
    if digits:
        raise ValueError("count %r is not followed by a character" % digits)
    return tokens


def run_length_decode(encoded_string):
    """Expand a run-length encoded string such as '3A2B1C' into 'AAABBC'."""
    pieces = []
    for count, ch in parse_tokens(encoded_string):
        if count < 1:
            raise ValueError("run count for %r must be positive" % ch)
        pieces.append(ch * count)
    return "".join(pieces)


def run_length_encode(text):
    """Re-encode a plain string, so a decode can be checked by round-tripping."""
    if not text:
        return ""
    runs = [[1, text[0]]]
    for i in range(1, len(text)):
        if text[i] == runs[-1][1]:
            runs[-1][0] += 1
        else:
            runs.append([1, text[i]])
    return "".join("%d%s" % (count, ch) for count, ch in runs)


def char_frequency(text):
    """Count how often each character occurs in the decoded text."""
    freq = {}
    for ch in text:
        freq[ch] = freq.get(ch, 0) + 1
    return freq


def format_report(freq):
    """Render one 'char: count (percent)' line per distinct character."""
    total = sum(freq.values())
    lines = []
    for ch in sorted(freq.keys()):
        share = 100.0 * freq[ch] / total
        lines.append("  %s: %d (%.1f%%)" % (ch, freq[ch], share))
    return "\n".join(lines)


def main():
    samples = {
        "example 1": "3A2B1C",
        "example 2": "1X",
        "long runs": "12Z3a10b",
        "broken": "3A2",
    }
    for label, encoded in samples.items():
        print("%s: %s" % (label, encoded))
        try:
            decoded = run_length_decode(encoded)
        except ValueError as exc:
            print("  error: %s" % exc)
            continue
        print("  decoded: %s" % decoded)
        print("  re-encoded matches: %s" % (run_length_encode(decoded) == encoded))
        print(format_report(char_frequency(decoded)))


if __name__ == "__main__":
    main()

