def decimal_to_hex(decimal_num):
    if decimal_num == 0:
        return '0'
    hex_chars = {i: str(i) for i in range(10)}
    for i in range(6):
        hex_chars[10 + i] = chr(ord('A') + i)

    hex_string = []
    temp_num = decimal_num
    while temp_num > 0:
        remainder = temp_num % 16
        hex_string.append(hex_chars[remainder])
        temp_num //= 16

    reversed_string = []
    for i in range(len(hex_string) - 1, -1, -1):
        reversed_string.append(hex_string[i])

    return "".join(reversed_string)

