import random

def simulate_dice_sum(num_dice):
    if not isinstance(num_dice, int) or isinstance(num_dice, bool):
        raise TypeError("num_dice must be an int")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    total_sum = 0
    for _ in range(num_dice):
        total_sum += random.randint(1, 6)
    return total_sum


def roll_distribution(num_dice, trials):
    counts = {}
    for outcome in range(num_dice, 6 * num_dice + 1):
        counts[outcome] = 0
    for _ in range(trials):
        total = simulate_dice_sum(num_dice)
        counts[total] += 1
    return counts


def exact_probabilities(num_dice):
    ways = {0: 1}
    for _ in range(num_dice):
        nxt = {}
        for subtotal, count in ways.items():
            for face in range(1, 7):
                nxt[subtotal + face] = nxt.get(subtotal + face, 0) + count
        ways = nxt
    total_ways = sum(ways.values())
    return {outcome: count / total_ways for outcome, count in ways.items()}


def summarize(counts):
    trials = 0
    weighted = 0
    for outcome, count in counts.items():
        trials += count
        weighted += outcome * count
    mean = weighted / trials if trials else 0.0
    best = None
    for outcome in counts.keys():
        if best is None or counts[outcome] > counts[best]:
            best = outcome
    return {"trials": trials, "mean": mean, "mode": best}


def report(num_dice, trials):
    counts = roll_distribution(num_dice, trials)
    expected = exact_probabilities(num_dice)
    stats = summarize(counts)
    lines = ["Rolling %d dice, %d trials" % (num_dice, trials)]
    for key, value in stats.items():
        lines.append("  %-7s %s" % (key + ":", round(value, 3) if isinstance(value, float) else value))
    for outcome, count in counts.items():
        observed = count / trials
        bar = "#" * int(round(observed * 100))
        lines.append("  %3d  %6.3f (exact %6.3f) %s" % (outcome, observed, expected[outcome], bar))
    return "\n".join(lines)


def main():
    random.seed(20260918)
    for num_dice in range(1, 4):
        print(report(num_dice, 2000))
        print()
    single_rolls = [simulate_dice_sum(1) for _ in range(5)]
    print("Five single rolls:", single_rolls)
    print("Sum of two dice:", simulate_dice_sum(2))


if __name__ == "__main__":
    main()

