def count_occurrences(numbers):
    """Build a mapping from each value in *numbers* to how often it occurs."""
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def find_duplicate(numbers):
    """Return the single value that appears twice in *numbers*."""
    counts = count_occurrences(numbers)
    for value, occurrences in counts.items():
        if occurrences == 2:
            return value
    raise ValueError("no duplicated number found")


def missing_values(counts, n):
    """Return the values of 1..n that never appear in the counted data."""
    missing = []
    for candidate in range(1, n + 1):
        if candidate not in counts:
            missing.append(candidate)
    return missing


def validate(numbers):
    """Check that *numbers* holds 1..N with exactly one value twice."""
    counts = count_occurrences(numbers)
    n = len(numbers) - 1
    gaps = missing_values(counts, n)
    if gaps:
        raise ValueError("values absent from 1..%d: %s" % (n, gaps))
    doubled = []
    for value, occurrences in counts.items():
        if occurrences > 2:
            raise ValueError("value %d appears %d times" % (value, occurrences))
        if occurrences == 2:
            doubled.append(value)
    if len(doubled) != 1:
        raise ValueError("expected exactly one duplicate, got %s" % doubled)
    return n


def histogram_lines(counts, n):
    """Render one 'value: stars' line for each value of 1..n."""
    lines = []
    for value in range(1, n + 1):
        lines.append("%3d: %s" % (value, "*" * counts[value]))
    return lines


def total_counted(counts):
    """Sum of all recorded occurrences."""
    total = 0
    for occurrences in counts.values():
        total += occurrences
    return total


def report(numbers):
    """Validate, analyse and describe one input list as a block of text."""
    n = validate(numbers)
    counts = count_occurrences(numbers)
    duplicate = find_duplicate(numbers)
    lines = ["input: %s" % (numbers,),
             "range 1..%d, %d items total" % (n, total_counted(counts)),
             "sum %d, plain 1..%d sums to %d" % (sum(numbers), n,
                                                 sum(range(1, n + 1))),
             "duplicate: %d" % duplicate]
    lines.extend(histogram_lines(counts, n))
    return "\n".join(lines)


def main():
    samples = [[1, 2, 3, 2], [5, 1, 3, 4, 2, 5], [3, 1, 2, 3]]
    for position, sample in enumerate(samples, start=1):
        print("case %d" % position)
        print(report(sample))
        print()


if __name__ == "__main__":
    main()

