def letter_counts(word):
    """Map each letter of *word* (case-insensitive) to how often it occurs."""
    counts = {}
    for letter in word.lower():
        counts[letter] = counts.get(letter, 0) + 1
    return counts


def signature(word):
    """A hashable fingerprint shared by all anagrams of *word*."""
    return tuple(sorted(letter_counts(word).items()))


def group_anagrams(words):
    buckets = {}
    for word in words:
        buckets.setdefault(signature(word), []).append(word)
    return list(buckets.values())


def describe_signature(sig):
    """Render a signature as e.g. 'a1e1t1'."""
    parts = []
    for letter, count in sig:
        parts.append("{}{}".format(letter, count))
    return "".join(parts)


def group_index(groups):
    """Map every word to the number of the group it landed in."""
    index = {}
    for number in range(len(groups)):
        for word in groups[number]:
            index[word] = number
    return index


def size_histogram(groups):
    """How many groups have 1 member, 2 members, ..."""
    histogram = {}
    for group in groups:
        size = len(group)
        histogram[size] = histogram.get(size, 0) + 1
    return histogram


def alphabet_used(groups):
    """Sorted list of the distinct letters appearing anywhere in *groups*."""
    letters = set()
    for group in groups:
        for word in group:
            letters.update(letter_counts(word).keys())
    return sorted(letters)


def report(words):
    groups = group_anagrams(words)
    lines = ["input: {}".format(words)]
    for number in range(len(groups)):
        group = groups[number]
        lines.append("group {}: {} [{}]".format(
            number, group, describe_signature(signature(group[0]))))
    for word, number in group_index(groups).items():
        lines.append("  {} -> group {}".format(word, number))
    for size, how_many in sorted(size_histogram(groups).items()):
        lines.append("  {} group(s) of size {}".format(how_many, size))
    lines.append("letters used: {}".format("".join(alphabet_used(groups))))
    return "\n".join(lines)


def main():
    samples = {
        "example 1": ["eat", "tea", "tan", "ate", "nat", "bat"],
        "example 2": ["a", "b"],
        "mixed case": ["Listen", "Silent", "enlist", "google", "gooegl"],
    }
    for name, words in samples.items():
        print(name)
        print(report(words))
        print()


if __name__ == "__main__":
    main()

