def validate_meeting(meeting):
    if len(meeting) != 2:
        raise ValueError("a meeting needs exactly a start and an end time")
    for i in xrange(2):
        if not isinstance(meeting[i], int):
            raise TypeError("meeting times must be integers")
    if meeting[0] > meeting[1]:
        raise ValueError("meeting start must not be after its end")
    return tuple(meeting)


def has_overlap(meeting1, meeting2):
    start1, end1 = validate_meeting(meeting1)
    start2, end2 = validate_meeting(meeting2)
    return start1 < end2 and start2 < end1


def conflicting_pairs(meetings):
    names = list(meetings.iterkeys())
    pairs = []
    for i in xrange(len(names)):
        for j in xrange(i + 1, len(names)):
            if has_overlap(meetings[names[i]], meetings[names[j]]):
                pairs.append((names[i], names[j]))
    return pairs


def busy_hours(meetings):
    hours = {}
    for name, (start, end) in meetings.iteritems():
        for hour in xrange(start, end):
            hours.setdefault(hour, []).append(name)
    return hours


def free_slots(meetings, day_start, day_end):
    hours = busy_hours(meetings)
    slots = []
    for hour in xrange(day_start, day_end):
        if hour not in hours:
            if slots and slots[-1][1] == hour:
                slots[-1] = (slots[-1][0], hour + 1)
            else:
                slots.append((hour, hour + 1))
    return slots


def total_booked_hours(meetings):
    return sum(end - start for start, end in meetings.itervalues())


def format_report(meetings, day_start, day_end):
    lines = ["Schedule %d:00-%d:00" % (day_start, day_end)]
    for name, (start, end) in meetings.iteritems():
        lines.append("  %-10s %d:00-%d:00" % (name, start, end))
    lines.append("Booked hours: %d" % total_booked_hours(meetings))
    conflicts = conflicting_pairs(meetings)
    if conflicts:
        for first, second in conflicts:
            lines.append("  conflict: %s vs %s" % (first, second))
    else:
        lines.append("  no conflicts")
    for hour, names in sorted(busy_hours(meetings).iteritems()):
        if len(names) > 1:
            lines.append("  %d:00 double booked by %s" % (hour, ", ".join(names)))
    for start, end in free_slots(meetings, day_start, day_end):
        lines.append("  free: %d:00-%d:00" % (start, end))
    return "\n".join(lines)


def main():
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))
    meetings = {
        "standup": (9, 10),
        "design": (9, 11),
        "review": (13, 14),
        "retro": (16, 17),
    }
    print(format_report(meetings, 9, 18))


if __name__ == "__main__":
    main()

