def validate_image(image_matrix):
    """Check that the input is a rectangular matrix of [R, G, B] triples."""
    if not image_matrix or not image_matrix[0]:
        raise ValueError("image must contain at least one pixel")
    width = len(image_matrix[0])
    for y in range(len(image_matrix)):
        row = image_matrix[y]
        if len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (y, len(row), width))
        for x in range(width):
            pixel = row[x]
            if len(pixel) != 3:
                raise ValueError("pixel (%d,%d) does not have 3 channels" % (y, x))
            for c in range(3):
                if not 0 <= pixel[c] <= 255:
                    raise ValueError("channel value out of range at (%d,%d)" % (y, x))


def to_grayscale(image_matrix):
    """Return a new matrix where every pixel is the average of its channels."""
    validate_image(image_matrix)
    grayscale_image = []
    for y in range(len(image_matrix)):
        gray_row = []
        for x in range(len(image_matrix[y])):
            pixel = image_matrix[y][x]
            total = 0
            for c in range(3):
                total += pixel[c]
            gray_row.append(total // 3)
        grayscale_image.append(gray_row)
    return grayscale_image


def histogram(grayscale_image):
    """Map each gray level present in the image to the number of pixels."""
    counts = {}
    for y in range(len(grayscale_image)):
        for x in range(len(grayscale_image[y])):
            level = grayscale_image[y][x]
            counts[level] = counts.get(level, 0) + 1
    return counts


def summarize(counts):
    total = sum(counts.values())
    weighted = 0
    for level, count in counts.items():
        weighted += level * count
    return {
        "pixels": total,
        "mean": round(weighted / total, 2),
        "darkest": min(counts.keys()),
        "brightest": max(counts.keys()),
    }


def band_distribution(counts):
    """Group gray levels into four brightness bands."""
    bands = {"shadow": 0, "midtone": 0, "highlight": 0, "white": 0}
    labels = ["shadow", "midtone", "highlight", "white"]
    for level, count in counts.items():
        bands[labels[min(level // 64, 3)]] += count
    return bands


def to_ascii(grayscale_image, ramp=" .:-=+*#%@"):
    step = 256 / len(ramp)
    lines = []
    for y in range(len(grayscale_image)):
        chars = []
        for x in range(len(grayscale_image[y])):
            chars.append(ramp[int(grayscale_image[y][x] / step)])
        lines.append("".join(chars))
    return lines


def main():
    gradient_row = [[i * 40, i * 40, i * 40] for i in range(6)]
    samples = {
        "flag": [[[255, 0, 0], [0, 255, 0]]],
        "single": [[[10, 20, 30]]],
        "gradient": [gradient_row, gradient_row],
    }
    for name, matrix in samples.items():
        gray = to_grayscale(matrix)
        counts = histogram(gray)
        print("%s -> %s" % (name, gray))
        for key, value in summarize(counts).items():
            print("   %-9s %s" % (key, value))
        for band, count in band_distribution(counts).items():
            print("   band %-9s %d" % (band, count))
        for line in to_ascii(gray):
            print("   |%s|" % line)


if __name__ == "__main__":
    main()

