def extract_numbers(text):
    """Return every digit of `text`, in order, joined into one string."""
    digits = []
    for position in range(len(text)):
        character = text[position]
        if character.isdigit():
            digits.append(character)
    return "".join(digits)


def digit_counts(digits_string):
    """Map each digit character to how often it occurs in `digits_string`."""
    counts = {}
    for value in range(10):
        counts[str(value)] = 0
    for character in digits_string:
        counts[character] += 1
    return counts


def present_digits(counts):
    """Digit characters that actually occurred, in ascending order."""
    found = []
    for digit in counts.keys():
        if counts[digit] > 0:
            found.append(digit)
    return sorted(found)


def weighted_checksum(digits_string):
    """Sum of each digit multiplied by its 1-based position."""
    total = 0
    for index in range(len(digits_string)):
        total += int(digits_string[index]) * (index + 1)
    return total


def group_digits(digits_string, size=3):
    """Split the digit string into dash separated blocks of `size`."""
    blocks = []
    for start in range(0, len(digits_string), size):
        blocks.append(digits_string[start:start + size])
    return "-".join(blocks)


def describe(text):
    """Build a human readable report about the digits inside `text`."""
    digits_string = extract_numbers(text)
    counts = digit_counts(digits_string)
    lines = ["input: %r" % text, "digits: %r" % digits_string]
    if digits_string:
        lines.append("grouped: " + group_digits(digits_string))
        lines.append("checksum: %d" % weighted_checksum(digits_string))
        total = 0
        for occurrences in counts.values():
            total += occurrences
        lines.append("total digits: %d" % total)
        for digit, occurrences in counts.items():
            if occurrences:
                lines.append("  %s appears %d time(s)" % (digit, occurrences))
        lines.append("distinct: " + ", ".join(present_digits(counts)))
    else:
        lines.append("no digits found")
    return "\n".join(lines)


