def is_sorted(numbers):
    """Return True if numbers is in ascending (non-decreasing) order."""
    for i in range(len(numbers) - 1):
        if numbers[i] > numbers[i + 1]:
            return False
    return True


def find_breaks(numbers):
    """Map each index i to the pair (numbers[i], numbers[i+1]) that breaks order."""
    breaks = {}
    for i in range(len(numbers) - 1):
        if numbers[i] > numbers[i + 1]:
            breaks[i] = (numbers[i], numbers[i + 1])
    return breaks


def longest_ascending_run(numbers):
    """Return the length of the longest non-decreasing stretch."""
    if not numbers:
        return 0
    best = 1
    current = 1
    for i in range(1, len(numbers)):
        if numbers[i - 1] <= numbers[i]:
            current += 1
        else:
            current = 1
        if current > best:
            best = current
    return best


def analyse(numbers):
    """Collect the facts about one list into a dictionary."""
    breaks = find_breaks(numbers)
    return {
        "length": len(numbers),
        "ascending": is_sorted(numbers),
        "breaks": breaks,
        "first_break": min(breaks.keys()) if breaks else None,
        "longest_run": longest_ascending_run(numbers),
    }


def describe_breaks(breaks):
    """Turn a break dictionary into readable fragments."""
    parts = []
    for index, (left, right) in breaks.items():
        parts.append("{0}>{1} at index {2}".format(left, right, index))
    return ", ".join(parts)


def format_report(numbers):
    report = analyse(numbers)
    lines = ["{0} -> ascending={1}".format(numbers, report["ascending"])]
    if not report["ascending"]:
        lines.append("  first break at index {0}".format(report["first_break"]))
        lines.append("  breaks: " + describe_breaks(report["breaks"]))
        drops = [right - left for left, right in report["breaks"].values()]
        lines.append("  largest drop: {0}".format(min(drops)))
    lines.append("  longest ascending run: {0}".format(report["longest_run"]))
    return "\n".join(lines)


def main():
    samples = {
        "sorted": [1, 2, 3, 4],
        "unsorted": [1, 3, 2],
        "plateau": [2, 2, 2.5, 7],
        "descending": [9, 5, 4, 1],
        "empty": [],
    }
    for name, numbers in samples.items():
        print(name)
        print(format_report(numbers))
    ordered = {name: is_sorted(numbers) for name, numbers in samples.items()}
    good = [name for name, flag in ordered.items() if flag]
    print("ascending lists: {0}/{1} ({2})".format(
        sum(ordered.values()), len(ordered), ", ".join(good)))


if __name__ == "__main__":
    main()

