    return positions


def word_counts(sentence):
    """Map each lower-cased word to how often it appears in the sentence."""
    counts = {}
    for word, indices in word_positions(sentence).iteritems():
        counts[word] = len(indices)
    return counts


def repeated_words(counts):
    """Words that occur more than once, in alphabetical order."""
    repeats = []
    for word, count in counts.iteritems():
        if count > 1:
            repeats.append(word)
    return sorted(repeats)


def reversed_index_map(sentence):
    """Map the original index of every word to its index after reversing."""
    last = len(sentence.split()) - 1
    mapping = {}
    for index in xrange(last + 1):
        mapping[index] = last - index
    return mapping


def format_report(sentence):
    """Build a multi-line description of a sentence and its reversal."""
    counts = word_counts(sentence)
    lines = ['original: ' + sentence.strip()]
    lines.append('reversed: ' + reverse_sentence_words(sentence))
    lines.append('total words: %d' % sum(counts.itervalues()))
    width = 0
    for word in counts.iterkeys():
        width = max(width, len(word))
    for word in sorted(counts.iterkeys()):
        lines.append('  %-*s %d' % (width, word, counts[word]))
    repeats = repeated_words(counts)
    if repeats:
        lines.append('repeated: ' + ', '.join(repeats))
    moves = []
    for old, new in reversed_index_map(sentence).iteritems():
        moves.append('%d->%d' % (old, new))
    lines.append('moves: ' + ' '.join(moves))
    return '\n'.join(lines)


def main():
    samples = ['hello world', 'python is fun', 'the quick brown fox the end']
    for position in xrange(len(samples)):
        print('sample %d' % (position + 1))
        print(format_report(samples[position]))
        print()


if __name__ == '__main__':
    main()

