def merge_dicts(dict1, dict2):
    """Return a new dict with dict2's values overwriting dict1's on shared keys."""
    merged = {}
    for key, value in dict1.items():
        merged[key] = value
    for key, value in dict2.items():
        merged[key] = value
    return merged


def merge_many(dicts):
    """Merge a sequence of dictionaries left to right."""
    result = {}
    for mapping in dicts:
        result = merge_dicts(result, mapping)
    return result


def overwritten_keys(dict1, dict2):
    """Keys of dict1 whose value is replaced by a different value from dict2."""
    changed = []
    for key in dict1.keys():
        if key in dict2 and dict1[key] != dict2[key]:
            changed.append(key)
    return changed


def added_keys(dict1, dict2):
    """Keys contributed only by dict2."""
    return [key for key in dict2.keys() if key not in dict1]


def describe_merge(dict1, dict2):
    """Build a human readable report about merging dict1 and dict2."""
    merged = merge_dicts(dict1, dict2)
    lines = ["result: " + format_dict(merged)]
    for key in overwritten_keys(dict1, dict2):
        lines.append("overwritten {0}: {1} -> {2}".format(key, dict1[key], dict2[key]))
    for key in added_keys(dict1, dict2):
        lines.append("added {0}: {1}".format(key, dict2[key]))
    total = 0
    for value in merged.values():
        if isinstance(value, (int, float)):
            total += value
    lines.append("numeric total: {0}".format(total))
    return lines


def format_dict(mapping):
    """Render a dict with keys in sorted order for stable output."""
    parts = []
    for key in sorted(mapping.keys(), key=str):
        parts.append("{0!r}: {1!r}".format(key, mapping[key]))
    return "{" + ", ".join(parts) + "}"


def main():
    pairs = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
    ]
    for number in range(len(pairs)):
        first, second = pairs[number]
        print("case {0}".format(number + 1))
        for line in describe_merge(first, second):
            print("  " + line)
    combined = merge_many([second for _first, second in pairs])
    print("combined second dicts: " + format_dict(combined))
    counts = {}
    for first, second in pairs:
        for key in merge_dicts(first, second).keys():
            counts[key] = counts.get(key, 0) + 1
    for key, count in sorted(counts.items()):
        print("key {0} appears in {1} merged result(s)".format(key, count))


if __name__ == "__main__":
    main()

