import random


def roll_die(num_sides):
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an integer")
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    return random.randint(1, num_sides)


def roll_many(num_sides, times):
    return [roll_die(num_sides) for _ in range(times)]


def tally(rolls, num_sides):
    counts = {}
    for face in range(1, num_sides + 1):
        counts[face] = 0
    for value in rolls:
        counts[value] += 1
    return counts


def frequencies(counts):
    total = 0
    for count in counts.values():
        total += count
    shares = {}
    for face, count in counts.items():
        shares[face] = count / total if total else 0.0
    return shares


def most_common_faces(counts):
    best = max(counts.values())
    return [face for face, count in counts.items() if count == best]


def histogram_lines(counts, width=40):
    peak = max(counts.values()) or 1
    lines = []
    for face in counts.keys():
        bar = "#" * int(round(counts[face] * width / peak))
        lines.append("{:>3} | {:<{w}} {}".format(face, bar, counts[face], w=width))
    return lines


def report(num_sides, times):
    rolls = roll_many(num_sides, times)
    counts = tally(rolls, num_sides)
    shares = frequencies(counts)
    print("d{} rolled {} times".format(num_sides, times))
    print("first rolls:", ", ".join(str(value) for value in rolls[:10]))
    for line in histogram_lines(counts):
        print(line)
    for face, share in shares.items():
        print("face {:>3}: {:6.2%}".format(face, share))
    print("most common:", most_common_faces(counts))


def main():
    print("single rolls:")
    for sides in (6, 20):
        print("  d{} ->".format(sides), roll_die(sides))
    for sides, times in {6: 600, 20: 400}.items():
        print()
        report(sides, times)


if __name__ == "__main__":
    main()

