def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """Return True if (px, py) lies inside (or on the border of) the rectangle."""
    left, right = min(x1, x2), max(x1, x2)
    bottom, top = min(y1, y2), max(y1, y2)
    return left <= px <= right and bottom <= py <= top


def classify_points(points, rectangles):
    """Map each rectangle name to the list of points it contains."""
    hits = {}
    for name, box in rectangles.items():
        x1, y1, x2, y2 = box
        hits[name] = [(px, py) for px, py in points
                      if is_point_in_rectangle(px, py, x1, y1, x2, y2)]
    return hits


def count_lattice_points(x1, y1, x2, y2):
    """Count integer points covered by the rectangle."""
    width = abs(x2 - x1) + 1
    height = abs(y2 - y1) + 1
    return width * height


def render_grid(width, height, rectangles):
    """Draw an ASCII map where each rectangle covers its cells with its initial."""
    rows = []
    for y in range(height - 1, -1, -1):
        cells = ['.'] * width
        for name, box in rectangles.items():
            for x in range(width):
                if is_point_in_rectangle(x, y, *box):
                    cells[x] = name[0]
        rows.append(''.join(cells))
    return rows


def describe_coverage(rectangles):
    """Build a short text line per rectangle with its size and point count."""
    lines = []
    for name, (x1, y1, x2, y2) in rectangles.items():
        w = abs(x2 - x1) + 1
        h = abs(y2 - y1) + 1
        lines.append("%s: %dx%d area, %d lattice points"
                     % (name, w, h, count_lattice_points(x1, y1, x2, y2)))
    return lines


def overlap_counts(rectangles, width, height):
    """Count, per cell column index, how many rectangles cover that column."""
    counts = {}
    for x in range(width):
        covered = 0
        for box in rectangles.values():
            if any(is_point_in_rectangle(x, y, *box) for y in range(height)):
                covered += 1
        counts[x] = covered
    return counts


def main():
    rectangles = {"Alpha": (0, 0, 5, 5), "Beta": (4, 1, 8, 3)}
    points = [(3, 3), (6, 2), (0, 0), (5, 5), (9, 9)]

    for px, py in points:
        verdict = is_point_in_rectangle(px, py, 0, 0, 5, 5)
        print("(%d, %d) in Alpha -> %s" % (px, py, verdict))

    hits = classify_points(points, rectangles)
    for name, contained in hits.items():
        print("%s contains %d of %d test points" % (name, len(contained), len(points)))

    for line in describe_coverage(rectangles):
        print(line)

    for row in render_grid(10, 7, rectangles):
        print(row)

    for column, covered in overlap_counts(rectangles, 10, 7).items():
        print("column %d covered by %d rectangle(s)" % (column, covered))

    shared = [p for p in hits["Alpha"] if p in hits["Beta"]]
    print("Shared points:", shared)


if __name__ == "__main__":
    main()

