def validate_numbers(numbers):
    """Check that ``numbers`` is a list holding at least two numeric values."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    for index, item in enumerate(numbers):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("element at index %d is not numeric: %r" % (index, item))
    if len(numbers) < 2:
        raise ValueError("numbers must contain at least two values")


def count_values(numbers):
    """Return a mapping of each value to how often it occurs."""
    counts = {}
    for value in numbers:
        counts[value] = counts.get(value, 0) + 1
    return counts


def find_kth_smallest(numbers, k):
    """Return the k-th smallest distinct value of ``numbers`` (k starts at 1)."""
    validate_numbers(numbers)
    if k < 1:
        raise ValueError("k must be at least 1")
    ordered = sorted(count_values(numbers).keys())
    if len(ordered) < k:
        raise ValueError("numbers contains fewer than %d distinct values" % k)
    return ordered[k - 1]


def find_second_smallest(numbers):
    """Return the second smallest distinct value of ``numbers``."""
    return find_kth_smallest(numbers, 2)


def most_common_value(counts):
    """Return the value with the highest frequency, smallest value winning ties."""
    best = None
    for value, frequency in counts.items():
        if best is None or frequency > counts[best] or (frequency == counts[best] and value < best):
            best = value
    return best


def summarize(numbers):
    """Collect the statistics shown in the report."""
    counts = count_values(numbers)
    depth = min(3, len(counts))
    return {
        "size": len(numbers),
        "distinct": len(counts),
        "second_smallest": find_second_smallest(numbers),
        "lowest": [find_kth_smallest(numbers, k) for k in range(1, depth + 1)],
        "most_common": most_common_value(counts),
    }


def histogram_lines(counts, width=12):
    """Render one bar per distinct value, scaled so the peak fills ``width``."""
    peak = max(counts.values())
    ordered = sorted(counts.keys())
    lines = []
    for position in range(len(ordered)):
        value = ordered[position]
        bars = int(round(counts[value] * float(width) / peak))
        lines.append("  #%-3d %8s %3d %s" % (position + 1, value, counts[value], "#" * bars))
    return lines


def format_report(label, numbers):
    """Build a printable multi-line report for one data set."""
    lines = ["%s: %r" % (label, numbers)]
    for key, value in summarize(numbers).items():
        lines.append("  %-15s %s" % (key, value))
    lines.extend(histogram_lines(count_values(numbers)))
    return "\n".join(lines)


def main():
    datasets = {
        "example 1": [5, 1, 8, 2, 9],
        "example 2": [10, 20, 30, 5],
        "repeated": [3, 3, 7, 7, 1, 1, 1],
        "floats": [2.5, 0.5, 0.5, 4.0],
    }
    for label, numbers in datasets.items():
        print(format_report(label, numbers))
        print()


if __name__ == "__main__":
    main()

