def validate_matrix(matrix):
    """Check that matrix is a rectangular list of lists of numbers."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")
    width = None
    for i in range(len(matrix)):
        row = matrix[i]
        if not isinstance(row, list) or not row:
            raise ValueError("row %d must be a non-empty list" % i)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), width))
        for j in range(width):
            if not isinstance(row[j], (int, float)) or isinstance(row[j], bool):
                raise ValueError("entry (%d, %d) is not a number" % (i, j))
    return len(matrix), width


def transpose_matrix(matrix):
    """Return a new matrix whose rows are the columns of the input."""
    rows, cols = validate_matrix(matrix)
    result = []
    for j in range(cols):
        new_row = []
        for i in range(rows):
            new_row.append(matrix[i][j])
        result.append(new_row)
    return result


def column_widths(matrix):
    """Map each column index to the widest rendered entry in that column."""
    rows, cols = validate_matrix(matrix)
    widths = {}
    for j in range(cols):
        widths[j] = max(len(str(matrix[i][j])) for i in range(rows))
    return widths


def format_matrix(matrix):
    """Render a matrix as aligned text lines."""
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j, width in widths.items():
            cells.append(str(row[j]).rjust(width))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def column_sums(matrix):
    """Map each column index to the sum of its entries, via the transpose."""
    sums = {}
    for j, column in enumerate(transpose_matrix(matrix)):
        sums[j] = sum(column)
    return sums


def main():
    samples = {
        "2x3": [[1, 2, 3], [4, 5, 6]],
        "1x1": [[10]],
        "3x2": [[1.5, -2], [30, 4], [-5, 600]],
    }
    for name, matrix in samples.items():
        transposed = transpose_matrix(matrix)
        print("%s original:" % name)
        print(format_matrix(matrix))
        print("%s transposed:" % name)
        print(format_matrix(transposed))
        sums = column_sums(matrix)
        for index in sorted(sums.keys()):
            print("  column %d sums to %s" % (index, sums[index]))
        print("  total of all entries: %s" % sum(sums.values()))
        print()


if __name__ == "__main__":
    main()

