def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    if principal < 0 or rate < 0 or time < 0:
        raise ValueError("principal, rate and time must be non-negative")
    return principal * rate * time / 100.0


def yearly_balances(principal, rate, time):
    """Map each year (1..time) to the account balance at the end of that year."""
    balances = {}
    for year in range(1, time + 1):
        balances[year] = principal + calculate_simple_interest(principal, rate, year)
    return balances


def yearly_increments(balances, principal):
    """Map each year to the interest credited during that single year."""
    increments = {}
    previous = principal
    for year in sorted(balances.keys()):
        increments[year] = balances[year] - previous
        previous = balances[year]
    return increments


def compare_rates(principal, rates, time):
    """Map each candidate rate to the interest it yields over `time` years."""
    results = {}
    for rate in rates:
        results[rate] = calculate_simple_interest(principal, rate, time)
    return results


def best_rate(results):
    """Return the rate producing the largest interest."""
    chosen = None
    best = float("-inf")
    for rate, interest in results.items():
        if interest > best:
            best = interest
            chosen = rate
    return chosen


def years_to_target(principal, rate, target, limit):
    """Return the first year within `limit` whose interest reaches `target`."""
    for year in range(1, limit + 1):
        if calculate_simple_interest(principal, rate, year) >= target:
            return year
    return None


def format_schedule(balances, increments):
    lines = ["Year |    Interest |     Balance"]
    for year, balance in balances.items():
        lines.append("{:>4} | {:>11.2f} | {:>11.2f}".format(year, increments[year], balance))
    return "\n".join(lines)


def main():
    principal, rate, time = 1000.0, 5.0, 2
    print("Interest on {:.2f} at {}% for {} years: {:.2f}".format(
        principal, rate, time, calculate_simple_interest(principal, rate, time)))
    print("Interest on 500.00 at 2.5% for 10 years: {:.2f}".format(
        calculate_simple_interest(500, 2.5, 10)))

    balances = yearly_balances(500.0, 2.5, 10)
    increments = yearly_increments(balances, 500.0)
    print(format_schedule(balances, increments))

    total = 0.0
    for credited in increments.values():
        total += credited
    print("Total interest credited: {:.2f}".format(total))

    results = compare_rates(500.0, [2.5, 3.75, 4.0, 1.25], 10)
    for rate in sorted(results.keys()):
        print("rate {:>5.2f}% -> interest {:>8.2f}".format(rate, results[rate]))
    top = best_rate(results)
    print("Best rate: {:.2f}%".format(top))
    print("Years for 500.00 at {:.2f}% to earn 100.00: {}".format(
        top, years_to_target(500.0, top, 100.0, 10)))


if __name__ == "__main__":
    main()

