def normalize(card_number):
    """Strip separators and verify the remaining characters are digits."""
    cleaned = []
    for index in range(len(card_number)):
        char = card_number[index]
        if char in " -":
            continue
        if not char.isdigit():
            raise ValueError("invalid character %r at position %d" % (char, index))
        cleaned.append(int(char))
    if not cleaned:
        raise ValueError("card number contains no digits")
    return cleaned


def luhn_sum(digits):
    """Double every second digit from the right and add everything up."""
    total = 0
    last = len(digits) - 1
    for position in range(last, -1, -1):
        value = digits[position]
        if (last - position) % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value
    return total


def is_valid_luhn(card_number):
    digits = normalize(card_number)
    return luhn_sum(digits) % 10 == 0


def digit_frequency(digits):
    """Count how often each digit 0-9 occurs in the card number."""
    counts = {}
    for digit in range(10):
        counts[digit] = 0
    for digit in digits:
        counts[digit] += 1
    return {digit: count for digit, count in counts.items() if count}


def describe(card_number):
    digits = normalize(card_number)
    total = luhn_sum(digits)
    counts = digit_frequency(digits)
    busiest = max(counts.keys(), key=lambda digit: (counts[digit], -digit))
    parts = []
    for digit, count in sorted(counts.items()):
        parts.append("%d x%d" % (digit, count))
    return {
        "number": "".join(str(d) for d in digits),
        "length": sum(counts.values()),
        "checksum": total,
        "valid": total % 10 == 0,
        "most_common_digit": busiest,
        "distribution": ", ".join(parts),
        "distinct_digits": len(counts),
    }


def main():
    samples = {
        "valid sample": "49927398716",
        "sequential": "1234567890123456",
        "spaced": "4539 1488 0343 6467",
        "short": "59",
    }
    for label, number in samples.items():
        report = describe(number)
        verdict = "VALID" if report["valid"] else "INVALID"
        print("%-14s %-18s %s" % (label, report["number"], verdict))
        for field in ("length", "checksum", "distinct_digits", "most_common_digit"):
            print("    %-18s %s" % (field, report[field]))
        print("    distribution       %s" % report["distribution"])
    checked = {number: is_valid_luhn(number) for number in samples.values()}
    passed = [number for number, ok in checked.items() if ok]
    print("%d of %d sample numbers pass the check" % (len(passed), len(checked)))


if __name__ == "__main__":
    main()

