class Queue:
    """A first-in, first-out queue backed by a Python list."""

    def __init__(self, items=None):
        self._items = []
        if items is not None:
            for item in items:
                self.enqueue(item)

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            return None
        return self._items.pop(0)

    def __len__(self):
        return len(self._items)

    def peek(self):
        if not self._items:
            return None
        return self._items[0]

    def snapshot(self):
        return list(self._items)


def fill_from_batches(queue, batches):
    """Enqueue `count` copies of each label described by a {label: count} dict."""
    for label, count in batches.items():
        for index in range(count):
            queue.enqueue("{0}-{1}".format(label, index + 1))
    return len(queue)


def drain(queue, limit):
    """Dequeue up to `limit` items, stopping early when the queue runs dry."""
    served = []
    for _ in range(limit):
        item = queue.dequeue()
        if item is None:
            break
        served.append(item)
    return served


def count_by_prefix(items):
    tally = {}
    for item in items:
        prefix = item.split("-")[0]
        tally[prefix] = tally.get(prefix, 0) + 1
    return tally


def format_report(tally):
    lines = []
    width = 0
    for key in tally.keys():
        width = max(width, len(key))
    for prefix, count in tally.items():
        lines.append("{0}: {1}".format(prefix.ljust(width), count))
    lines.append("total served: {0}".format(sum(tally.values())))
    return "\n".join(lines)


def main():
    queue = Queue()
    print("empty dequeue ->", queue.dequeue())

    queue.enqueue(1)
    print("single dequeue ->", queue.dequeue())

    pending = fill_from_batches(queue, {"web": 3, "phone": 2, "walkin": 4})
    print("queued {0} requests, next is {1}".format(pending, queue.peek()))

    all_served = []
    for round_number in range(3):
        served = drain(queue, 3)
        all_served.extend(served)
        print("round {0} served {1}".format(round_number + 1, served))
        print("remaining:", queue.snapshot())

    print(format_report(count_by_prefix(all_served)))


if __name__ == "__main__":
    main()

