import math


def euclidean_distance_2d(x1, y1, x2, y2):
    """Return the Euclidean distance between (x1, y1) and (x2, y2)."""
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def distance_matrix(points):
    """Build the symmetric matrix of pairwise distances for a list of points."""
    n = len(points)
    matrix = [[0.0] * n for i in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            d = euclidean_distance_2d(x1, y1, x2, y2)
            matrix[i][j] = d
            matrix[j][i] = d
    return matrix


def nearest_neighbours(named_points):
    """Map each label to the label of its closest other point and that distance."""
    labels = list(named_points.keys())
    result = {}
    for label, (x1, y1) in named_points.items():
        best_label = None
        best_distance = float("inf")
        for other in labels:
            if other == label:
                continue
            x2, y2 = named_points[other]
            d = euclidean_distance_2d(x1, y1, x2, y2)
            if d < best_distance:
                best_distance = d
                best_label = other
        result[label] = (best_label, best_distance)
    return result


def path_length(points):
    """Total length of the open polyline visiting the points in order."""
    total = 0.0
    for i in range(len(points) - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]
        total += euclidean_distance_2d(x1, y1, x2, y2)
    return total


def distances_from_origin(named_points):
    """Distance of every labelled point from (0, 0)."""
    radii = {}
    for label, (x, y) in named_points.items():
        radii[label] = euclidean_distance_2d(0.0, 0.0, x, y)
    return radii


def format_report(named_points):
    lines = []
    radii = distances_from_origin(named_points)
    for label, radius in radii.items():
        x, y = named_points[label]
        lines.append("{0:<8} ({1:5.2f}, {2:5.2f})  r = {3:.4f}".format(label, x, y, radius))
    lines.append("farthest from origin: {0:.4f}".format(max(radii.values())))
    for label, (other, d) in nearest_neighbours(named_points).items():
        lines.append("{0:<8} nearest -> {1:<8} d = {2:.4f}".format(label, other, d))
    return "\n".join(lines)


def main():
    named_points = {
        "origin": (0.0, 0.0),
        "alpha": (3.0, 4.0),
        "beta": (1.0, 1.0),
        "gamma": (-2.0, 5.5),
    }
    print(format_report(named_points))

    order = list(named_points.keys())
    points = [named_points[label] for label in order]
    print("tour order: " + " -> ".join(order))
    print("path length: {0:.4f}".format(path_length(points)))

    matrix = distance_matrix(points)
    for i in range(len(points)):
        row = " ".join("{0:7.3f}".format(matrix[i][j]) for j in range(len(points)))
        print("{0:<8}{1}".format(order[i], row))


if __name__ == "__main__":
    main()

