def fibonacci_sequence(n):
    """Return the Fibonacci numbers strictly less than n, starting 0, 1."""
    if n <= 0:
        return []
    seq = [0]
    a, b = 0, 1
    while b < n:
        seq.append(b)
        a, b = b, a + b
    return seq


def digit_frequency(seq):
    """Count how often each decimal digit appears across the sequence."""
    counts = {digit: 0 for digit in range(10)}
    for value in seq:
        for ch in str(value):
            counts[int(ch)] += 1
    return counts


def parity_split(seq):
    """Group the numbers into even and odd buckets."""
    buckets = {"even": [], "odd": []}
    for value in seq:
        key = "even" if value % 2 == 0 else "odd"
        buckets[key].append(value)
    return buckets


def successive_ratios(seq):
    """Map each index i to seq[i + 1] / seq[i] for the non-zero terms."""
    ratios = {}
    for i in range(len(seq) - 1):
        if seq[i] != 0:
            ratios[i] = seq[i + 1] / seq[i]
    return ratios


def describe_digits(counts):
    """Build lines for the digits that actually occurred, most frequent first."""
    used = {digit: total for digit, total in counts.items() if total > 0}
    order = sorted(used.keys(), key=lambda d: (-used[d], d))
    lines = []
    for digit in order:
        lines.append("  digit %d appears %d time(s)" % (digit, used[digit]))
    return lines


