def validate_dict(input_dict):
    """Ensure the mapping only holds numeric values that can be compared."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    for key, value in input_dict.items():
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("value for key %r is not numeric" % (key,))
    return input_dict


def filter_dict_by_value(input_dict, threshold):
    """Return the pairs of input_dict whose value is greater than threshold."""
    validate_dict(input_dict)
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")
    result = {}
    for key, value in input_dict.items():
        if value > threshold:
            result[key] = value
    return result


def summarize(input_dict):
    """Basic statistics over the values of a mapping."""
    count = len(input_dict)
    if count == 0:
        return {"count": 0, "total": 0, "mean": None, "max": None, "min": None}
    total = 0
    for value in input_dict.values():
        total += value
    return {
        "count": count,
        "total": total,
        "mean": total / count,
        "max": max(input_dict.values()),
        "min": min(input_dict.values()),
    }


def histogram(input_dict, step=20):
    """Count values per half-open bucket [low, low + step)."""
    top = max(input_dict.values()) if input_dict else 0
    buckets = {}
    for low in range(0, int(top) + step, step):
        buckets[(low, low + step)] = 0
    for value in input_dict.values():
        low = int(value) // step * step
        buckets[(low, low + step)] += 1
    return buckets


def threshold_sweep(input_dict, start, stop, step):
    """How many pairs survive for each threshold in a range."""
    sizes = {}
    for threshold in range(start, stop, step):
        sizes[threshold] = len(filter_dict_by_value(input_dict, threshold))
    return sizes


def format_table(input_dict):
    """Render a numbered, key-sorted table of the surviving pairs."""
    keys = sorted(input_dict.keys())
    width = 1
    for key in keys:
        width = max(width, len(str(key)))
    lines = []
    for index in range(len(keys)):
        lines.append("%3d. %-*s %s" % (index + 1, width, keys[index], input_dict[keys[index]]))
    return "\n".join(lines)


def main():
    scores = {"ann": 91, "bob": 47, "cid": 68, "dee": 12, "eve": 75, "fay": 33}
    kept = filter_dict_by_value(scores, 50)
    print("kept: %s" % (kept,))
    print(format_table(kept))
    for name, stat in summarize(kept).items():
        print("  %-5s %s" % (name, stat))
    for bounds, count in histogram(scores).items():
        print("  [%3d,%3d) %s" % (bounds[0], bounds[1], "#" * count))
    for threshold, size in threshold_sweep(scores, 0, 100, 25).items():
        print("  > %3d -> %d pair(s)" % (threshold, size))


if __name__ == "__main__":
    main()

