def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9 / 5 + 32


def fahrenheit_to_celsius(fahrenheit):
    """Convert a Fahrenheit temperature back to Celsius."""
    return (float(fahrenheit) - 32) * 5 / 9


def conversion_table(start, stop, step=10):
    """Map each Celsius value in [start, stop] to its Fahrenheit value."""
    table = {}
    for celsius in range(start, stop + 1, step):
        table[celsius] = celsius_to_fahrenheit(celsius)
    return table


def format_table(table):
    """Render a conversion table as aligned text lines."""
    lines = ["%8s %10s" % ("Celsius", "Fahrenheit")]
    for celsius, fahrenheit in table.items():
        lines.append("%8.1f %10.1f" % (celsius, fahrenheit))
    return lines


REFERENCE_POINTS = {
    "absolute zero": -273.15,
    "water freezes": 0.0,
    "body temperature": 37.0,
    "water boils": 100.0,
}


def reference_report():
    """Convert every well-known reference point to Fahrenheit."""
    converted = {}
    for name, celsius in REFERENCE_POINTS.items():
        converted[name] = celsius_to_fahrenheit(celsius)
    return converted


def widest_name(names):
    """Length of the longest label, used for column alignment."""
    longest = 0
    for name in names:
        if len(name) > longest:
            longest = len(name)
    return longest


def round_trip_error(table):
    """Largest error introduced by converting back to Celsius."""
    worst = 0.0
    for celsius, fahrenheit in table.items():
        error = abs(fahrenheit_to_celsius(fahrenheit) - celsius)
        if error > worst:
            worst = error
    return worst


def main():
    table = conversion_table(-40, 100, 20)
    for line in format_table(table):
        print(line)

    report = reference_report()
    width = widest_name(report.keys())
    print()
    for name in sorted(report.keys()):
        print("%-*s %8.2f F" % (width, name, report[name]))

    hottest = max(report.values())
    print("\nhottest reference point: %.2f F" % hottest)
    print("max round-trip error: %.12f C" % round_trip_error(table))

    samples = [0, 100]
    for index in range(len(samples)):
        print("%d C -> %.1f F" % (samples[index], celsius_to_fahrenheit(samples[index])))


if __name__ == "__main__":
    main()

