def validate(numbers):
    """Check that `numbers` holds n-1 distinct integers drawn from 1..n."""
    n = len(numbers) + 1
    counts = {}
    for index in range(len(numbers)):
        value = numbers[index]
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("position %d is not an integer: %r" % (index, value))
        if value < 1 or value > n:
            raise ValueError("value %d at position %d is outside 1..%d" % (value, index, n))
        counts[value] = counts.get(value, 0) + 1
    for value, times in counts.items():
        if times > 1:
            raise ValueError("value %d appears %d times" % (value, times))
    return n


def build_presence_map(numbers, n):
    """Map every candidate in 1..n to whether it occurs in `numbers`."""
    presence = {}
    for candidate in range(1, n + 1):
        presence[candidate] = False
    for value in numbers:
        presence[value] = True
    return presence


def find_missing_number(numbers):
    n = validate(numbers)
    expected = 0
    for candidate in range(1, n + 1):
        expected += candidate
    return expected - sum(numbers)


def missing_by_scan(numbers):
    """Second, independent answer used to cross-check the arithmetic one."""
    n = len(numbers) + 1
    presence = build_presence_map(numbers, n)
    for candidate, seen in presence.items():
        if not seen:
            return candidate
    raise ValueError("no candidate is missing from a full range")


def describe(numbers):
    n = len(numbers) + 1
    presence = build_presence_map(numbers, n)
    present_total = sum(1 for seen in presence.values() if seen)
    marks = []
    for candidate in sorted(presence.keys()):
        marks.append(str(candidate) if presence[candidate] else "_")
    return "range 1..%d, %d present: %s" % (n, present_total, " ".join(marks))


def main():
    cases = [[1, 2, 4, 5], [1, 3], [2], [3, 1, 5, 4, 6, 2, 8]]
    for position in range(len(cases)):
        numbers = cases[position]
        answer = find_missing_number(numbers)
        assert answer == missing_by_scan(numbers)
        print("case %d: %s -> %d" % (position + 1, numbers, answer))
        print("  " + describe(numbers))

    tally = {}
    for numbers in cases:
        answer = find_missing_number(numbers)
        tally[answer] = tally.get(answer, 0) + 1
    print("answers seen: %d distinct" % len(tally))
    print("cases covered: %d" % sum(tally.values()))
    for answer, times in sorted(tally.items()):
        print("  %d was missing in %d case(s)" % (answer, times))


if __name__ == "__main__":
    main()

