    expected = 0
    for candidate in xrange(1, n + 1):
        expected += candidate
    return expected - sum(numbers)


def missing_by_scan(numbers):
    """Second, independent answer used to cross-check the arithmetic one."""
    n = len(numbers) + 1
    presence = build_presence_map(numbers, n)
    for candidate, seen in presence.iteritems():
        if not seen:
            return candidate
    raise ValueError("no candidate is missing from a full range")


def describe(numbers):
    n = len(numbers) + 1
    presence = build_presence_map(numbers, n)
    present_total = sum(1 for seen in presence.itervalues() if seen)
    marks = []
    for candidate in sorted(presence.iterkeys()):
        marks.append(str(candidate) if presence[candidate] else "_")
    return "range 1..%d, %d present: %s" % (n, present_total, " ".join(marks))


def main():
    cases = [[1, 2, 4, 5], [1, 3], [2], [3, 1, 5, 4, 6, 2, 8]]
    for position in xrange(len(cases)):
        numbers = cases[position]
        answer = find_missing_number(numbers)
        assert answer == missing_by_scan(numbers)
        print("case %d: %s -> %d" % (position + 1, numbers, answer))
        print("  " + describe(numbers))

    tally = {}
    for numbers in cases:
        answer = find_missing_number(numbers)
        tally[answer] = tally.get(answer, 0) + 1
    print("answers seen: %d distinct" % len(tally))
    print("cases covered: %d" % sum(tally.itervalues()))
    for answer, times in sorted(tally.iteritems()):
        print("  %d was missing in %d case(s)" % (answer, times))


if __name__ == "__main__":
    main()

