import re

EMAIL_PATTERN = re.compile(
    r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+"
)
MAX_LABEL_LENGTH = 63


def _labels_are_sane(domain):
    labels = domain.split(".")
    for i in range(len(labels)):
        if not labels[i] or len(labels[i]) > MAX_LABEL_LENGTH:
            return False
    return True


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    found = []
    for candidate in EMAIL_PATTERN.findall(text):
        local, _, domain = candidate.partition("@")
        if len(local) <= MAX_LABEL_LENGTH and _labels_are_sane(domain):
            found.append(candidate)
    return found


def group_by_domain(emails):
    """Map each domain to the list of addresses seen for it."""
    groups = {}
    for email in emails:
        domain = email.split("@", 1)[1].lower()
        groups.setdefault(domain, []).append(email)
    return groups


def domain_counts(groups):
    return {domain: len(members) for domain, members in groups.items()}


def top_domains(counts, limit=3):
    ranked = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ranked[:limit]


def mask_email(email):
    """Obfuscate the local part so a report can be shared safely."""
    local, _, domain = email.partition("@")
    chars = []
    for i in range(len(local)):
        if i == 0 or i == len(local) - 1:
            chars.append(local[i])
        else:
            chars.append("*")
    return "".join(chars) + "@" + domain


def format_report(groups):
    lines = []
    for domain in sorted(groups.keys()):
        members = groups[domain]
        lines.append("%s (%d)" % (domain, len(members)))
        for position in range(1, len(members) + 1):
            lines.append("  %d. %s" % (position, mask_email(members[position - 1])))
    for domain, count in top_domains(domain_counts(groups)):
        lines.append("top: %s -> %s" % (domain, "#" * count))
    return "\n".join(lines)


def main():
    documents = {
        "footer": "Contact us at info@example.com or support@test.org.",
        "notice": "No emails here.",
        "thread": "ping dev@example.com, cc ops@example.com and qa@other.net",
    }
    collected = []
    for name, text in documents.items():
        emails = extract_emails(text)
        print("%s: %r" % (name, emails))
        collected.extend(emails)
    groups = group_by_domain(collected)
    print(format_report(groups))
    print("total addresses:", sum(len(m) for m in groups.values()))


if __name__ == "__main__":
    main()

