VOWELS = "aeiou"


def count_vowels(text):
    """Return the number of vowels (case-insensitive) in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    total = 0
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def vowel_frequencies(text):
    """Return a dict mapping each vowel to how often it occurs in text."""
    counts = dict.fromkeys(VOWELS, 0)
    for char in text.lower():
        if char in counts:
            counts[char] += 1
    return counts


def most_common_vowels(text):
    """Return the vowels tied for the highest count, alphabetically sorted."""
    counts = vowel_frequencies(text)
    best = max(counts.values())
    if best == 0:
        return []
    return sorted(vowel for vowel, n in counts.items() if n == best)


def vowel_positions(text):
    """Return a dict mapping each vowel to the indexes where it appears."""
    positions = {vowel: [] for vowel in VOWELS}
    for index, char in enumerate(text.lower()):
        if char in positions:
            positions[char].append(index)
    return positions


def chunk_vowel_counts(text, size=8):
    """Return a dict mapping each chunk start offset to its vowel count."""
    if size < 1:
        raise ValueError("size must be positive")
    return {start: count_vowels(text[start:start + size])
            for start in range(0, len(text), size)}


def wrap(text, width=40):
    """Split text into display lines of at most width characters."""
    return [text[start:start + width] for start in range(0, len(text), width)]


def format_report(text, chunk=8):
    """Build a multi-line report about the vowels found in text."""
    lines = ["| %s" % piece for piece in wrap(text)]
    lines.append("Total vowels: %d" % count_vowels(text))
    for vowel, spots in vowel_positions(text).items():
        if spots:
            places = ", ".join(str(spot) for spot in spots)
            lines.append("  %s x%d at %s" % (vowel, len(spots), places))
    for start, count in chunk_vowel_counts(text, chunk).items():
        lines.append("  chars %d-%d: %d" % (start, start + chunk - 1, count))
    top = most_common_vowels(text)
    if top:
        lines.append("Most common: %s" % "/".join(top))
    return "\n".join(lines)


def main():
    samples = ["Hello World", "Python", "Programming is queueing vowels", ""]
    for sample in samples:
        print(format_report(sample))
        print("-" * 32)
    totals = {sample: count_vowels(sample) for sample in samples}
    grand = 0
    for sample, count in totals.items():
        grand += count
        print("%-32s %d" % (sample or "<empty>", count))
    print("Grand total: %d" % grand)


if __name__ == "__main__":
    main()

