def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    """Return the total amount after compounding `principal` for `time_years`."""
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if compounding_frequency < 1:
        raise ValueError("compounding_frequency must be at least 1")
    if time_years < 0:
        raise ValueError("time_years must be non-negative")
    amount = principal
    periodic_rate = rate / compounding_frequency
    for _ in range(compounding_frequency * time_years):
        amount *= 1 + periodic_rate
    return amount


def yearly_schedule(principal, rate, compounding_frequency, time_years):
    """Map each year (0..time_years) to the balance at the end of that year."""
    schedule = {}
    for year in range(time_years + 1):
        schedule[year] = calculate_compound_interest(
            principal, rate, compounding_frequency, year
        )
    return schedule


def interest_earned_per_year(schedule):
    """Map each year to the interest credited during that year."""
    years = sorted(schedule.keys())
    earned = {}
    for index in range(1, len(years)):
        previous, current = years[index - 1], years[index]
        earned[current] = schedule[current] - schedule[previous]
    return earned


def compare_frequencies(principal, rate, time_years, frequencies):
    """Map each frequency label to the final amount it produces."""
    results = {}
    for label, frequency in frequencies.items():
        results[label] = calculate_compound_interest(
            principal, rate, frequency, time_years
        )
    return results


def best_frequency(results):
    """Return the label whose final amount is the largest."""
    best_label = None
    for label, amount in results.items():
        if best_label is None or amount > results[best_label]:
            best_label = label
    return best_label


def format_schedule(schedule, earned):
    lines = ["year |      balance |     interest"]
    for year, balance in schedule.items():
        gain = earned.get(year, 0.0)
        lines.append("{:>4} | {:>12.2f} | {:>12.2f}".format(year, balance, gain))
    return "\n".join(lines)


def main():
    principal, rate, time_years = 1000.0, 0.05, 5
    frequencies = {"annual": 1, "quarterly": 4, "monthly": 12, "daily": 365}

    schedule = yearly_schedule(principal, rate, frequencies["quarterly"], time_years)
    earned = interest_earned_per_year(schedule)
    print("Quarterly compounding of {:.2f} at {:.2%}".format(principal, rate))
    print(format_schedule(schedule, earned))
    print("total interest: {:.2f}".format(sum(earned.values())))

    results = compare_frequencies(principal, rate, time_years, frequencies)
    print("\nFinal amounts after {} years:".format(time_years))
    for label in frequencies.keys():
        print("  {:<10} {:.6f}".format(label, results[label]))
    print("best option: {}".format(best_frequency(results)))


if __name__ == "__main__":
    main()

