def split_pairs(query_string):
    """Split a query string into raw 'key=value' chunks on '&' or ';'."""
    pairs = []
    start = 0
    for i in range(len(query_string)):
        if query_string[i] in '&;':
            pairs.append(query_string[start:i])
            start = i + 1
    pairs.append(query_string[start:])
    return [pair for pair in pairs if pair]


def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    params = {}
