def is_valid_ipv4(ip_address):
    """Return True if ip_address is four dot-separated octets in 0..255."""
    if not isinstance(ip_address, str):
        return False
    parts = ip_address.split('.')
    if len(parts) != 4:
        return False
    for i in range(4):
        octet = parts[i]
        if not octet or len(octet) > 3:
            return False
        if octet.strip('0123456789'):
            return False
        if octet[0] == '0' and len(octet) > 1:
            return False
        if int(octet) > 255:
            return False
    return True


def ip_to_int(ip_address):
    """Pack a dotted-quad address into a single 32-bit integer."""
    octets = [int(part) for part in ip_address.split('.')]
    value = 0
    for i in range(4):
        value |= octets[i] << (8 * (3 - i))
    return value


def int_to_ip(value):
    """Render a 32-bit integer back as a dotted-quad address."""
    octets = []
    for shift in range(24, -1, -8):
        octets.append(str((value >> shift) & 255))
    return '.'.join(octets)


def netmask(prefix_len):
    """Return the 32-bit mask for a prefix length."""
    return (0xFFFFFFFF << (32 - prefix_len)) & 0xFFFFFFFF


NETWORKS = {
    'loopback': ('127.0.0.0', 8),
    'private-10': ('10.0.0.0', 8),
    'private-172': ('172.16.0.0', 12),
    'private-192': ('192.168.0.0', 16),
    'link-local': ('169.254.0.0', 16),
    'multicast': ('224.0.0.0', 4),
}


def classify(ip_address):
    """Name the reserved network containing a valid IPv4 address."""
    value = ip_to_int(ip_address)
    for name, (network, prefix_len) in NETWORKS.items():
        mask = netmask(prefix_len)
        if value & mask == ip_to_int(network) & mask:
            return name
    return 'public'


def subnet_base(ip_address, prefix_len=24):
    """Return the network address of the subnet holding ip_address."""
    return int_to_ip(ip_to_int(ip_address) & netmask(prefix_len))


def audit(addresses):
    """Map each candidate address to its verdict."""
    report = {}
    for address in addresses:
        report[address] = classify(address) if is_valid_ipv4(address) else 'invalid'
    return report


def summarize(report):
    """Count how many addresses fall into each verdict."""
    counts = {}
    for verdict in report.values():
        counts[verdict] = counts.get(verdict, 0) + 1
    return counts


def main():
    candidates = [
        '192.168.1.1', '256.0.0.1', '127.0.0.1', '10.0.0.7', '172.20.5.9',
        '169.254.1.1', '8.8.8.8', '1.2.3', '01.2.3.4', '224.0.0.251',
    ]
    report = audit(candidates)
    width = max(len(key) for key in report.keys())
    for address, verdict in report.items():
        subnet = (subnet_base(address) + '/24') if verdict != 'invalid' else ''
        print('%s  %s %s' % (address.ljust(width), verdict.ljust(12), subnet))

    print('-' * (width + 20))
    for verdict, total in sorted(summarize(report).items()):
        print('%s  %d' % (verdict.ljust(width), total))


if __name__ == '__main__':
    main()

