def validate_2x2(matrix, name):
    if len(matrix) != 2:
        raise ValueError(name + " must have exactly 2 rows")
    for i in range(2):
        if len(matrix[i]) != 2:
            raise ValueError(name + " row " + str(i) + " must have exactly 2 entries")
        for j in range(2):
            if not isinstance(matrix[i][j], (int, float)):
                raise TypeError(name + " entry at (" + str(i) + ", " + str(j) + ") is not numeric")


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            total = 0
            for k in range(2):
                total += matrix_a[i][k] * matrix_b[k][j]
            result[i][j] = total
    return result


def matrix_power(matrix, exponent):
    accumulator = [[1, 0], [0, 1]]
    for _ in range(exponent):
        accumulator = multiply_2x2_matrices(accumulator, matrix)
    return accumulator


def column_widths(matrix):
    widths = {}
    for j in range(2):
        widths[j] = max(len(str(matrix[i][j])) for i in range(2))
    return widths


def format_matrix(matrix):
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j, width in widths.items():
            cells.append(str(row[j]).rjust(width))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def main():
    cases = {
        "basic": ([[1, 2], [3, 4]], [[5, 6], [7, 8]]),
        "identity": ([[1, 0], [0, 1]], [[10, 20], [30, 40]]),
        "negatives": ([[2, -1], [-3, 4]], [[0, 5], [6, -7]]),
    }
    for label, (a, b) in cases.items():
        product = multiply_2x2_matrices(a, b)
        print(label + ":")
        print(format_matrix(product))
        print()

    fib = [[1, 1], [1, 0]]
    powers = {}
    for n in range(1, 8):
        powers[n] = matrix_power(fib, n)
    for n in powers.keys():
        print("fib matrix ^" + str(n) + " -> F(" + str(n) + ") = " + str(powers[n][0][1]))

    traces = [p[0][0] + p[1][1] for p in powers.values()]
    print("traces:", traces)


if __name__ == "__main__":
    main()

