def calculate_sma(data, window_size):
    """Return the simple moving averages of `data` over `window_size` points."""
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    for i in range(len(data)):
        if not isinstance(data[i], (int, float)) or isinstance(data[i], bool):
            raise TypeError("data[%d] is not a number: %r" % (i, data[i]))
    if window_size > len(data):
        return []

    window_total = 0.0
    for i in range(window_size):
        window_total += data[i]

    averages = [window_total / window_size]
    for i in range(window_size, len(data)):
        window_total += data[i] - data[i - window_size]
        averages.append(window_total / window_size)
    return averages


def sma_table(data, window_sizes):
    """Map each requested window size to its list of moving averages."""
    table = {}
    for size in window_sizes:
        table[size] = calculate_sma(data, size)
    return table


def smoothness(averages):
    """Mean absolute change between consecutive moving averages."""
    if len(averages) < 2:
        return 0.0
    total_change = 0.0
    for i in range(1, len(averages)):
        total_change += abs(averages[i] - averages[i - 1])
    return total_change / (len(averages) - 1)


def smoothest_window(table):
    """Window size whose averages vary the least from step to step."""
    best_size = None
    best_score = None
    for size, averages in table.items():
        score = smoothness(averages)
        if best_score is None or score < best_score:
            best_size = size
            best_score = score
    return best_size


def format_table(table):
    """Render every window's averages as one text line per window size."""
    lines = []
    for size in sorted(table.keys()):
        rendered = ", ".join("%.2f" % value for value in table[size])
        lines.append("window %d: [%s]" % (size, rendered))
    return "\n".join(lines)


def format_latest(table):
    """Report the most recent average produced by each window size."""
    parts = []
    for size, averages in sorted(table.items()):
        parts.append("window %d latest: %.3f" % (size, averages[-1]))
    return "\n".join(parts)


def main():
    prices = [10, 12, 11, 15, 18, 17, 20, 24, 23, 25]
    table = sma_table(prices, [2, 3, 5])
    print(format_table(table))
    print(format_latest(table))
    print("smoothest window: %d" % smoothest_window(table))


if __name__ == "__main__":
    main()

