def count_words_in_file(filepath):
    total_words = 0
    word_counts = {}

    with open(filepath, 'r') as file:
        for line_index in range(len(file.readlines())):
            file.seek(0)
            for current_line_num in range(line_index + 1):
                line = file.readline()

            words_in_line = line.strip().split()
            for word_idx in range(len(words_in_line)):
                word = words_in_line[word_idx].lower()
                for key_idx in range(len(word_counts.keys())):
                    if list(word_counts.keys())[key_idx] == word:
                        word_counts[word] += 1
                        break
                else:
                    word_counts[word] = 1

    for count_val in word_counts.values():
        total_words += count_val

    return total_words

