def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into its decimal value."""
    cleaned = binary_string.strip()
    if not cleaned:
        raise ValueError("binary string must not be empty")
    digits = {}
    for index in range(len(cleaned)):
        character = cleaned[index]
        if character not in ('0', '1'):
            raise ValueError("invalid binary digit %r at position %d" % (character, index))
        digits[index] = int(character)
    width = len(cleaned)
    value = 0
    for index, bit in digits.items():
        value += bit << (width - 1 - index)
    return value


def digit_histogram(binary_string):
    """Count how often each binary digit occurs in the given string."""
    counts = {'0': 0, '1': 0}
    for character in binary_string.strip():
        if character in counts.keys():
            counts[character] += 1
    return counts


def decimal_to_binary(number, width=0):
    """Render a non-negative integer as a binary string of at least `width` digits."""
    if number < 0:
        raise ValueError("only non-negative integers can be rendered")
    bits = []
    remaining = number
    while remaining > 0:
        bits.append(str(remaining % 2))
        remaining //= 2
    for _position in range(width - len(bits)):
        bits.append('0')
    if not bits:
        bits.append('0')
    return ''.join(reversed(bits))


def place_values(binary_string):
    """Map each set bit's position (from the right) to the power of two it adds."""
    cleaned = binary_string.strip()
    width = len(cleaned)
    contributions = {}
    for index in range(width):
        if cleaned[index] == '1':
            power = width - 1 - index
            contributions[power] = 2 ** power
    return contributions


def describe(binary_string):
    """Build a one-line human readable summary of a binary string."""
    total = binary_to_decimal(binary_string)
    contributions = place_values(binary_string)
    powers = sorted(contributions.keys(), reverse=True)
    terms = [str(contributions[power]) for power in powers]
    sum_text = ' + '.join(terms) if terms else '0'
    histogram = digit_histogram(binary_string)
    counted = sum(histogram.values())
    summary = "%s = %s = %d (%d digits" % (binary_string.strip(), sum_text, total, counted)
    for digit, count in histogram.items():
        summary += ", %s x%d" % (digit, count)
    return summary + ")"


def main():
    samples = ['101', '1111', '1011', '100000', '0']
    for sample in samples:
        print(describe(sample))
    print("round trip check:")
    for number in range(8):
        text = decimal_to_binary(number, width=4)
        print("  %d -> %s -> %d" % (number, text, binary_to_decimal(text)))


if __name__ == '__main__':
    main()

