def count_characters(s):
    """Return a dict mapping each character of s to the number of times it occurs."""
    counts = {}
    for i in range(len(s)):
        ch = s[i]
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def first_unique_char(s):
    """Return the index of the first non-repeating character in s, or -1."""
    counts = count_characters(s)
    for i in range(len(s)):
        if counts[s[i]] == 1:
            return i
    return -1


def unique_characters(s):
    """Return the characters of s that occur exactly once, in order of first appearance."""
    counts = count_characters(s)
    singles = []
    for ch, total in counts.items():
        if total == 1:
            singles.append(ch)
    singles.sort(key=s.index)
    return singles


def repeated_characters(s):
    """Return the characters of s that occur more than once, sorted alphabetically."""
    counts = count_characters(s)
    repeats = []
    for ch in counts.keys():
        if counts[ch] > 1:
            repeats.append(ch)
    repeats.sort()
    return repeats


def longest_run(s):
    """Return the length of the longest run of one repeated character in s."""
    best = 0
    run = 0
    for i in range(len(s)):
        if i > 0 and s[i] == s[i - 1]:
            run += 1
        else:
            run = 1
        if run > best:
            best = run
    return best


def frequency_report(s):
    """Build a human readable frequency table for s, most frequent first."""
    counts = count_characters(s)
    order = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    lines = []
    for ch, total in order:
        lines.append("  '{}' x{}".format(ch, total))
    distinct = len(counts)
    covered = sum(counts.values())
    lines.append("  {} distinct characters covering {} positions".format(distinct, covered))
    return "\n".join(lines)


def main():
    samples = {
        "leetcode": "classic example",
        "loveleetcode": "first two letters repeat",
        "aabb": "no unique character",
        "aaabbbc": "unique letter at the end",
    }
    for text, note in samples.items():
        index = first_unique_char(text)
        print("{!r} ({})".format(text, note))
        print("  first unique index: {}".format(index))
        if index >= 0:
            print("  first unique char: {!r}".format(text[index]))
        print("  all unique: {}".format("".join(unique_characters(text)) or "none"))
        print("  repeated: {}".format("".join(repeated_characters(text)) or "none"))
        print("  longest run: {}".format(longest_run(text)))
        print(frequency_report(text))


if __name__ == "__main__":
    main()

