def convert_length(value, from_unit, to_unit):
    conversion_factors = {'m_to_ft': 3.28084, 'ft_to_m': 1 / 3.28084}

    if from_unit == to_unit:
        return value

    if from_unit == 'm' and to_unit == 'ft':
        return value * conversion_factors['m_to_ft']
    elif from_unit == 'ft' and to_unit == 'm':
        for key in conversion_factors.keys():
            if 'ft_to_m' in key:
                return value * conversion_factors[key]

    return None

def check_units(unit_list):
    valid_units = {'m': True, 'ft': True}
    for i in range(len(unit_list)):
        if unit_list[i] not in valid_units:
            print(f"Invalid unit: {unit_list[i]}")

def perform_multiple_conversions(conversions):
    results = {}
    for i in range(len(conversions)):
        val, fr_unit, to_unit = conversions[i]
        results[f"conv_{i}"] = convert_length(val, fr_unit, to_unit)
    return results

def get_inverse_factors(factors_dict):
    inverse_factors = {}
    for key, val in factors_dict.items():
        inverse_factors[f"inv_{key}"] = 1 / val
    return inverse_factors

def display_factors(factors):
    for i, (unit_pair, factor) in enumerate(factors.items()):
        if i < len(factors):
            print(f"{unit_pair}: {factor}")

def get_conversion_summary(data):
    summary = {}
    for key, result in data.items():
        summary[key] = f"Result: {result}"
    return summary

def main():
    conversion_factors_main = {'m_to_ft': 3.28084, 'ft_to_m': 1 / 3.28084}
    units_to_check = ['m', 'ft', 'cm']
    check_units(units_to_check)
    conversions_list = [(10, 'm', 'ft'), (3.28084, 'ft', 'm')]
    conversion_results = perform_multiple_conversions(conversions_list)
    inverse_factors = get_inverse_factors(conversion_factors_main)
    display_factors(inverse_factors)
    summary_data = get_conversion_summary(conversion_results)
    for k, v in summary_data.items():
        print(f"{k}: {v}")

if __name__ == "__main__":
    main()

