def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after taking `discount_percentage` off `original_price`."""
    if original_price < 0:
        raise ValueError("original_price must not be negative")
    if not 0 <= discount_percentage <= 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    return round(original_price * (1 - discount_percentage / 100.0), 2)


def discount_ladder(original_price, max_percentage=50, step=10):
    """Map each discount percentage in a ladder to the resulting price."""
    ladder = {}
    for percentage in xrange(0, max_percentage + 1, step):
        ladder[percentage] = calculate_discount_price(original_price, percentage)
    return ladder


def tier_for_quantity(quantity, tiers):
    """Pick the best discount whose minimum quantity is reached."""
    best = 0.0
    for minimum, percentage in tiers.iteritems():
        if quantity >= minimum and percentage > best:
            best = percentage
    return best


def price_cart(cart, tiers):
    """Compute per-item pricing details for a cart of {name: (unit_price, quantity)}."""
    priced = {}
    for name, (unit_price, quantity) in cart.iteritems():
        percentage = tier_for_quantity(quantity, tiers)
        unit_final = calculate_discount_price(unit_price, percentage)
        priced[name] = {
            "quantity": quantity,
            "discount": percentage,
            "unit_final": unit_final,
            "line_total": round(unit_final * quantity, 2),
            "line_saving": round((unit_price - unit_final) * quantity, 2),
        }
    return priced


def cart_summary(priced):
    """Add up the line totals and savings of an already priced cart."""
    total = 0.0
    saving = 0.0
    for details in priced.itervalues():
        total += details["line_total"]
        saving += details["line_saving"]
    return round(total, 2), round(saving, 2)


def build_report_lines(priced):
    """Render one numbered line per cart entry, cheapest unit price first."""
    order = sorted(priced.iterkeys(), key=lambda name: priced[name]["unit_final"])
    lines = []
    for index in xrange(len(order)):
        name = order[index]
        details = priced[name]
        lines.append(
            "{0}. {1:<10} x{2:<3} -{3:g}% -> {4:.2f} (saved {5:.2f})".format(
                index + 1,
                name,
                details["quantity"],
                details["discount"],
                details["line_total"],
                details["line_saving"],
            )
        )
    return lines


def main():
    tiers = {1: 0.0, 3: 5.0, 6: 10.0, 12: 20.0}
    cart = {"mug": (12.5, 4), "poster": (8.0, 12), "lamp": (45.0, 1), "pen": (2.0, 6)}

    priced = price_cart(cart, tiers)
    for line in build_report_lines(priced):
        print(line)

    total, saving = cart_summary(priced)
    print("Total: {0:.2f} (total saved {1:.2f})".format(total, saving))

    for percentage, price in discount_ladder(45.0, 40, 10).iteritems():
        print("Lamp at -{0}%: {1:.2f}".format(percentage, price))


if __name__ == "__main__":
    main()

