from collections import OrderedDict


def _key_type_names(input_dict):
    """Collect the distinct type names of the dictionary's keys."""
    names = set()
    for key in input_dict.keys():
        names.add(type(key).__name__)
    return names


def _check_sortable(input_dict):
    """Reject dictionaries whose keys cannot be compared with each other."""
    names = _key_type_names(input_dict)
    numeric = {"int", "float", "bool"}
    if len(names) > 1 and not names.issubset(numeric):
        raise TypeError("keys of mixed types cannot be ordered: %s" % sorted(names))


def _insertion_sorted(keys):
    """Return a new list holding the keys in ascending order."""
    items = list(keys)
    for i in range(1, len(items)):
        current = items[i]
        j = i - 1
        while j >= 0 and items[j] > current:
            items[j + 1] = items[j]
            j -= 1
        items[j + 1] = current
    return items


def sort_dict_by_key(input_dict):
    """Return a new OrderedDict with the entries of input_dict sorted by key."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    _check_sortable(input_dict)
    ordered = OrderedDict()
    for key in _insertion_sorted(input_dict.keys()):
        ordered[key] = input_dict[key]
    return ordered


def format_dict(ordered):
    """Render a sorted dictionary as aligned 'key: value' lines."""
    width = 0
    for key in ordered.keys():
        width = max(width, len(repr(key)))
    lines = []
    for key, value in ordered.items():
        lines.append("%s : %r" % (repr(key).ljust(width), value))
    return "\n".join(lines)


def value_total(ordered):
    """Sum the numeric values of the dictionary, ignoring the rest."""
    total = 0
    for value in ordered.values():
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            total += value
    return total


def main():
    samples = [
        {"b": 2, "a": 1, "c": 3},
        {"z": 26, "y": 25},
        {3: "three", 1: "one", 2: "two"},
    ]
    for index in range(len(samples)):
        ordered = sort_dict_by_key(samples[index])
        print("sample %d -> %r" % (index + 1, dict(ordered)))
        print(format_dict(ordered))
        print("value total: %s\n" % value_total(ordered))

    merged = {}
    for sample in samples:
        for key, value in sample.items():
            merged[str(key)] = value
    print("merged and sorted -> %r" % dict(sort_dict_by_key(merged)))


if __name__ == "__main__":
    main()

