def char_positions(s):
    """Map each character of *s* to the ascending list of its indices."""
    positions = {}
    for i, ch in enumerate(s):
        positions.setdefault(ch, []).append(i)
    return positions


def char_counts(s):
    """Map each character of *s* to the number of times it occurs."""
    counts = {}
    for ch, spots in char_positions(s).items():
        counts[ch] = len(spots)
    return counts


def has_all_unique_chars(s):
    """Return True when no character of *s* appears more than once."""
    if not isinstance(s, str):
        raise TypeError("has_all_unique_chars expects a str")
    for total in char_counts(s).values():
        if total > 1:
            return False
    return True


def duplicate_chars(s):
    """Characters of *s* that occur at least twice, in order of first sight."""
    repeated = []
    for ch, total in char_counts(s).items():
        if total > 1:
            repeated.append(ch)
    return repeated


def first_duplicate_index(s):
    """Index of the first character that was already seen earlier, else -1."""
    clashes = []
    for ch, spots in char_positions(s).items():
        if len(spots) > 1:
            clashes.append(spots[1])
    if not clashes:
        return -1
    return min(clashes)


def describe(s):
    """One-line human readable verdict for *s*."""
    if has_all_unique_chars(s):
        return "%-14s unique (%d chars)" % (repr(s), len(s))
    return "%-14s repeats %s, first clash at index %d" % (
        repr(s), "".join(duplicate_chars(s)), first_duplicate_index(s))


def frequency_table(s):
    """Rows of 'char: count' for every distinct character, most frequent first."""
    rows = []
    for ch, total in sorted(char_counts(s).items(), key=lambda p: (-p[1], p[0])):
        rows.append("%r: %d" % (ch, total))
    return rows


def index_ruler(n):
    """Digit ruler of width *n* for reading off character positions."""
    digits = []
    for i in range(n):
        digits.append(str(i % 10))
    return "".join(digits)


def format_rows(rows, per_line=4):
    """Join *rows* into lines holding at most *per_line* entries each."""
    lines = []
    for start in range(0, len(rows), per_line):
        lines.append("  ".join(rows[start:start + per_line]))
    return lines


def main():
    samples = ["abcde", "hello", "", "AaBb", "Python 3", "mississippi"]
    verdicts = {}
    for word in samples:
        print(describe(word))
        verdicts[word] = has_all_unique_chars(word)

    unique_count = 0
    for flag in verdicts.values():
        if flag:
            unique_count += 1
    print("\n%d of %d samples have all unique characters" % (unique_count, len(verdicts)))

    for word, flag in verdicts.items():
        if not flag:
            print("frequencies for %r:" % word)
            print("    " + word)
            print("    " + index_ruler(len(word)))
            for line in format_rows(frequency_table(word)):
                print("    " + line)


if __name__ == "__main__":
    main()

