def reverse_string(input_string):
    """Return a new string with the characters of input_string in reverse order."""
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str")
    characters = []
    for index in range(len(input_string) - 1, -1, -1):
        characters.append(input_string[index])
    return "".join(characters)


def reverse_chunks(text, size):
    """Reverse the characters inside every block of `size` characters of text."""
    if size <= 0:
        raise ValueError("size must be positive")
    pieces = []
    for start in range(0, len(text), size):
        pieces.append(reverse_string(text[start:start + size]))
    return "".join(pieces)


def reverse_words(text):
    """Reverse the characters of each whitespace-separated word, keeping word order."""
    return " ".join(reverse_string(word) for word in text.split())


def is_palindrome(text):
    """True if text reads the same forwards and backwards, ignoring case and spaces."""
    cleaned = "".join(text.lower().split())
    last = len(cleaned) - 1
    for index in range(len(cleaned) // 2):
        if cleaned[index] != cleaned[last - index]:
            return False
    return True


def char_counts(text):
    """Map each character of text to the number of times it occurs."""
    counts = {}
    for character in text:
        counts[character] = counts.get(character, 0) + 1
    return counts


def describe(text):
    """Build a dictionary of facts about text and its reversal."""
    counts = char_counts(text)
    return {
        "original": text,
        "reversed": reverse_string(text),
        "words_reversed": reverse_words(text),
        "triples_reversed": reverse_chunks(text, 3),
        "palindrome": is_palindrome(text),
        "distinct_characters": len(counts),
        "total_characters": sum(counts.values()),
    }


def format_report(facts):
    """Render a facts dictionary as aligned "key: value" lines."""
    width = max(len(label) for label in facts.keys())
    lines = []
    for label, value in facts.items():
        lines.append("{}: {}".format(label.ljust(width), value))
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "never odd or even", "step on no pets"]
    for number, sample in enumerate(samples, start=1):
        print("--- sample {} ---".format(number))
        print(format_report(describe(sample)))

    tally = char_counts("mississippi")
    for character, count in sorted(tally.items()):
        print("{} appears {} time(s)".format(character, count))
    print("busiest character occurs {} time(s)".format(max(tally.values())))


if __name__ == "__main__":
    main()

