def calculate_power(base, exponent):
    """Return ``base`` raised to ``exponent`` using repeated multiplication."""
    if isinstance(exponent, bool) or not isinstance(exponent, int):
        raise TypeError("exponent must be an int")
    if isinstance(base, bool) or not isinstance(base, (int, float)):
        raise TypeError("base must be an int or a float")
    result = 1
    for _ in range(abs(exponent)):
        result *= base
    if exponent < 0:
        if result == 0:
            raise ZeroDivisionError("0 cannot be raised to a negative exponent")
        return 1 / result
    return result


def power_table(bases, max_exponent):
    """Map every base to the list of its powers from 0 up to ``max_exponent``."""
    if max_exponent < 0:
        raise ValueError("max_exponent must be non-negative")
    table = {}
    for base in bases:
        table[base] = [calculate_power(base, e) for e in range(max_exponent + 1)]
    return table


def format_cell(value, width):
    if isinstance(value, float):
        return "{0:>{1}.4g}".format(value, width)
    return "{0:>{1}}".format(value, width)


def format_table(table, max_exponent, width=8):
    header = "{0:>6} |".format("base")
    for e in range(max_exponent + 1):
        header += "{0:>{1}}".format("^" + str(e), width)
    lines = [header, "-" * len(header)]
    for base, powers in table.items():
        cells = "".join(format_cell(value, width) for value in powers)
        lines.append("{0:>6} |".format(base) + cells)
    return lines


def column_maxima(table, max_exponent):
    """For each exponent, find the largest power produced by any base."""
    maxima = {}
    for e in range(max_exponent + 1):
        maxima[e] = max(powers[e] for powers in table.values())
    return maxima


def describe_maxima(maxima):
    return ["exponent {0}: largest value {1}".format(e, value)
            for e, value in maxima.items()]


def total_of_powers(table):
    totals = {}
    for base, powers in table.items():
        totals[base] = sum(powers)
    return totals


def main():
    bases = [2, 5, -3, 1.5]
    max_exponent = 4
    table = power_table(bases, max_exponent)
    for line in format_table(table, max_exponent):
        print(line)
    print("")
    for line in describe_maxima(column_maxima(table, max_exponent)):
        print(line)
    print("")
    for base, total in total_of_powers(table).items():
        print("sum of powers of {0}: {1}".format(base, total))
    print("")
    for exponent in range(-2, 4):
        print("2 ** {0} = {1}".format(exponent, calculate_power(2, exponent)))


main()

