def is_even(number):
    """Return True if number is even, False otherwise."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an int")
    return number % 2 == 0


def parity_of(number):
    """Return the parity label of number."""
    return "even" if is_even(number) else "odd"


def parity_map(start, stop):
    """Map each integer in [start, stop) to its parity label."""
    labels = {}
    for value in range(start, stop):
        labels[value] = parity_of(value)
    return labels


def count_parities(labels):
    """Count how many numbers carry each parity label."""
    totals = {"even": 0, "odd": 0}
    for label in labels.values():
        totals[label] += 1
    return totals


def evens_only(labels):
    """Return the sorted numbers whose label is 'even'."""
    numbers = []
    for number, label in labels.items():
        if label == "even":
            numbers.append(number)
    return sorted(numbers)


def even_digit_positions(number):
    """Map the index of each digit of abs(number) to whether that digit is even."""
    digits = str(abs(number))
    flags = {}
    for index in range(len(digits)):
        flags[index] = is_even(int(digits[index]))
    return flags


def describe_digits(number):
    """Build a human readable description of the digit parities of number."""
    flags = even_digit_positions(number)
    digits = str(abs(number))
    parts = []
    for index in flags.keys():
        marker = "even" if flags[index] else "odd"
        parts.append("{0}:{1}={2}".format(index, digits[index], marker))
    return " ".join(parts)


def format_report(labels, totals):
    """Render the parity table and totals as report lines."""
    lines = []
    for number, label in labels.items():
        lines.append("{0:>4} -> {1}".format(number, label))
    for label, count in totals.items():
        lines.append("total {0}: {1}".format(label, count))
    return lines


def main():
    print("is_even(4) =", is_even(4))
    print("is_even(7) =", is_even(7))

    labels = parity_map(-3, 8)
    totals = count_parities(labels)
    for line in format_report(labels, totals):
        print(line)

    print("evens:", evens_only(labels))
    for sample in (2468, 13579, -1024):
        print(sample, "->", describe_digits(sample))


if __name__ == "__main__":
    main()

