import math


def calculate_sphere_volume(radius):
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return 4.0 / 3.0 * math.pi * float(radius) ** 3


def sample_radii(start, stop, count):
    if count < 2:
        raise ValueError("need at least two samples")
    step = (stop - start) / (count - 1)
    return [start + step * i for i in range(count)]


def volume_table(radii):
    return {radius: calculate_sphere_volume(radius) for radius in radii}


def shell_volumes(radii):
    ordered = sorted(radii)
    shells = {}
    for i in range(1, len(ordered)):
        inner, outer = ordered[i - 1], ordered[i]
        shells[(inner, outer)] = calculate_sphere_volume(outer) - calculate_sphere_volume(inner)
    return shells


def format_table(table):
    lines = []
    for radius, volume in table.items():
        lines.append("r = {:6.2f}   V = {:12.4f}".format(radius, volume))
    return lines


def largest_radius(table):
    best = None
    for radius in table.keys():
        if best is None or radius > best:
            best = radius
    return best


def total_volume(table):
    total = 0.0
    for volume in table.values():
        total += volume
    return total


def radius_from_volume(volume, steps=60):
    low, high = 0.0, max(1.0, volume)
    for _ in range(steps):
        mid = (low + high) / 2.0
        if calculate_sphere_volume(mid) < volume:
            low = mid
        else:
            high = mid
    return (low + high) / 2.0


def main():
    radii = [1.0, 2.0, 3.0, 4.5]
    table = volume_table(radii)
    for line in format_table(table):
        print(line)

    print("largest radius: {:.2f}".format(largest_radius(table)))
    print("combined volume: {:.4f}".format(total_volume(table)))

    print("shell volumes:")
    for bounds, volume in shell_volumes(radii).items():
        print("  {:.2f} -> {:.2f}: {:10.4f}".format(bounds[0], bounds[1], volume))

    print("inverted radii:")
    for volume in volume_table(sample_radii(0.5, 3.0, 6)).values():
        print("  V = {:10.4f}  ->  r = {:.4f}".format(volume, radius_from_volume(volume)))


if __name__ == "__main__":
    main()

