from datetime import date

MONTH_DAYS = {
    1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
    7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31,
}

UNITS = {"year": 365, "week": 7, "day": 1}


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    length = MONTH_DAYS[month]
    if month == 2 and is_leap(year):
        length += 1
    return length


def validate(year, month, day):
    if month not in MONTH_DAYS:
        raise ValueError("month must be between 1 and 12, got {}".format(month))
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        raise ValueError("day must be between 1 and {}, got {}".format(limit, day))


def days_since(year, month, day):
    validate(year, month, day)
    past = date(year, month, day)
    today = date.today()
    if past > today:
        raise ValueError("{} is not in the past".format(past.isoformat()))
    return (today - past).days


def format_span(days):
    parts = []
    remaining = days
    for name, size in UNITS.items():
        count = remaining // size
        if count:
            parts.append("{} {}{}".format(count, name, "" if count == 1 else "s"))
            remaining -= count * size
    return ", ".join(parts) if parts else "0 days"


def milestones(days):
    return list(range(1000, days + 1, 1000))


def year_length(year):
    total = 0
    for month in range(1, 13):
        total += days_in_month(year, month)
    return total


def year_lengths(start, end):
    lengths = {}
    for year in range(start, end + 1):
        lengths[year] = year_length(year)
    return lengths


def main():
    samples = {
        "moon landing": (1969, 7, 20),
        "millennium": (2000, 1, 1),
        "leap day": (2020, 2, 29),
    }
    for label, parts in samples.items():
        elapsed = days_since(*parts)
        print("{}: {} days ({})".format(label, elapsed, format_span(elapsed)))
        reached = milestones(elapsed)
        if reached:
            print("    milestones passed: {}".format(reached[-1]))
    lengths = year_lengths(2000, date.today().year)
    leap_years = sum(1 for length in lengths.values() if length == 366)
    print("leap years in span: {}".format(leap_years))
    for year, length in lengths.items():
        if length == 366:
            print("    {} had {} days".format(year, length))


if __name__ == "__main__":
    main()

