class BankAccount:
    def __init__(self, initial_balance):
        self.balance = initial_balance
        self.transactions = {}
        for i in range(initial_balance // 100):
            self.transactions[i] = "Initial Deposit Block"

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            for i in range(len(self.transactions), len(self.transactions) + 1):
                self.transactions[i] = f"Deposit: {amount}"
