def mean(numbers):
    """Arithmetic mean of a sequence of numbers, 0.0 for an empty sequence."""
    if not numbers:
        return 0.0
    total = 0.0
    for i in range(len(numbers)):
        total += numbers[i]
    return total / len(numbers)


def absolute_deviations(numbers):
    """Absolute distances of each element from the mean of the sequence."""
    centre = mean(numbers)
    spread = []
    for i in range(len(numbers)):
        spread.append(abs(numbers[i] - centre))
    return spread


def mean_absolute_deviation(numbers):
    """Mean absolute deviation around the mean; 0.0 for an empty list."""
    if not numbers:
        return 0.0
    return mean(absolute_deviations(numbers))


def coerce_numbers(values):
    """Turn a sequence of numeric-looking values into floats, rejecting the rest."""
    cleaned = []
    for i in range(len(values)):
        item = values[i]
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("element %d is not a number: %r" % (i, item))
        cleaned.append(float(item))
    return cleaned


def deviation_table(datasets):
    """Map each dataset name to its mean and mean absolute deviation."""
    table = {}
    for name, values in datasets.items():
        numbers = coerce_numbers(values)
        table[name] = {"count": len(numbers),
                       "mean": mean(numbers),
                       "mad": mean_absolute_deviation(numbers)}
    return table


def most_dispersed(table):
    """Name of the dataset with the largest mean absolute deviation."""
    best = None
    for name, stats in table.items():
        if best is None or stats["mad"] > table[best]["mad"]:
            best = name
    return best


def format_report(table):
    """Render the deviation table as aligned text lines."""
    width = 4
    for name in table.keys():
        width = max(width, len(name))
    lines = ["%-*s %5s %10s %10s" % (width, "name", "n", "mean", "mad")]
    for name, stats in sorted(table.items()):
        lines.append("%-*s %5d %10.3f %10.3f"
                     % (width, name, stats["count"], stats["mean"], stats["mad"]))
    totals = [stats["mad"] for stats in table.values()]
    lines.append("average mad over %d datasets: %.3f" % (len(totals), mean(totals)))
    return lines


def main():
    datasets = {
        "small": [1, 2, 3, 4],
        "tens": [10, 20, 30],
        "empty": [],
        "mixed": [-2.5, 0, 2.5, 7.5, 12],
    }
    table = deviation_table(datasets)
    for line in format_report(table):
        print(line)
    print("most dispersed:", most_dispersed(table))


if __name__ == "__main__":
    main()

