    for i in xrange(n):
        value = numbers[i]
        if not isinstance(value, (int, float)) or value <= 0:
            return 0.0
    log_sum = 0.0
    for i in xrange(n):
        log_sum += math.log(numbers[i])
    return math.exp(log_sum / n)


def arithmetic_mean(numbers):
    """Return the arithmetic mean, or 0.0 for an empty list."""
    if not numbers:
        return 0.0
    total = 0.0
    for i in xrange(len(numbers)):
        total += numbers[i]
    return total / len(numbers)


def growth_factors(values):
    """Ratios between consecutive values, usable as geometric-mean input."""
    factors = []
    for i in xrange(1, len(values)):
        previous = values[i - 1]
        if previous <= 0:
            return []
        factors.append(values[i] / previous)
    return factors


def summarize(datasets):
    """Map each dataset name to its arithmetic and geometric means."""
    summary = {}
    for name, values in datasets.iteritems():
        summary[name] = {
            "arithmetic": arithmetic_mean(values),
            "geometric": geometric_mean(values),
        }
    return summary


def average_growth(series):
    """Average per-step growth factor of a numeric series."""
    return geometric_mean(growth_factors(series))


def format_report(summary):
    lines = []
    for name in sorted(summary.iterkeys()):
        means = summary[name]
        parts = []
        for label, value in means.iteritems():
            parts.append("{0}={1:.4f}".format(label, value))
        lines.append("{0}: {1}".format(name, " ".join(parts)))
    return "\n".join(lines)


def main():
    datasets = {
        "powers": [1, 2, 4],
        "pair": [2, 8],
        "mixed": [0.5, 1.5, 6.0],
        "invalid": [3, -1, 9],
    }
    summary = summarize(datasets)
    print(format_report(summary))

    geometric_values = [entry["geometric"] for entry in summary.itervalues()]
    positive = [v for v in geometric_values if v > 0]
    print("geometric mean of geometric means: {0:.4f}".format(geometric_mean(positive)))

    revenue = [100.0, 120.0, 150.0, 180.0]
    print("average growth factor: {0:.4f}".format(average_growth(revenue)))


if __name__ == "__main__":
    main()

