def levenshtein_distance(s1, s2):
    """Minimum number of insertions, deletions or substitutions turning s1 into s2."""
    n, m = len(s1), len(s2)
    previous = [j for j in range(m + 1)]
    for i in range(1, n + 1):
        current = [i] + [0] * m
        for j in range(1, m + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            current[j] = min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost)
        previous = current
    return previous[m]


def distance_matrix(s1, s2):
    """Full DP table, useful for inspecting how the distance is built up."""
    table = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]
    for i in range(len(s1) + 1):
        table[i][0] = i
    for j in range(len(s2) + 1):
        table[0][j] = j
    for i in range(1, len(s1) + 1):
        for j in range(1, len(s2) + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            table[i][j] = min(table[i - 1][j] + 1,
                              table[i][j - 1] + 1,
                              table[i - 1][j - 1] + cost)
    return table


def similarity(s1, s2):
    """Normalised similarity in [0.0, 1.0]; identical strings give 1.0."""
    longest = max(len(s1), len(s2))
    if longest == 0:
        return 1.0
    return 1.0 - levenshtein_distance(s1, s2) / longest


def distances_to(word, vocabulary):
    """Map every vocabulary entry to its distance from word."""
    return {candidate: levenshtein_distance(word, candidate) for candidate in vocabulary}


def best_matches(word, vocabulary, max_distance=2):
    """Vocabulary entries within max_distance, closest first."""
    keep = [(cand, dist) for cand, dist in distances_to(word, vocabulary).items()
            if dist <= max_distance]
    keep.sort(key=lambda pair: (pair[1], pair[0]))
    return keep


def group_by_distance(word, vocabulary):
    """Bucket vocabulary entries by their distance from word."""
    buckets = {}
    for candidate, dist in distances_to(word, vocabulary).items():
        buckets.setdefault(dist, []).append(candidate)
    for words in buckets.values():
        words.sort()
    return buckets


def format_matrix(s1, s2):
    """Render the DP table with the two strings as row and column labels."""
    table = distance_matrix(s1, s2)
    header = "      " + " ".join(ch.rjust(2) for ch in s2)
    lines = [header]
    labels = " " + s1
    for i in range(len(table)):
        row = " ".join(str(value).rjust(2) for value in table[i])
        lines.append("{} {}".format(labels[i].rjust(2), row))
    return "\n".join(lines)


def main():
    for left, right in [("kitten", "sitting"), ("flaw", "lawn")]:
        print("{} -> {}: {} (similarity {:.2f})".format(
            left, right, levenshtein_distance(left, right), similarity(left, right)))

    print(format_matrix("flaw", "lawn"))

    vocabulary = ["kitten", "sitting", "mitten", "bitten", "kitchen", "smitten", "kite"]
    print("close to 'kitten':", best_matches("kitten", vocabulary))

    buckets = group_by_distance("kitten", vocabulary)
    for dist in sorted(buckets.keys()):
        print("distance {}: {}".format(dist, ", ".join(buckets[dist])))


