def word_frequency(words):
    """Count words case-insensitively and return {word: frequency}."""
    freq = {}
    for word in words:
        key = word.strip().lower()
        if key:
            freq[key] = freq.get(key, 0) + 1
    return freq


def tokenize(text):
    """Split raw text into word tokens, stripping punctuation."""
    tokens = []
    for chunk in text.split():
        cleaned = chunk.strip(".,;:!?\"'()[]-")
        if cleaned:
            tokens.append(cleaned)
    return tokens


def merge_counts(base, extra):
    """Add the counts of `extra` into a copy of `base`."""
    merged = dict(base)
    for word, count in extra.items():
        merged[word] = merged.get(word, 0) + count
    return merged


def total_words(freq):
    return sum(freq.values())


def vocabulary(freq):
    return sorted(freq.keys())


def most_common(freq, n):
    """Return the n (word, count) pairs with the highest counts."""
    ordered = sorted(freq.items(), key=lambda pair: (-pair[1], pair[0]))
    limit = min(n, len(ordered))
    return [ordered[i] for i in range(limit)]


def group_by_count(freq):
    """Invert the mapping: count -> sorted list of words with that count."""
    groups = {}
    for word, count in freq.items():
        groups.setdefault(count, []).append(word)
    for words in groups.values():
        words.sort()
    return groups


def format_report(freq, top=3):
    lines = ["total words: %d" % total_words(freq),
             "distinct words: %d" % len(freq)]
    ranking = most_common(freq, top)
    for rank in range(1, len(ranking) + 1):
        word, count = ranking[rank - 1]
        lines.append("%d. %-8s %s (%d)" % (rank, word, "#" * count, count))
    groups = group_by_count(freq)
    highest = max(groups.keys()) if groups else 0
    for count in range(highest, 0, -1):
        if count in groups:
            lines.append("seen %dx: %s" % (count, ", ".join(groups[count])))
    return "\n".join(lines)


def main():
    simple = word_frequency(['Apple', 'banana', 'apple', 'Orange'])
    print(simple)
    print(word_frequency([]))
    print("vocabulary:", vocabulary(simple))

    text = "The cat sat on the mat; the mat was warm, the cat was happy."
    counts = word_frequency(tokenize(text))
    combined = merge_counts(counts, simple)
    print(format_report(combined))


if __name__ == "__main__":
