def xor_cipher(text, key_char):
    """XOR every character of `text` with the single character `key_char`."""
    if len(key_char) != 1:
        raise ValueError("key_char must be exactly one character")
    key = ord(key_char)
    return ''.join(chr(ord(ch) ^ key) for ch in text)


def to_hex(data):
    """Render a string as space separated hexadecimal byte values."""
    return ' '.join('%02x' % ord(ch) for ch in data)


def char_frequencies(text):
    """Count how often each (lower-cased) character occurs in `text`."""
    freq = {}
    for ch in text.lower():
        freq[ch] = freq.get(ch, 0) + 1
    return freq


def is_printable(text):
    return all(32 <= ord(ch) <= 126 for ch in text)


ENGLISH_WEIGHTS = {
    ' ': 15.0, 'e': 12.7, 't': 9.1, 'a': 8.2, 'o': 7.5, 'i': 7.0, 'n': 6.7,
    's': 6.3, 'h': 6.1, 'r': 6.0, 'd': 4.3, 'l': 4.0, 'c': 2.8, 'u': 2.8,
    'm': 2.4, 'w': 2.4, 'f': 2.2, 'g': 2.0, 'y': 2.0, 'p': 1.9, 'b': 1.5,
}


def english_score(text):
    """Average English-likeness weight per character of `text`."""
    freq = char_frequencies(text)
    total = sum(freq.values())
    if total == 0:
        return 0.0
    score = 0.0
    for ch, count in freq.items():
        score += ENGLISH_WEIGHTS.get(ch, 0.0) * count
    return score / total


def rank_keys(cipher):
    """Score every printable single-character key against `cipher`."""
    scores = {}
    for code in range(32, 127):
        candidate = xor_cipher(cipher, chr(code))
        if is_printable(candidate):
            scores[chr(code)] = english_score(candidate)
    return scores


def crack(cipher):
    """Return the best scoring key for `cipher` and the decrypted text."""
    best_key = None
    best_score = -1.0
    for key_char, score in rank_keys(cipher).items():
        if score > best_score:
            best_key = key_char
            best_score = score
    return best_key, xor_cipher(cipher, best_key)


def main():
    samples = {'Hello': 'A', 'Test': 'B', 'the quick brown fox': 'K'}
    for plain, key_char in samples.items():
        cipher = xor_cipher(plain, key_char)
        print('%-20s key=%r  ->  %s' % (plain, key_char, to_hex(cipher)))
        print('   round trip: %r' % xor_cipher(cipher, key_char))

    secret = xor_cipher('attack the bridge at dawn', 'q')
    found_key, recovered = crack(secret)
    print('cracked key: %r -> %r' % (found_key, recovered))

    letters = char_frequencies(recovered)
    for ch in sorted(letters.keys()):
        if ch.isalpha():
            print('  %s: %d' % (ch, letters[ch]))


if __name__ == '__main__':
    main()

