def normalize(s):
    cleaned = []
    for ch in s:
        if ch.isalnum():
            cleaned.append(ch.lower())
    return "".join(cleaned)


def is_palindrome_string(s):
    text = normalize(s)
    for i in range(len(text) // 2):
        if text[i] != text[len(text) - 1 - i]:
            return False
    return True


def character_counts(s):
    counts = {}
    for ch in normalize(s):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def odd_count_characters(counts):
    odd = []
    for ch, total in counts.items():
        if total % 2 == 1:
            odd.append(ch)
    odd.sort()
    return odd


def alphabet_used(counts):
    return "".join(sorted(counts.keys()))


def can_rearrange_to_palindrome(counts):
    return len(odd_count_characters(counts)) <= 1


def longest_palindromic_span(s):
    text = normalize(s)
    best_start, best_length = 0, 0
    for center in range(len(text)):
        for offset in range(2):
            left, right = center, center + offset
            while left >= 0 and right < len(text) and text[left] == text[right]:
                left -= 1
                right += 1
            length = right - left - 1
            if length > best_length:
                best_start, best_length = left + 1, length
    return text[best_start:best_start + best_length]


def describe(s):
    counts = character_counts(s)
    return {
        "input": s,
        "normalized": normalize(s),
        "palindrome": is_palindrome_string(s),
        "alphabet": alphabet_used(counts),
        "normalized_length": sum(counts.values()),
        "odd_characters": "".join(odd_count_characters(counts)),
        "rearrangeable": can_rearrange_to_palindrome(counts),
        "longest_span": longest_palindromic_span(s),
    }


def main():
    samples = [
        "Racecar",
        "A man, a plan, a canal: Panama",
        "Hello, World!",
        "No 'x' in Nixon",
        "",
    ]
    for index, sample in enumerate(samples, 1):
        print("sample {0}:".format(index))
        for field, value in describe(sample).items():
            print("  {0:<20} {1!r}".format(field, value))


if __name__ == "__main__":
    main()

