def cartesian_product(list1, list2):
    """Return all ordered pairs (a, b) with a from list1 and b from list2."""
    pairs = []
    for i in range(len(list1)):
        for j in range(len(list2)):
            pairs.append((list1[i], list2[j]))
    return pairs


def group_by_first(pairs):
    """Map each first component to the list of second components paired with it."""
    groups = {}
    for first, second in pairs:
        groups.setdefault(first, []).append(second)
    return groups


def count_by_first(pairs):
    """Map each first component to how many pairs start with it."""
    counts = {}
    for first, seconds in group_by_first(pairs).items():
        counts[first] = len(seconds)
    return counts


def format_groups(pairs):
    """Render the grouping as lines like '1 -> a, b'."""
    lines = []
    for first, seconds in group_by_first(pairs).items():
        lines.append("{} -> {}".format(first, ", ".join(str(s) for s in seconds)))
    return lines


def product_matrix(list1, list2):
    """Return a row-per-element-of-list1 matrix of the pairs."""
    pairs = cartesian_product(list1, list2)
    width = len(list2)
    matrix = []
    for row in range(len(list1)):
        start = row * width
        matrix.append([pairs[start + col] for col in range(width)])
    return matrix


def is_balanced(pairs):
    """True when every first component appears the same number of times."""
    sizes = set(count_by_first(pairs).values())
    return len(sizes) <= 1


def main():
    cases = [
        ([1, 2], ['a', 'b']),
        ([1], []),
        ([], ['a']),
        ([1, 2, 3], ['x', 'y']),
    ]
    for index in range(len(cases)):
        first_list, second_list = cases[index]
        pairs = cartesian_product(first_list, second_list)
        print("case {}: {} x {}".format(index, first_list, second_list))
        print("  pairs: {}".format(pairs))
        for line in format_groups(pairs):
            print("  " + line)
        print("  balanced: {}".format(is_balanced(pairs)))

    totals = count_by_first(cartesian_product([1, 2, 3], ['x', 'y']))
    print("firsts seen: {}".format(sorted(totals.keys())))
    print("pairs per first: {}".format(sum(totals.values())))

    for row in product_matrix([1, 2], ['a', 'b']):
        print(" | ".join("{}{}".format(a, b) for a, b in row))


if __name__ == "__main__":
    main()

