TO_CELSIUS = {
    'C': lambda v: v,
    'F': lambda v: (v - 32.0) * 5.0 / 9.0,
    'K': lambda v: v - 273.15,
}

FROM_CELSIUS = {
    'C': lambda c: c,
    'F': lambda c: c * 9.0 / 5.0 + 32.0,
    'K': lambda c: c + 273.15,
}

UNIT_NAMES = {'C': 'Celsius', 'F': 'Fahrenheit', 'K': 'Kelvin'}


def convert_temperature(value, unit_from, unit_to):
    celsius = TO_CELSIUS[unit_from](float(value))
    return float(FROM_CELSIUS[unit_to](celsius))


def conversion_table(value, unit_from):
    table = {}
    for unit in FROM_CELSIUS.keys():
        table[unit] = convert_temperature(value, unit_from, unit)
    return table


def format_table(table):
    lines = []
    for unit, converted in table.items():
        lines.append("{:<10} {:>10.2f} {}".format(UNIT_NAMES[unit], converted, unit))
    return "\n".join(lines)


def numeric_spread(table):
    numbers = list(table.values())
    return max(numbers) - min(numbers)


def sample_series(start, stop, steps, unit_from, unit_to):
    """Convert `steps` evenly spaced temperatures from start to stop (inclusive)."""
    if steps < 2:
        raise ValueError("steps must be at least 2")
    width = (stop - start) / (steps - 1)
    series = []
    for i in range(steps):
        series.append(convert_temperature(start + i * width, unit_from, unit_to))
    return series


def series_summary(series):
    return {
        'min': min(series),
        'max': max(series),
        'mean': sum(series) / len(series),
    }


def hottest_unit(table):
    hottest = None
    for unit, converted in table.items():
        if hottest is None or converted > table[hottest]:
            hottest = unit
    return hottest


def main():
    readings = {'C': 0.0, 'F': 98.6, 'K': 273.15}
    for unit, value in readings.items():
        table = conversion_table(value, unit)
        print("{:.2f} {} expressed in every scale:".format(value, unit))
        print(format_table(table))
        print("largest numeric value: {}".format(UNIT_NAMES[hottest_unit(table)]))
        print("numeric spread: {:.2f}\n".format(numeric_spread(table)))

    series = sample_series(-40.0, 100.0, 8, 'C', 'F')
    print("Celsius -40..100 in Fahrenheit:")
    for i in range(len(series)):
        print("  point {}: {:.2f} F".format(i, series[i]))

    for label, stat in series_summary(series).items():
        print("{}: {:.2f} F".format(label, stat))


if __name__ == '__main__':
    main()

