_DIGITS = "0123456789abcdef"
HEX_VALUES = {}
for _index in range(len(_DIGITS)):
    HEX_VALUES[_DIGITS[_index]] = _index

NAMED_COLORS = {
    "black": {"r": 0, "g": 0, "b": 0},
    "white": {"r": 255, "g": 255, "b": 255},
    "red": {"r": 255, "g": 0, "b": 0},
    "green": {"r": 0, "g": 128, "b": 0},
    "blue": {"r": 0, "g": 0, "b": 255},
    "gray": {"r": 128, "g": 128, "b": 128},
}


def is_valid_hex_color(code):
    if not isinstance(code, str) or len(code) not in (4, 7):
        return False
    if code[0] != "#":
        return False
    for position in range(1, len(code)):
        if code[position].lower() not in HEX_VALUES:
            return False
    return True


def expand_hex_color(code):
    body = code[1:]
    if len(body) == 6:
        return "#" + body.lower()
    expanded = ""
    for position in range(3):
        expanded += body[position].lower() * 2
    return "#" + expanded


def hex_to_rgb(code):
    body = expand_hex_color(code)[1:]
    labels = ("r", "g", "b")
    channels = {}
    for position in range(3):
        high = HEX_VALUES[body[position * 2]]
        low = HEX_VALUES[body[position * 2 + 1]]
        channels[labels[position]] = high * 16 + low
    return channels


def dominant_channel(channels):
    best_label = "r"
    for label, value in channels.items():
        if value > channels[best_label]:
            best_label = label
    return best_label


def nearest_named_color(channels):
    best_name = None
    best_distance = None
    for name, reference in NAMED_COLORS.items():
        distance = 0
        for label in channels.keys():
            difference = channels[label] - reference[label]
            distance += difference * difference
        if best_distance is None or distance < best_distance:
            best_name = name
            best_distance = distance
    return best_name


def describe_color(code):
    channels = hex_to_rgb(code)
    brightness = sum(channels.values()) / 3.0
    parts = []
    for label, value in channels.items():
        parts.append("%s=%d" % (label.upper(), value))
    return "%s -> %s | brightness %.1f | dominant %s | nearest %s" % (
        expand_hex_color(code),
        " ".join(parts),
        brightness,
        dominant_channel(channels),
        nearest_named_color(channels),
    )


def main():
    codes = ["#ABC", "#123456", "#GGGGGG", "#fff", "#12", "abc123", "#0080FF"]
    results = {}
    for code in codes:
        results[code] = is_valid_hex_color(code)
    for code, valid in results.items():
        if valid:
            print("%-9s valid   %s" % (code, describe_color(code)))
        else:
            print("%-9s invalid" % code)
    valid_total = sum(1 for valid in results.values() if valid)
    print("%d of %d codes are valid" % (valid_total, len(results)))


if __name__ == "__main__":
    main()

