def rotate_list(lst, n):
    """Return a new list with elements of lst rotated n positions to the right."""
    size = len(lst)
    if size == 0:
        return []
    shift = n % size
    rotated = []
    for i in range(size):
        rotated.append(lst[(i - shift) % size])
    return rotated


def all_rotations(lst):
    """Map every distinct right-shift amount to the corresponding rotation."""
    table = {}
    for shift in range(len(lst)):
        table[shift] = rotate_list(lst, shift)
    return table


def find_shift(original, candidate):
    """Return the smallest right-shift turning original into candidate, or None."""
    if len(original) != len(candidate):
        return None
    for shift, rotated in all_rotations(original).items():
        if rotated == candidate:
            return shift
    return None


def is_rotation(original, candidate):
    return find_shift(original, candidate) is not None


def format_rotations(lst):
    """Build printable lines for each rotation of lst, aligned on the shift."""
    table = all_rotations(lst)
    widths = [len(str(shift)) for shift in table.keys()]
    width = max(widths) if widths else 1
    lines = []
    for shift in sorted(table.keys()):
        body = ", ".join(str(item) for item in table[shift])
        lines.append("shift {0:>{1}}: [{2}]".format(shift, width, body))
    return lines


def rotation_period(lst):
    """Smallest positive shift that maps lst onto itself."""
    table = all_rotations(lst)
    for shift in range(1, len(lst) + 1):
        if table.get(shift % len(lst)) == lst:
            return shift
    return 1


def main():
    samples = {
        "basic right": ([1, 2, 3, 4, 5], 2),
        "single left": ([1, 2, 3], -1),
        "wrap around": (["a", "b", "c", "d"], 6),
        "empty": ([], 3),
        "uniform": ([7, 7, 7], 1),
    }
    for label, (data, amount) in samples.items():
        print("{0:>12} {1} by {2} -> {3}".format(label, data, amount, rotate_list(data, amount)))

    demo = [10, 20, 30, 40]
    for line in format_rotations(demo):
        print(line)

    print("period of", demo, "is", rotation_period(demo))
    print("period of [7, 7, 7] is", rotation_period([7, 7, 7]))

    probes = [[30, 40, 10, 20], [20, 30, 40, 10], [10, 20, 40, 30]]
    for index in range(len(probes)):
        print(probes[index], "rotation of demo:", is_rotation(demo, probes[index]),
              "shift:", find_shift(demo, probes[index]))


if __name__ == "__main__":
    main()

