def common_keys(dict1, dict2):
    """Return the set of keys that appear in both dictionaries."""
    shared = set()
    for key in dict1.keys():
        if key in dict2:
            shared.add(key)
    return shared


def common_keys_across(dicts):
    """Return the keys shared by every dictionary in the given sequence."""
    if not dicts:
        return set()
    shared = set(dicts[0].keys())
    for index in range(1, len(dicts)):
        shared = common_keys(dict.fromkeys(shared), dicts[index])
    return shared


def conflicting_values(dict1, dict2):
    """Map each shared key to the pair of differing values it holds."""
    conflicts = {}
    for key, value in dict1.items():
        if key in dict2 and dict2[key] != value:
            conflicts[key] = (value, dict2[key])
