NIBBLE_BITS = {}
for value in range(16):
    bits = 0
    for shift in range(4):
        bits += (value >> shift) & 1
    NIBBLE_BITS[value] = bits


def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be a non-negative integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    nibbles = (n.bit_length() + 3) // 4
    total = 0
    for index in range(nibbles):
        total += NIBBLE_BITS[(n >> (4 * index)) & 0xF]
    return total


def popcount_table(start, stop):
    """Map every integer in [start, stop) to its population count."""
    table = {}
    for number in range(start, stop):
        table[number] = count_set_bits(number)
    return table


def bit_frequency(table):
    """Count how many numbers share each population count."""
    frequency = {}
    for bits in table.values():
        frequency[bits] = frequency.get(bits, 0) + 1
    return frequency


def densest_numbers(table):
    """Return the numbers holding the largest population count in the table."""
    peak = max(table.values())
    return [number for number, bits in table.items() if bits == peak]


def format_table(table):
    """Render the table as aligned 'decimal binary count' lines."""
    width = max(number.bit_length() for number in table.keys()) or 1
    lines = []
    for number, bits in sorted(table.items()):
        lines.append("{:>4}  {:>{w}}  {}".format(number, format(number, "b"), bits, w=width))
    return lines


def main():
    table = popcount_table(0, 32)
    for line in format_table(table):
        print(line)

    print("\nnumbers grouped by population count:")
    frequency = bit_frequency(table)
    for bits in sorted(frequency.keys()):
        members = [number for number, count in table.items() if count == bits]
        print("  {} bit(s): {:>2} numbers -> {}".format(bits, frequency[bits], members))

    print("\ndensest entries:", densest_numbers(table))
    for power in range(1, 6):
        edge = (1 << power) - 1
        print("count_set_bits({}) = {}".format(edge, count_set_bits(edge)))


if __name__ == "__main__":
    main()

