def generate_permutations(lst):
    """Return a list containing every ordering of the elements of lst."""
    if len(lst) <= 1:
        return [list(lst)]
    permutations = []
    for i in range(len(lst)):
        remainder = lst[:i] + lst[i + 1:]
        for tail in generate_permutations(remainder):
            permutations.append([lst[i]] + tail)
    return permutations


def factorial(n):
    total = 1
    for k in range(2, n + 1):
        total *= k
    return total


def position_frequency(permutations):
    """Map each position index to a dict of element -> how often it appears there."""
    frequency = {}
    if not permutations:
        return frequency
    width = len(permutations[0])
    for index in range(width):
        counts = {}
        for perm in permutations:
            element = perm[index]
            counts[element] = counts.get(element, 0) + 1
        frequency[index] = counts
    return frequency


def format_frequency_table(frequency):
    lines = []
    for index, counts in frequency.items():
        parts = []
        for element, count in counts.items():
            parts.append("{0}x{1}".format(element, count))
        lines.append("position {0}: {1}".format(index, ", ".join(parts)))
    return "\n".join(lines)


def most_common_per_position(frequency):
    """For each position, the element that appears there most often."""
    winners = {}
    for index, counts in frequency.items():
        best = None
        for element, count in counts.items():
            if best is None or count > counts[best]:
                best = element
        winners[index] = best
    return winners


def summarize(lst):
    permutations = generate_permutations(lst)
    frequency = position_frequency(permutations)
    distinct = len(set(tuple(perm) for perm in permutations))
    return {
        "input": lst,
        "permutations": permutations,
        "expected_count": factorial(len(lst)),
        "distinct_count": distinct,
        "frequency": frequency,
    }


def main():
    samples = [[1, 2], ['a'], [], ['x', 'y', 'z'], [1, 1, 2]]
    for sample in samples:
        report = summarize(sample)
        print("input: {0}".format(report["input"]))
        print("permutations: {0}".format(report["permutations"]))
        print("count: {0} (expected {1}, distinct {2})".format(
            len(report["permutations"]),
            report["expected_count"],
            report["distinct_count"],
        ))
        table = format_frequency_table(report["frequency"])
        if table:
            print(table)
        for index, element in most_common_per_position(report["frequency"]).items():
            print("position {0} favours {1}".format(index, element))
        print("-" * 40)


if __name__ == "__main__":
    main()

