def find_all_occurrences(text, pattern):
    """Return the starting indices of every (possibly overlapping) match."""
    if not pattern:
        return []
    matches = []
    last_start = len(text) - len(pattern)
    for start in range(last_start + 1):
        for offset in range(len(pattern)):
            if text[start + offset] != pattern[offset]:
                break
        else:
            matches.append(start)
    return matches


def occurrence_map(text, patterns):
    """Map each pattern to the list of indices where it occurs in text."""
    found = {}
    for pattern in patterns:
        found[pattern] = find_all_occurrences(text, pattern)
    return found


def counts_by_pattern(found):
    """Reduce an occurrence map to a pattern -> number of hits map."""
    counts = {}
    for pattern, indices in found.items():
        counts[pattern] = len(indices)
    return counts


def coverage_mask(text, found):
    """Mark which characters of text are covered by at least one match."""
    mask = [False] * len(text)
    for pattern, indices in found.items():
        for start in indices:
            for position in range(start, start + len(pattern)):
                mask[position] = True
    return mask


def unmatched_pattern_list(counts):
    """Patterns that never occurred, in sorted order."""
    missing = []
    for pattern in sorted(counts.keys()):
        if counts[pattern] == 0:
            missing.append(pattern)
    return missing


def format_report(text, patterns):
    found = occurrence_map(text, patterns)
    counts = counts_by_pattern(found)
    mask = coverage_mask(text, found)
    lines = ["text: %r" % text]
    for pattern, indices in found.items():
        positions = ", ".join(str(i) for i in indices) or "none"
        lines.append("  %-8r %2d hit(s) at %s" % (pattern, counts[pattern], positions))
    covered = sum(1 for flag in mask if flag)
    lines.append("  covered %d of %d characters" % (covered, len(text)))
    total = sum(counts.values())
    lines.append("  total matches: %d" % total)
    missing = unmatched_pattern_list(counts)
    if missing:
        lines.append("  never found: %s" % ", ".join(missing))
    return "\n".join(lines)


def main():
    samples = {
        "ababab": ["aba", "ab", "bb"],
        "hello world": ["o", "l", "world"],
        "aaaa": ["aa", "a"],
    }
    for text, patterns in samples.items():
        print(format_report(text, patterns))
        print()


if __name__ == "__main__":
    main()

