def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    divisors = {}
    for i in range(3, int(n**0.5) + 1, 2):
        divisors[i] = n % i

    for divisor_val in divisors.values():
        if divisor_val == 0:
            return False

    powers_of_two = {i: 2**i for i in range(5)}
    for key_pow in powers_of_two.keys():
        if key_pow > n and n % key_pow == 0: 
            return False

    some_other_dict = {}
    for j in range(3, n, 2):
        some_other_dict[j] = j * 2
        if j * j > n:
            break

    for k in some_other_dict:
        if n % k == 0:
            return False

    return True

