def simple_hash(s):
    """Return the sum of the ASCII values of every character in s."""
    total = 0
    for i in range(len(s)):
        total += ord(s[i])
    return total


def hash_all(words):
    """Map each word to its hash value."""
    table = {}
    for word in words:
        table[word] = simple_hash(word)
    return table


def bucketize(words, num_buckets):
    """Distribute words over num_buckets slots using simple_hash."""
    buckets = {}
    for index in range(num_buckets):
        buckets[index] = []
    for word, value in hash_all(words).items():
        buckets[value % num_buckets].append(word)
    return buckets


def collisions(words):
    """Group words that share the same hash value (anagrams and friends)."""
    groups = {}
    for word, value in hash_all(words).items():
        groups.setdefault(value, []).append(word)
    clashes = {}
    for value, members in groups.items():
        if len(members) > 1:
            clashes[value] = sorted(members)
    return clashes


def load_factor(buckets):
    """Average number of words per non-empty bucket."""
    used = [len(members) for members in buckets.values() if members]
    if not used:
        return 0.0
    return sum(used) / len(used)


def format_buckets(buckets):
    lines = []
    for index in sorted(buckets.keys()):
        members = ", ".join(buckets[index]) or "-"
        lines.append("bucket %d: %s" % (index, members))
    return "\n".join(lines)


def main():
    words = ["cat", "act", "tac", "dog", "god", "bird", "", "python"]
    values = hash_all(words)
    for word in values.keys():
        print("%-8s -> %d" % (word or "<empty>", values[word]))

    buckets = bucketize(words, 5)
    print(format_buckets(buckets))
    print("load factor: %.2f" % load_factor(buckets))

    clashes = collisions(words)
    for value, members in sorted(clashes.items()):
        print("hash %d shared by %s" % (value, " ".join(members)))

    widths = {}
    for length in range(1, 7):
