def calculate_factorial(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def factorial_table(limit):
    table = {}
    for n in range(limit + 1):
        table[n] = calculate_factorial(n)
    return table


def trailing_zeros(value):
    zeros = 0
    text = str(value)
    for index in range(len(text) - 1, -1, -1):
        if text[index] != "0":
            break
        zeros += 1
    return zeros


def digit_counts(value):
    counts = {}
    for digit in str(value):
        counts[digit] = counts.get(digit, 0) + 1
    return counts


def column_widths(table):
    widths = {"n": 1, "n!": 2, "digits": 6, "zeros": 5}
    for n, value in table.items():
        widths["n"] = max(widths["n"], len(str(n)))
        widths["n!"] = max(widths["n!"], len(str(value)))
    return widths


def format_row(cells, widths):
    padded = []
    for index in range(len(cells)):
        padded.append(cells[index].rjust(widths[index]))
    return "  ".join(padded)


def format_table(table):
    widths = column_widths(table)
    sizes = list(widths.values())
    lines = [format_row(list(widths.keys()), sizes)]
    lines.append("-" * len(lines[0]))
    for n in sorted(table.keys()):
        value = table[n]
        cells = [str(n), str(value), str(len(str(value))), str(trailing_zeros(value))]
        lines.append(format_row(cells, sizes))
    return "\n".join(lines)


def main():
    table = factorial_table(12)
    print(format_table(table))
    print()
    for n in (0, 5, 20):
        print("{}! = {}".format(n, calculate_factorial(n)))
    print()
    counts = digit_counts(calculate_factorial(25))
    print("digit frequencies in 25!:")
    for digit in sorted(counts.keys()):
        print("  {} appears {} time(s)".format(digit, counts[digit]))
    print("  total digits: {}".format(sum(counts.values())))


if __name__ == "__main__":
