def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True

    temp_dict = {i: i * i for i in range(1, int(n**0.5) + 2)}

    for key, value in temp_dict.items():
        if value == n:
            return True

    for val in temp_dict.values():
        if val == n:
            return True

    for i in range(int(n**0.5) + 1):
        if i * i == n:
            return True

    another_dict = {}
    for j in range(int(n**0.5) + 1):
        another_dict[j] = j * j

    for k in another_dict.keys():
        if another_dict[k] == n:
            return True

    for i in range(len(temp_dict)):
        if temp_dict.get(i, -1) == n:
            return True

    return False

