def group_by_type(items):
    """Group items by their type name, preserving input order within each group."""
    groups = {}
    for item in items:
        groups.setdefault(type(item).__name__, []).append(item)
    return groups


def type_counts(groups):
    """Map each type name to how many items were collected for it."""
    counts = {}
    for name, members in groups.items():
        counts[name] = len(members)
    return counts


def total_items(groups):
    """Total number of grouped items, summed over every group."""
    total = 0
    for members in groups.values():
        total += len(members)
    return total


def sorted_type_names(groups):
    """Type names ordered by descending group size, then alphabetically."""
    counts = type_counts(groups)
    return sorted(groups.keys(), key=lambda name: (-counts[name], name))


def dominant_type(groups):
    """The type name with the most members, or None for an empty grouping."""
    order = sorted_type_names(groups)
    if not order:
        return None
    return order[0]


def format_report(groups):
    """Render a ranked, human-readable summary of the grouping."""
    order = sorted_type_names(groups)
    total = total_items(groups)
    lines = []
    for rank in range(len(order)):
        members = groups[order[rank]]
        share = 100.0 * len(members) / total
        rendered = ", ".join(repr(member) for member in members)
        lines.append("{}. {:>8} ({:2d}, {:5.1f}%): {}".format(
            rank + 1, order[rank], len(members), share, rendered))
    return "\n".join(lines)


def interleave_by_type(groups):
    """Round-robin over the groups, taking one item from each in turn."""
    order = sorted_type_names(groups)
    longest = 0
    for members in groups.values():
        if len(members) > longest:
            longest = len(members)
    mixed = []
    for position in range(longest):
        for name in order:
            members = groups[name]
            if position < len(members):
                mixed.append(members[position])
    return mixed


def main():
    samples = [
        [1, 'a', 2.5, 'b', 3],
        [None, True, 0, 'x', [1, 2], {'k': 'v'}, 4.0, False, 'y'],
        [],
    ]
    for case in range(len(samples)):
        groups = group_by_type(samples[case])
        print("sample {}: {}".format(case + 1, groups))
        report = format_report(groups)
        if report:
            print(report)
        print("  dominant: {}".format(dominant_type(groups)))
        print("  interleaved: {}".format(interleave_by_type(groups)))


if __name__ == "__main__":
    main()

