def remove_duplicates_preserve_order(lst):
    """Return a new list without duplicates, keeping first-appearance order."""
    seen = set()
    unique = []
    for i in range(len(lst)):
        item = lst[i]
        if item not in seen:
            seen.add(item)
            unique.append(item)
    return unique


def count_occurrences(lst):
    """Map every element to the number of times it appears in lst."""
    counts = {}
    for i in range(len(lst)):
        item = lst[i]
        counts[item] = counts.get(item, 0) + 1
    return counts


def duplicate_positions(lst):
    """Map repeated elements to the indices that get dropped as duplicates."""
    positions = {}
    for i in range(len(lst)):
        positions.setdefault(lst[i], []).append(i)
    repeats = {}
    for item, indices in positions.items():
        if len(indices) > 1:
            repeats[item] = indices[1:]
    return repeats


def total_removed(lst):
    """Number of elements that removing duplicates discards."""
    removed = 0
    for occurrences in count_occurrences(lst).values():
        removed += occurrences - 1
    return removed


def format_counts(counts):
    lines = []
    for item, occurrences in counts.items():
        lines.append("  {!r}: {}".format(item, occurrences))
    return "\n".join(lines)


def summarize(lst):
    """Build a readable report about de-duplicating lst."""
    unique = remove_duplicates_preserve_order(lst)
    lines = ["input:  {!r}".format(lst), "unique: {!r}".format(unique)]
    counts = count_occurrences(lst)
    if counts:
        lines.append("counts:")
        lines.append(format_counts(counts))
    repeats = duplicate_positions(lst)
    if repeats:
        lines.append("dropped indices:")
        for item, indices in repeats.items():
            lines.append("  {!r} at {}".format(item, indices))
    lines.append("dropped total: {}".format(total_removed(lst)))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a'],
        [],
        [7, 7, 7, 8, 9, 8],
    ]
    for i in range(len(samples)):
        print("--- sample {} ---".format(i + 1))
        print(summarize(samples[i]))


if __name__ == "__main__":
    main()

