import re

OCTET = r"(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])"
IPV4_RE = re.compile(r"\A" + OCTET + r"(?:\." + OCTET + r"){3}\Z")

PRIVATE_BLOCKS = {
    "10.0.0.0/8": 8,
    "172.16.0.0/12": 12,
    "192.168.0.0/16": 16,
    "127.0.0.0/8": 8,
}

CLASS_RANGES = {
    "A": (0, 127),
    "B": (128, 191),
    "C": (192, 223),
    "D": (224, 239),
    "E": (240, 255),
}


def is_valid_ipv4(ip_address):
    if not isinstance(ip_address, str):
        return False
    return IPV4_RE.match(ip_address) is not None


def octets(ip_address):
    return [int(part) for part in ip_address.split(".")]


def mask_octets(prefix_bits):
    masks = []
    for index in range(4):
        remaining = prefix_bits - 8 * index
        if remaining >= 8:
            masks.append(255)
        elif remaining <= 0:
            masks.append(0)
        else:
            masks.append((0xFF << (8 - remaining)) & 0xFF)
    return masks


def in_block(ip_address, block, prefix_bits):
    base = octets(block.split("/")[0])
    target = octets(ip_address)
    masks = mask_octets(prefix_bits)
    for index in range(4):
        if base[index] & masks[index] != target[index] & masks[index]:
            return False
    return True


def private_block_of(ip_address):
    for block, prefix_bits in PRIVATE_BLOCKS.items():
        if in_block(ip_address, block, prefix_bits):
            return block
    return None


def address_class(ip_address):
    first = octets(ip_address)[0]
    for name, (low, high) in CLASS_RANGES.items():
        if low <= first <= high:
            return name
    return "?"


def summarize(addresses):
    counts = {"invalid": 0, "private": 0, "public": 0}
    for address in addresses:
        if not is_valid_ipv4(address):
            counts["invalid"] += 1
        elif private_block_of(address) is None:
            counts["public"] += 1
        else:
            counts["private"] += 1
    return counts


