    samples = ["192.168.1.1", "256.0.0.1", "10.20.30.40", "8.8.8.8",
               "172.16.5.5", "1.2.3", "01.2.3.4", "127.0.0.1"]
    print("private blocks checked: " + ", ".join(PRIVATE_BLOCKS.keys()))
