def calculate_percentage(part, whole):
    """Return part as a percentage of whole, or 0.0 when whole is zero."""
    if whole == 0:
        return 0.0
    return float(part) / float(whole) * 100.0


def tally_responses(responses, options):
    """Count how often each option appears in a list of responses."""
    counts = {}
    for option in options:
        counts[option] = 0
    for answer in responses:
        if answer in counts:
            counts[answer] += 1
    return counts


def percentage_breakdown(counts):
    """Map each option to its share of the total count."""
    total = sum(counts.values())
    shares = {}
    for option, count in counts.items():
        shares[option] = calculate_percentage(count, total)
    return shares


def bar(percent, width=20):
    """Render a percentage as a fixed-width text bar."""
    filled = int(round(percent / 100.0 * width))
    cells = []
    for i in range(width):
        if i < filled:
            cells.append("#")
        else:
            cells.append(".")
    return "".join(cells)


def format_report(title, counts):
    """Build the report lines for one question."""
    shares = percentage_breakdown(counts)
    width = 0
    for option in shares.keys():
        if len(option) > width:
            width = len(option)
    lines = [title, "-" * len(title)]
    for option, percent in shares.items():
        label = option.ljust(width)
        lines.append("%s %s %6.2f%% (%d)" % (label, bar(percent), percent, counts[option]))
    lines.append("total responses: %d" % sum(counts.values()))
    return lines


def turnout_table(counts, invited):
    """Percentage of invited people who answered each option."""
    table = {}
    for option in counts.keys():
        table[option] = calculate_percentage(counts[option], invited)
    return table


def main():
    options = ["python", "rust", "go", "java"]
    raw = ["python", "rust", "python", "go", "python", "java", "rust", "python"]
    counts = tally_responses(raw, options)

    for line in format_report("Favourite language", counts):
        print(line)

    invited = 12
    turnout = turnout_table(counts, invited)
    print("")
    print("Share of the %d invited people:" % invited)
    for option, percent in turnout.items():
        print("  %-8s %5.1f%%" % (option, percent))

    silent = invited - sum(counts.values())
    print("  %-8s %5.1f%%" % ("silent", calculate_percentage(silent, invited)))

    print("")
    print("Milestones toward full turnout:")
    for step in range(25, 125, 25):
        needed = int(round(invited * step / 100.0))
        print("  %3d%% needs %2d answers (have %d)" % (step, needed, sum(counts.values())))


if __name__ == "__main__":
    main()

