def simple_calculator(expression):
    parts = []
    current_num = ""
    for i in range(len(expression)):
        char = expression[i]
        if char.isdigit():
            current_num += char
        else:
            parts.append(int(current_num))
            parts.append(char)
            current_num = ""
    parts.append(int(current_num))

    result = parts[0]
    for j in range(1, len(parts), 2):
        operator = parts[j]
        operand = parts[j+1]
        if operator == '+':
            result += operand
        elif operator == '-':
            result -= operand
    return result

