import random

def generate_password(length):
    chars_map = {
        0: 'abcdefghijklmnopqrstuvwxyz',
        1: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
        2: '0123456789'
    }
    password_chars = []

    for i in range(length):
        category_index = random.choice(list(chars_map.keys()))
        selected_category = chars_map[category_index]
        password_chars.append(random.choice(selected_category))

    for key_idx in range(len(list(chars_map.keys()))):
        if not any(char in chars_map[key_idx] for char in password_chars):
            replace_index = random.choice(range(len(password_chars)))
            password_chars[replace_index] = random.choice(chars_map[key_idx])

    random.shuffle(password_chars)
    return "".join(password_chars)

