def list_to_dict(key_value_list):
    """Convert a list of [key, value] pairs into a dict, last value wins."""
    result = {}
    for i in range(len(key_value_list)):
        pair = key_value_list[i]
        if len(pair) != 2:
            raise ValueError("pair %d must have exactly 2 elements, got %d" % (i, len(pair)))
        key, value = pair
        result[key] = value
    return result


def count_duplicates(key_value_list):
    """Return how many times each key appears in the original pair list."""
    counts = {}
    for pair in key_value_list:
        key = pair[0]
        counts[key] = counts.get(key, 0) + 1
    return counts


def overwritten_keys(key_value_list):
    """Keys whose earlier values were discarded because they repeated."""
    counts = count_duplicates(key_value_list)
    repeated = []
    for key, times in counts.items():
        if times > 1:
            repeated.append(key)
    return repeated


def dict_to_list(mapping):
    """Inverse of list_to_dict: rebuild a list of [key, value] pairs."""
    pairs = []
    for key, value in mapping.items():
        pairs.append([key, value])
    return pairs


def invert(mapping):
    """Swap keys and values; later values win on collision."""
    flipped = {}
    for key in mapping.keys():
        flipped[mapping[key]] = key
    return flipped


def format_table(mapping):
    """Render a mapping as aligned 'key = value' lines."""
    width = 0
    for key in mapping.keys():
        width = max(width, len(str(key)))
    lines = []
    for key, value in mapping.items():
        lines.append("%s = %s" % (str(key).ljust(width), value))
    return "\n".join(lines)


def main():
    samples = [
        [['a', 1], ['b', 2]],
        [['x', 10], ['y', 20], ['x', 30]],
    ]
    for index in range(len(samples)):
        data = samples[index]
        mapping = list_to_dict(data)
        print("sample %d: %r" % (index, mapping))
        print(format_table(mapping))
        print("total of values:", sum(mapping.values()))
        repeated = overwritten_keys(data)
        if repeated:
            print("keys given more than once:", ", ".join(sorted(repeated)))
        print("round trip:", dict_to_list(mapping))
        print("inverted:", invert(mapping))
        print()


if __name__ == "__main__":
    main()

