def range_overlap(range1, range2):
    """Return the overlapping portion of two (start, end) ranges, or None."""
    start1, end1 = sorted(range1)
    start2, end2 = sorted(range2)
    overlap_start = max(start1, start2)
    overlap_end = min(end1, end2)
    if overlap_start > overlap_end:
        return None
    return (overlap_start, overlap_end)


def pairwise_overlaps(ranges):
    """Map every overlapping index pair to its overlap range."""
    found = {}
    for i in range(len(ranges)):
        for j in range(i + 1, len(ranges)):
            overlap = range_overlap(ranges[i], ranges[j])
            if overlap is not None:
                found[(i, j)] = overlap
    return found


def overlap_lengths(overlaps):
    """Length of each overlap, keyed the same way as the input mapping."""
    lengths = {}
    for pair in overlaps.keys():
        start, end = overlaps[pair]
        lengths[pair] = end - start
    return lengths


def coverage_histogram(ranges):
    """Count how many ranges cover each integer point."""
    histogram = {}
    for start, end in ranges:
        for point in range(int(start), int(end) + 1):
            histogram[point] = histogram.get(point, 0) + 1
    return histogram


def peak_coverage(histogram):
    """Highest coverage count and the sorted points reaching it."""
    best = max(histogram.values())
    hottest = []
    for point, count in histogram.items():
        if count == best:
            hottest.append(point)
    return best, sorted(hottest)


def format_overlap_report(named_ranges, overlaps):
    """Human readable lines describing the overlaps between named ranges."""
    names = list(named_ranges.keys())
    lines = []
    for (i, j), overlap in overlaps.items():
        length = overlap[1] - overlap[0]
        lines.append(
            "%s vs %s -> %s (length %s)" % (names[i], names[j], overlap, length)
        )
    return lines


def main():
    named_ranges = {
        "morning": (1, 5),
        "midday": (3, 7),
        "evening": (9, 12),
        "night": (11, 14),
    }
    ranges = list(named_ranges.values())

    for name, bounds in named_ranges.items():
        print("%-8s %s" % (name, bounds))

    overlaps = pairwise_overlaps(ranges)
    for line in format_overlap_report(named_ranges, overlaps):
        print(line)

    lengths = overlap_lengths(overlaps)
    print("total overlapping length:", sum(lengths.values()))

    histogram = coverage_histogram(ranges)
    best, hottest = peak_coverage(histogram)
    print("peak coverage:", best, "at points", hottest)

    print(range_overlap((1, 5), (3, 7)))
    print(range_overlap((1, 3), (5, 7)))


if __name__ == "__main__":
    main()

