def extract_digits(text):
    """Return a string of all decimal digits in `text`, preserving order."""
    if not isinstance(text, str):
        raise TypeError("extract_digits expects a string")
    return "".join(ch for ch in text if "0" <= ch <= "9")


def digit_positions(text):
    """Indices of `text` at which a decimal digit appears."""
    positions = []
    for i in range(len(text)):
        if "0" <= text[i] <= "9":
            positions.append(i)
    return positions


def digit_frequency(text):
    """Map each digit character found in `text` to how often it occurs."""
    counts = {}
    for ch in extract_digits(text):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def digit_sum(counts):
    """Numeric sum of all digits described by a frequency mapping."""
    total = 0
    for digit, times in counts.items():
        total += int(digit) * times
    return total


def most_common(counts):
    """Sorted list of the digits sharing the highest frequency."""
    if not counts:
        return []
    peak = max(counts.values())
    winners = [digit for digit, times in counts.items() if times == peak]
    return sorted(winners)


def distinct_digits(counts):
    """Digits present in a frequency mapping, in ascending order."""
    return sorted(counts.keys())


def digit_runs(text):
    """Split `text` into the maximal blocks of consecutive digits."""
    runs = []
    current = ""
    for ch in text:
        if "0" <= ch <= "9":
            current += ch
        elif current:
            runs.append(current)
            current = ""
    if current:
        runs.append(current)
    return runs


def grouped(digits, size=5):
    """Break a digit string into space-separated chunks of `size` digits."""
    chunks = []
    for start in range(0, len(digits), size):
        chunks.append(digits[start:start + size])
    return " ".join(chunks)


def histogram(counts):
    """Lines of the form `d: ***` for every digit present, in digit order."""
    lines = []
    for value in range(10):
        digit = str(value)
        if digit in counts:
            lines.append("  {}: {}".format(digit, "*" * counts[digit]))
    return lines


def report(text):
    counts = digit_frequency(text)
    digits = extract_digits(text)
    lines = ["input: {!r}".format(text), "digits: {!r}".format(digits)]
    lines.append("grouped: {}".format(grouped(digits) or "-"))
    lines.append("count: {}".format(sum(counts.values())))
    lines.append("sum: {}".format(digit_sum(counts)))
    lines.append("distinct: {}".format(" ".join(distinct_digits(counts)) or "-"))
    lines.append("positions: {}".format(digit_positions(text)))
    lines.append("runs: {}".format(", ".join(digit_runs(text)) or "-"))
    lines.append("most common: {}".format(" ".join(most_common(counts)) or "-"))
    lines.extend(histogram(counts))
    return "\n".join(lines)


