    samples = ["abc123def45", "NoDigitsHere", "2024-09-18 07:05", "a1b1c2c3d5"]
    for index, sample in enumerate(samples, start=1):
        print("--- sample {} ---".format(index))
        print(report(sample))


if __name__ == "__main__":
    main()

