def power_recursive(base, exponent):
    """Return base ** exponent for a non-negative integer exponent, recursively."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if exponent == 0:
        return 1
    half = power_recursive(base, exponent // 2)
    if exponent % 2 == 0:
        return half * half
    return half * half * base


def power_table(bases, max_exponent):
    """Map each base to the list of its powers from exponent 0 up to max_exponent."""
    table = {}
    for base in bases:
        table[base] = [power_recursive(base, e) for e in range(max_exponent + 1)]
    return table


def check_table(table):
    """Return the bases whose recursive powers disagree with the built-in operator."""
    wrong = []
    for base, powers in table.items():
        for exponent in range(len(powers)):
            if powers[exponent] != base ** exponent:
                wrong.append(base)
                break
    return wrong


def column_widths(table, max_exponent):
    """Width needed for the base column and for each exponent column."""
    base_width = max(len(str(base)) for base in table.keys())
    widths = []
    for exponent in range(max_exponent + 1):
        cells = [len(str(powers[exponent])) for powers in table.values()]
        widths.append(max(cells + [len(str(exponent))]))
    return base_width, widths


def format_table(table, max_exponent):
    """Render the power table as a list of aligned text lines."""
    base_width, widths = column_widths(table, max_exponent)
    header = "base".rjust(base_width)
    for exponent in range(max_exponent + 1):
        header += " " + str(exponent).rjust(widths[exponent])
    lines = [header, "-" * len(header)]
    for base, powers in table.items():
        row = str(base).rjust(base_width)
        for index in range(len(powers)):
            row += " " + str(powers[index]).rjust(widths[index])
        lines.append(row)
    return lines


def digit_sums(table):
    """Sum of the decimal digits of every power computed for each base."""
    sums = {}
    for base, powers in table.items():
        sums[base] = sum(int(ch) for value in powers for ch in str(abs(value)))
    return sums


def main():
    bases = [2, 3, 5, 10]
    max_exponent = 6
    table = power_table(bases, max_exponent)
    for line in format_table(table, max_exponent):
        print(line)
    mismatches = check_table(table)
    if mismatches:
        print("mismatching bases:", mismatches)
    print("\ndigit sums of all powers")
    sums = digit_sums(table)
    for base in sums.keys():
        print("  base {}: {}".format(base, sums[base]))
    print("total:", sum(sums.values()))
    print("\n2 ** 3 =", power_recursive(2, 3), " 5 ** 0 =", power_recursive(5, 0))


if __name__ == "__main__":
    main()

