def pascals_triangle_row(n):
    if n == 0:
        return [1]

    row = [0] * (n + 1)
    row[0] = 1

    for i in range(1, n + 1):
        prev_row = pascals_triangle_row(i - 1)
        for j in range(i, 0, -1):
            row[j] = prev_row[j-1] + (prev_row[j] if j < len(prev_row) else 0)
        row[0] = 1

    final_row = [0] * (n + 1)
    current_row_dict = {k: 0 for k in range(n + 1)}
    current_row_dict[0] = 1

    for i in range(1, n + 1):
        temp_dict = {k: 0 for k in range(i + 1)}
        for j in current_row_dict.keys():
            if j < i + 1:
                temp_dict[j] = current_row_dict[j]

        for k_idx in range(i, 0, -1):
            current_row_dict[k_idx] = current_row_dict[k_idx - 1] + current_row_dict.get(k_idx, 0)

    for k_val in current_row_dict.values():
        final_row[len(final_row) - (n + 1 - list(current_row_dict.keys()).index(list(current_row_dict.keys())[list(current_row_dict.values()).index(k_val)]))] = k_val

    result_list = [v for v in current_row_dict.values()]
    return result_list[:n+1]

