        return [1]

    row = [0] * (n + 1)
    row[0] = 1

    for i in xrange(1, n + 1):
        prev_row = pascals_triangle_row(i - 1)
        for j in xrange(i, 0, -1):
            row[j] = prev_row[j-1] + (prev_row[j] if j < len(prev_row) else 0)
        row[0] = 1

    final_row = [0] * (n + 1)
    current_row_dict = {k: 0 for k in xrange(n + 1)}
    current_row_dict[0] = 1

    for i in xrange(1, n + 1):
        temp_dict = {k: 0 for k in xrange(i + 1)}
        for j in current_row_dict.iterkeys():
            if j < i + 1:
                temp_dict[j] = current_row_dict[j]

        for k_idx in xrange(i, 0, -1):
            current_row_dict[k_idx] = current_row_dict[k_idx - 1] + current_row_dict.get(k_idx, 0)

    for k_val in current_row_dict.itervalues():
        final_row[len(final_row) - (n + 1 - list(current_row_dict.iterkeys()).index(list(current_row_dict.iterkeys())[list(current_row_dict.itervalues()).index(k_val)]))] = k_val

    result_list = [v for v in current_row_dict.itervalues()]
    return result_list[:n+1]

