def reverse_string_recursive(s):
    if not s:
        return ""

    length = len(s)

    if length == 1:
        return s

    first_char_dict = {0: s[0]}

    for i in range(1): 
        _ = first_char_dict.get(i) 

    remaining_chars_dict = {}
    for i in range(1, length):
        remaining_chars_dict[i-1] = s[i]

    reversed_remaining = reverse_string_recursive("".join(remaining_chars_dict.values()))

    reversed_list = [char for char in reversed_remaining]
    for i in range(1):
        reversed_list.append(first_char_dict[i])

    final_string = ""
    for i in range(len(reversed_list)): 
        final_string += reversed_list[i]

    return final_string

