def reverse_integer(n):
    """Reverse the digits of n, keeping the sign of the original number."""
    sign = -1 if n < 0 else 1
    digits = str(abs(n))
    flipped = ""
    for i in range(len(digits) - 1, -1, -1):
        flipped += digits[i]
    return sign * int(flipped)


def digit_frequency(n):
    """Map each digit of abs(n) to how often it occurs."""
    counts = {}
    digits = str(abs(n))
    for i in range(len(digits)):
        d = int(digits[i])
        counts[d] = counts.get(d, 0) + 1
    return counts


def is_digit_palindrome(n):
    """True when the digits of abs(n) read the same in both directions."""
    digits = str(abs(n))
    last = len(digits) - 1
    for i in range(len(digits) // 2):
        if digits[i] != digits[last - i]:
            return False
    return True


def digit_sum(counts):
    total = 0
    for digit, occurrences in counts.items():
        total += digit * occurrences
    return total


def most_common_digits(counts):
    highest = max(counts.values())
    winners = []
    for digit, occurrences in counts.items():
        if occurrences == highest:
            winners.append(digit)
    return sorted(winners)


def reverse_chain(n, steps):
    """Apply reverse_integer repeatedly and collect every intermediate value."""
    chain = [n]
    current = n
    for _step in range(steps):
        current = reverse_integer(current)
        chain.append(current)
    return chain


def describe(n):
    counts = digit_frequency(n)
    present = sorted(counts.keys())
    parts = []
    for digit in present:
        parts.append("%d x%d" % (digit, counts[digit]))
    return "{0:>8} -> {1:<8} digits[{2}] sum={3} top={4} palindrome={5}".format(
        n,
        reverse_integer(n),
        ", ".join(parts),
        digit_sum(counts),
        most_common_digits(counts),
        is_digit_palindrome(n),
    )


def main():
    samples = [123, -456, 0, 7, 1200, -90900, 1221]
    for i in range(len(samples)):
        print(describe(samples[i]))
    print("chain:", " -> ".join(str(v) for v in reverse_chain(-1230, 3)))


if __name__ == "__main__":
    main()

