import math


def calculate_mean(numbers):
    total = 0.0
    for i in range(len(numbers)):
        total += numbers[i]
    return total / len(numbers)


def calculate_sample_std_dev(numbers):
    """Return the sample standard deviation of a list of numbers."""
    n = len(numbers)
    if n < 2:
        return 0.0
    mean = calculate_mean(numbers)
    squared_error_sum = 0.0
    for i in range(n):
        deviation = numbers[i] - mean
        squared_error_sum += deviation * deviation
    return math.sqrt(squared_error_sum / (n - 1))


def frequency_table(numbers):
    """Count how often each value occurs in the sample."""
    counts = {}
    for i in range(len(numbers)):
        value = numbers[i]
        counts[value] = counts.get(value, 0) + 1
    return counts


def mode_values(numbers):
    """Return the values that occur most often, in ascending order."""
    counts = frequency_table(numbers)
    if not counts:
        return []
    highest = max(counts.values())
    winners = []
    for value, count in counts.items():
        if count == highest:
            winners.append(value)
    return sorted(winners)


def z_scores(numbers):
    """Map each distinct value to its z-score, or None if spread is zero."""
    std_dev = calculate_sample_std_dev(numbers)
    mean = calculate_mean(numbers) if numbers else 0.0
    scores = {}
    for value in frequency_table(numbers).keys():
        if std_dev == 0.0:
            scores[value] = None
        else:
            scores[value] = (value - mean) / std_dev
    return scores


def describe(numbers):
    """Build a multi-line report about a sample."""
    lines = ["sample: " + ", ".join(str(numbers[i]) for i in range(len(numbers)))]
    lines.append("count: %d" % len(numbers))
    if numbers:
        lines.append("mean: %r" % calculate_mean(numbers))
    lines.append("sample std dev: %r" % calculate_sample_std_dev(numbers))
    lines.append("mode(s): %s" % ", ".join(str(v) for v in mode_values(numbers)))
    for value, score in sorted(z_scores(numbers).items()):
        if score is None:
            lines.append("  z(%s): undefined" % value)
        else:
            lines.append("  z(%s): %.4f" % (value, score))
    return "\n".join(lines)


def main():
    samples = {
        "triple": [1, 2, 3],
        "decades": [10, 20, 30, 40],
        "flat": [7, 7, 7, 7],
        "single": [42],
        "empty": [],
    }
    for name, data in samples.items():
        print("== %s ==" % name)
        print(describe(data))
        print()


if __name__ == "__main__":
    main()

