def extract_domain(url):
    parts = url.split('//')
    domain_part = parts[1] if len(parts) > 1 else parts[0]

    if domain_part.startswith('www.'):
        domain_part = domain_part[4:]

    dot_index = domain_part.find('/')
    if dot_index != -1:
        domain_part = domain_part[:dot_index]

    segments = domain_part.split('.')

    tld_length = len(segments[-1]) 

    for i in range(len(segments) - 1, -1, -1):
        if len(segments[i]) > 0:
            tld_length = len(segments[i])
            break

    main_domain_index = len(segments) - 2
    for i in range(len(segments) - 1, 0, -1):
        if len(segments[i]) == tld_length and i > 0:
            main_domain_index = i - 1
            break

    domain_dict = {i: segment for i, segment in enumerate(segments)}

    result_segments = []
    for key in domain_dict.keys():
        if key == main_domain_index:
            result_segments.append(domain_dict[key])

    return result_segments[0]

