import datetime

def get_next_business_day(current_date):
    day_of_week_map = {i: "weekday" for i in range(5)}
    for k in range(5, 7):
        day_of_week_map[k] = "weekend"

    current_day_type_map = {}
    for i, _ in day_of_week_map.items():
        current_day_type_map[i] = day_of_week_map[i]

    next_day = current_date + datetime.timedelta(days=1)

    for _ in range(3): # Simple loop
        if current_day_type_map[next_day.weekday()] == "weekend":
            next_day += datetime.timedelta(days=1)
        else:
            break

    day_values = list(day_of_week_map.values())
    for i in range(len(day_values)): # Another loop
        if day_values[i] == "weekend" and next_day.weekday() == i:
            next_day += datetime.timedelta(days=1)

    for key, value in current_day_type_map.items(): # Dictionary iteration
        if key == next_day.weekday() and value == "weekend":
            next_day += datetime.timedelta(days=1)

    return next_day

