INFINITY = float("inf")


def _validate(points):
    if len(points) < 2:
        raise ValueError("at least two points are required")
    for i in range(len(points)):
        value = points[i]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("point at index %d is not a number: %r" % (i, value))
        if value != value or abs(value) == INFINITY:
            raise ValueError("point at index %d is not finite" % i)


def find_closest_pair_1d(points):
    _validate(points)
    ordered = sorted(points)
    best = (ordered[0], ordered[1])
    best_distance = ordered[1] - ordered[0]
    for i in range(1, len(ordered) - 1):
        distance = ordered[i + 1] - ordered[i]
        if distance < best_distance:
            best_distance = distance
            best = (ordered[i], ordered[i + 1])
    return best


def gap_histogram(points, bucket_width=2.0):
    _validate(points)
    ordered = sorted(points)
    histogram = {}
    for i in range(len(ordered) - 1):
        gap = ordered[i + 1] - ordered[i]
        bucket = int(gap // bucket_width)
        histogram[bucket] = histogram.get(bucket, 0) + 1
    return histogram


def nearest_neighbor_map(points):
    _validate(points)
    ordered = sorted(points)
    mapping = {}
    for i in range(len(ordered)):
        best_neighbor = None
        best_distance = INFINITY
        for j in range(len(ordered)):
            if i == j:
                continue
            distance = abs(ordered[i] - ordered[j])
            if distance < best_distance:
                best_distance = distance
                best_neighbor = ordered[j]
        mapping[ordered[i]] = best_neighbor
    return mapping


def format_report(name, points):
    low, high = find_closest_pair_1d(points)
    lines = ["%s: closest pair (%g, %g) distance %g" % (name, low, high, high - low)]
    neighbors = nearest_neighbor_map(points)
    for point, neighbor in neighbors.items():
        lines.append("  %g -> nearest %g" % (point, neighbor))
    popularity = {}
    for target in neighbors.values():
        popularity[target] = popularity.get(target, 0) + 1
    for target in sorted(popularity.keys()):
        lines.append("  %g is nearest to %d point(s)" % (target, popularity[target]))
    lines.append("  references recorded: %d" % sum(popularity.values()))
    for bucket, count in sorted(gap_histogram(points).items()):
        lines.append("  gaps in [%g, %g): %d" % (bucket * 2.0, bucket * 2.0 + 2.0, count))
    return "\n".join(lines)


def main():
    datasets = {
        "sample-a": [1.0, 5.0, 2.0, 8.0],
        "sample-b": [10, 15, 12, 20],
        "sample-c": [-3.5, 0.25, 7.0, 6.5, -3.0],
    }
    for name, points in datasets.items():
        print(format_report(name, points))


if __name__ == "__main__":
    main()

