QUADRANT_NAMES = {
    0: "on an axis",
    1: "quadrant I",
    2: "quadrant II",
    3: "quadrant III",
    4: "quadrant IV",
}


def get_quadrant(x, y):
    """Return the quadrant (1-4) containing (x, y), or 0 if it is on an axis."""
    if x == 0 or y == 0:
        return 0
    if x > 0:
        return 1 if y > 0 else 4
    return 2 if y > 0 else 3


def classify_points(points):
    """Return the quadrant of every point, in the same order as the input."""
    return [get_quadrant(x, y) for x, y in points]


def tally_quadrants(points):
    """Count how many points fall into each quadrant (and onto the axes)."""
    counts = {code: 0 for code in QUADRANT_NAMES.keys()}
    for code in classify_points(points):
        counts[code] += 1
    return counts


def empty_quadrants(counts):
    """Return the quadrant codes (1-4, axes excluded) that hold no point."""
    return [code for code in range(1, 5) if counts[code] == 0]


def parse_point(text):
    """Parse a point written as 'x,y' into a pair of floats."""
    fields = text.split(",")
    if len(fields) != 2:
        raise ValueError("a point needs exactly two coordinates: %r" % text)
    coords = []
    for field in fields:
        coords.append(float(field.strip()))
    return coords[0], coords[1]


def parse_points(texts):
    """Parse several points, reporting the position of a faulty entry."""
    points = []
    for i in range(len(texts)):
        try:
            points.append(parse_point(texts[i]))
        except ValueError as exc:
            raise ValueError("point %d: %s" % (i + 1, exc))
    return points


def format_point(x, y):
    parts = []
    for value in (x, y):
        parts.append("%g" % value)
    return "(" + ", ".join(parts) + ")"


def report(points):
    """Build a human-readable report of the classification of every point."""
    lines = []
    quadrants = classify_points(points)
    for i in range(len(points)):
        x, y = points[i]
        lines.append("%s lies %s" % (format_point(x, y), QUADRANT_NAMES[quadrants[i]]))
    counts = tally_quadrants(points)
    width = max(len(name) for name in QUADRANT_NAMES.values()) + 1
    for code, name in QUADRANT_NAMES.items():
        lines.append("%-*s %d point(s)" % (width, name + ":", counts[code]))
    lines.append("total: %d point(s)" % sum(counts.values()))
    missing = empty_quadrants(counts)
    if missing:
        lines.append("empty: " + ", ".join(QUADRANT_NAMES[code] for code in missing))
    return "\n".join(lines)


def main():
    raw = ["3,5", "-2,0", "-4,-7", "1.5,-2.5", "0,0", "-1,8"]
    print(report(parse_points(raw)))


if __name__ == "__main__":
    main()

