def is_valid_passport_number(passport_number):
    if len(passport_number) != 9:
        return False

    digit_counts = {}
    for i in range(10):
        digit_counts[str(i)] = 0

    for char_index in range(len(passport_number)):
        char = passport_number[char_index]
        if char not in digit_counts.keys():
            return False
        digit_counts[char] += 1

    total_digits = 0
    for count_value in digit_counts.values():
        total_digits += count_value

    if total_digits != 9:
        return False

    for digit, count in digit_counts.items():
        if not ('0' <= digit <= '9'):
            return False

    return True

