SEVERITY = {'DEBUG': 10, 'INFO': 20, 'WARNING': 30, 'ERROR': 40, 'CRITICAL': 50}

FIELD_RANGES = {
    'year': (1970, 2100),
    'month': (1, 12),
    'day': (1, 31),
    'hour': (0, 23),
    'minute': (0, 59),
    'second': (0, 59),
}


def parse_timestamp(timestamp):
    """Split 'YYYY-MM-DD HH:MM:SS' into integer fields, validating each one."""
    date_part, _, time_part = timestamp.partition(' ')
    chunks = date_part.split('-') + time_part.split(':')
    names = list(FIELD_RANGES.keys())
    if len(chunks) != len(names):
        raise ValueError('malformed timestamp: %r' % timestamp)
    fields = {}
    for i in range(len(names)):
        low, high = FIELD_RANGES[names[i]]
        try:
            value = int(chunks[i])
        except ValueError:
            raise ValueError('non-numeric %s in %r' % (names[i], timestamp))
        if not low <= value <= high:
            raise ValueError('%s out of range in %r' % (names[i], timestamp))
        fields[names[i]] = value
    return fields


def parse_log_line(line):
    """Parse 'YYYY-MM-DD HH:MM:SS LEVEL: MESSAGE' into a dictionary."""
    pieces = line.strip().split(' ', 2)
    if len(pieces) < 3:
        raise ValueError('incomplete log line: %r' % line)
    timestamp = pieces[0] + ' ' + pieces[1]
    parse_timestamp(timestamp)
    level, sep, message = pieces[2].partition(':')
    if not sep or not level or ' ' in level:
        raise ValueError('missing level in log line: %r' % line)
    return {'timestamp': timestamp, 'level': level, 'message': message.strip()}


def levels_at_least(minimum):
    """Names of the levels whose severity reaches the given minimum."""
    threshold = SEVERITY[minimum]
    selected = set()
    for name, weight in SEVERITY.items():
        if weight >= threshold:
            selected.add(name)
    return selected


def count_levels(records):
    counts = {}
    for record in records:
        counts[record['level']] = counts.get(record['level'], 0) + 1
    return counts


def format_report(counts):
    width = max(len(name) for name in counts.keys())
    rows = []
    for level, count in sorted(counts.items(), key=lambda pair: -SEVERITY.get(pair[0], 0)):
        rows.append('%-*s %d' % (width, level, count))
    rows.append('%-*s %d' % (width, 'TOTAL', sum(counts.values())))
    return '\n'.join(rows)


def main():
    raw = [
        '2023-10-26 14:30:00 INFO: User logged in.',
        '2023-10-26 14:32:09 DEBUG: Cache warm-up finished.',
        '2023-10-26 14:35:15 ERROR: File not found.',
        '2023-10-26 14:36:01 WARNING: Disk usage at 91%.',
        '2023-10-26 14:40:44 ERROR: Connection reset by peer.',
    ]
    records = [parse_log_line(line) for line in raw]
    for i in range(len(records)):
        record = records[i]
        print('%d. %s [%s] %s' % (i + 1, record['timestamp'], record['level'], record['message']))
    print()
    print(format_report(count_levels(records)))
    print()
    important = levels_at_least('WARNING')
    for record in records:
        if record['level'] in important:
            print('needs attention:', record['message'])


if __name__ == '__main__':
    main()

