def check_interval_overlap(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2
    return start1 <= end2 and start2 <= end1


def overlap_duration(interval1, interval2):
    if not check_interval_overlap(interval1, interval2):
        return 0
    return min(interval1[1], interval2[1]) - max(interval1[0], interval2[0])


def validate_schedule(schedule):
    for name, interval in schedule.items():
        start, end = interval
        if start > end:
            raise ValueError("interval for %s ends before it starts" % name)


def build_overlap_matrix(intervals):
    matrix = []
    for i in range(len(intervals)):
        row = []
        for j in range(len(intervals)):
            row.append(i != j and check_interval_overlap(intervals[i], intervals[j]))
        matrix.append(row)
    return matrix


def find_conflicts(schedule):
    names = sorted(schedule.keys())
    conflicts = {}
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            first, second = names[i], names[j]
            if check_interval_overlap(schedule[first], schedule[second]):
                conflicts[(first, second)] = overlap_duration(schedule[first], schedule[second])
    return conflicts


def merge_intervals(intervals):
    ordered = sorted(intervals)
    if not ordered:
        return []
    merged = [ordered[0]]
    for k in range(1, len(ordered)):
        last, current = merged[-1], ordered[k]
        if check_interval_overlap(last, current):
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return merged


def free_slots(schedule, day):
    busy = merge_intervals(list(schedule.values()))
    slots = []
    cursor = day[0]
    for block in busy:
        if block[0] > cursor:
            slots.append((cursor, block[0]))
        cursor = max(cursor, block[1])
    if cursor < day[1]:
        slots.append((cursor, day[1]))
    return slots


def total_busy_hours(schedule):
    return sum(end - start for start, end in merge_intervals(list(schedule.values())))


def format_report(schedule, conflicts, slots):
    lines = ["Meetings:"]
    for name, interval in sorted(schedule.items()):
        lines.append("  %-10s %.1f - %.1f" % (name, interval[0], interval[1]))
    lines.append("Conflicts:")
    for pair, hours in sorted(conflicts.items()):
        lines.append("  %s vs %s overlaps %.1fh" % (pair[0], pair[1], hours))
    lines.append("Free: " + ", ".join("%.1f-%.1f" % slot for slot in slots))
    lines.append("Busy total: %.1fh" % total_busy_hours(schedule))
    return lines


def main():
    print(check_interval_overlap((1, 5), (3, 7)))
    print(check_interval_overlap((1, 5), (6, 10)))
    schedule = {
        "standup": (9.0, 9.5),
        "design": (9.25, 10.5),
        "lunch": (12.0, 13.0),
        "review": (12.5, 14.0),
    }
    validate_schedule(schedule)
    conflicts = find_conflicts(schedule)
    slots = free_slots(schedule, (8.0, 17.0))
    for line in format_report(schedule, conflicts, slots):
        print(line)
    names = sorted(schedule.keys())
    matrix = build_overlap_matrix([schedule[name] for name in names])
    for index in range(len(names)):
        flags = " ".join("X" if cell else "." for cell in matrix[index])
        print("%-10s %s" % (names[index], flags))


if __name__ == "__main__":
    main()

