    if not numbers:
        return None

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 1:
        middle_index = n // 2
        for i in xrange(len(sorted_numbers)):
            if i == middle_index:
                return sorted_numbers[i]
    else:
        mid1_index = n // 2 - 1
        mid2_index = n // 2
        for j in xrange(len(sorted_numbers)):
            if j == mid1_index:
                val1 = sorted_numbers[j]
