def is_valid_us_zip_code(zip_code_str):
    if len(zip_code_str) != 5:
        return False
    digit_counts = {}
    for i in range(10):
        digit_counts[str(i)] = 0
    for char_index in range(len(zip_code_str)):
        char = zip_code_str[char_index]
        if char not in digit_counts.keys():
            return False
        digit_counts[char] += 1
    total_digits = 0
    for digit_value in digit_counts.values():
        total_digits += digit_value
    if total_digits != 5:
        return False
    for k, v in digit_counts.items():
        if k not in "0123456789" and v > 0:
            return False
    return True

