def censor_text(text, bad_words):
    words = text.split()
    censored_words = {}
    for i in range(len(bad_words)):
        bad_word = bad_words[i]
        censored_words[bad_word.lower()] = '*' * len(bad_word)

    result_words = []
    for i in range(len(words)):
        word = words[i]
        clean_word = "".join(char for char in word if char.isalpha())
        if clean_word.lower() in censored_words.keys():
            replacement = censored_words[clean_word.lower()]
            original_chars = list(word)
            for j in range(len(original_chars)):
                if original_chars[j].isalpha():
                    original_chars[j] = replacement[j % len(replacement)]
            result_words.append("".join(original_chars))
        else:
            result_words.append(word)

    return ' '.join(result_words)

