def geometric_series_sum(a, r, n):
    """Sum of the first n terms of the geometric series a, a*r, a*r^2, ..."""
    if n < 0:
        raise ValueError("number of terms must be non-negative")
    if r == 1:
        return a * n
    return a * (1 - r ** n) / (1 - r) if isinstance(r, float) else a * (1 - r ** n) // (1 - r)


def series_terms(a, r, n):
    """Return the individual terms of the series as a list."""
    terms = []
    term = a
    for _ in range(n):
        terms.append(term)
        term = term * r
    return terms


def partial_sums(a, r, n):
    """Map each term count k (1..n) to the sum of the first k terms."""
    terms = series_terms(a, r, n)
    sums = {}
    running = 0
    for k in range(1, n + 1):
        running += terms[k - 1]
        sums[k] = running
    return sums


def verify_formula(a, r, n):
    """Check the closed-form sum against the accumulated partial sums."""
    mismatches = {}
    for k, accumulated in partial_sums(a, r, n).items():
        closed = geometric_series_sum(a, r, k)
        if abs(closed - accumulated) > 1e-9:
            mismatches[k] = (closed, accumulated)
    return mismatches


def describe(a, r, n):
    """Build a human readable line for one series."""
    pieces = [str(term) for term in series_terms(a, r, n)]
    total = geometric_series_sum(a, r, n)
    body = " + ".join(pieces) if pieces else "0"
    return "a={0}, r={1}, n={2}: {3} = {4}".format(a, r, n, body, total)


def growth_profile(a, r, n):
    """Ratio of each partial sum to the final sum, keyed by term count."""
    total = geometric_series_sum(a, r, n)
    profile = {}
    for k, value in partial_sums(a, r, n).items():
        profile[k] = value / total if total else 0.0
    return profile


def main():
    cases = [(1, 2, 3), (5, 1, 4), (3, 0.5, 6), (2, -3, 5), (7, 1, 0)]
    for a, r, n in cases:
        print(describe(a, r, n))
        for k, (closed, accumulated) in verify_formula(a, r, n).items():
            print("  mismatch at k={0}: {1} vs {2}".format(k, closed, accumulated))

    a, r, n = cases[2]
    profile = growth_profile(a, r, n)
    for k in sorted(profile.keys()):
        print("first {0} terms reach {1:.1%} of the total".format(k, profile[k]))
    print("mean coverage: {0:.1%}".format(sum(profile.values()) / len(profile)))


if __name__ == "__main__":
    main()

