def is_point_in_circle(px, py, cx, cy, radius):
    """Return True if (px, py) lies inside or on the circle (cx, cy, radius)."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    dx = px - cx
    dy = py - cy
    return dx * dx + dy * dy <= radius * radius


def classify_point(px, py, cx, cy, radius):
    """Return 'inside', 'boundary' or 'outside' for a point against a circle."""
    dx = px - cx
    dy = py - cy
    squared = dx * dx + dy * dy
    if squared == radius * radius:
        return "boundary"
    if is_point_in_circle(px, py, cx, cy, radius):
        return "inside"
    return "outside"


def classify_many(points, cx, cy, radius):
    """Map each point index to its classification against the circle."""
    result = {}
    for index in range(len(points)):
        px, py = points[index]
        result[index] = classify_point(px, py, cx, cy, radius)
    return result


def count_by_class(classifications):
    """Tally how many points fell into each class."""
    tally = {"inside": 0, "boundary": 0, "outside": 0}
    for label in classifications.values():
        tally[label] += 1
    return tally


def scan_lattice(cx, cy, radius, half_width):
    """Collect integer lattice points of the square window that are in the circle."""
    covered = []
    for x in range(int(cx) - half_width, int(cx) + half_width + 1):
        for y in range(int(cy) - half_width, int(cy) + half_width + 1):
            if is_point_in_circle(x, y, cx, cy, radius):
                covered.append((x, y))
    return covered


def row_widths(lattice_points):
    """Number of covered lattice points per row, keyed by the y coordinate."""
    widths = {}
    for x, y in lattice_points:
        widths[y] = widths.get(y, 0) + 1
    return widths


def format_report(classifications, points):
    lines = []
    for index, label in classifications.items():
        px, py = points[index]
        lines.append("point ({0}, {1}) -> {2}".format(px, py, label))
    return "\n".join(lines)


def main():
    cx, cy, radius = 0, 0, 2
    points = [(1, 1), (3, 3), (2, 0), (0, -2), (-1, -1), (2, 2)]
    classifications = classify_many(points, cx, cy, radius)
    print(format_report(classifications, points))

    tally = count_by_class(classifications)
    for label in sorted(tally.keys()):
        print("{0}: {1}".format(label, tally[label]))

    lattice = scan_lattice(cx, cy, radius, 3)
    print("lattice points covered:", len(lattice))
    widths = row_widths(lattice)
    for y in sorted(widths.keys()):
        print("row y={0}: {1} points".format(y, widths[y]))

    print(is_point_in_circle(1, 1, 0, 0, 2), is_point_in_circle(3, 3, 0, 0, 2))


if __name__ == "__main__":
    main()

