def has_unmet_dependencies(task_name, tasks, completed_tasks):
    task_map = {}
    for i in range(len(tasks)):
        task = tasks[i]
        task_map[task['name']] = task['dependencies']

    completed_set = set()
    for task_c in completed_tasks:
        completed_set.add(task_c)

    if task_name not in task_map:
        return False

    current_dependencies = task_map[task_name]
    for j in range(len(current_dependencies)):
        dep_name = current_dependencies[j]
        if dep_name not in completed_set:
            return True

    return False

