def is_positive_integer(value):
    """Return True only when value is an int (not bool) strictly greater than zero."""
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return value > 0
    return False


def rejection_reason(value):
    """Describe why a value is not a positive integer, or None when it is one."""
    if is_positive_integer(value):
        return None
    if isinstance(value, bool):
        return "booleans are not accepted as integers"
    if isinstance(value, int):
        return "integer is zero or negative"
    if isinstance(value, float):
        return "floats are not integers"
    return "value is not of an integer type"


def validate_batch(values):
    """Map each position in values to the outcome of is_positive_integer."""
    results = {}
    for index in range(len(values)):
        results[index] = is_positive_integer(values[index])
    return results


def build_reason_table(values):
    """Count how often each rejection reason occurs in values."""
    table = {}
    for index in range(len(values)):
        reason = rejection_reason(values[index])
        if reason is not None:
            table[reason] = table.get(reason, 0) + 1
    return table


def summarize(results):
    accepted = 0
    for ok in results.values():
        if ok:
            accepted += 1
    return {"total": len(results), "accepted": accepted, "rejected": len(results) - accepted}


