import datetime

TODAY = datetime.date(2023, 10, 26)


def calculate_age(birthdate, today=TODAY):
    """Return the whole number of years between birthdate and today."""
    if birthdate > today:
        raise ValueError("birthdate lies in the future")
    age = today.year - birthdate.year
    if (today.month, today.day) < (birthdate.month, birthdate.day):
        age -= 1
    return age


def age_on_birthdays(birthdate, first_year, last_year, today=TODAY):
    """Map each birthday year in the range to the age reached that year."""
    ages = {}
    for year in range(first_year, last_year + 1):
        try:
            birthday = birthdate.replace(year=year)
        except ValueError:
            birthday = datetime.date(year, 3, 1)
        if birthday <= today:
            ages[year] = calculate_age(birthdate, birthday)
    return ages


def days_until_next_birthday(birthdate, today=TODAY):
    """Number of days between today and the next occurrence of the birthday."""
    for year in range(today.year, today.year + 5):
        try:
            birthday = birthdate.replace(year=year)
        except ValueError:
            continue
        if birthday >= today:
            return (birthday - today).days
    raise ValueError("no upcoming birthday found")


def group_by_age(people, today=TODAY):
    """Build a mapping age -> sorted list of names."""
    groups = {}
    for name, birthdate in people.items():
        age = calculate_age(birthdate, today)
        groups.setdefault(age, []).append(name)
    for names in groups.values():
        names.sort()
    return groups


def format_report(people, today=TODAY):
    lines = []
    for name, birthdate in people.items():
        age = calculate_age(birthdate, today)
        wait = days_until_next_birthday(birthdate, today)
        lines.append("{:<8} born {} -> {} years, next birthday in {} days".format(
            name, birthdate.isoformat(), age, wait))
    groups = group_by_age(people, today)
    for age in sorted(groups.keys(), reverse=True):
        lines.append("age {}: {}".format(age, ", ".join(groups[age])))
    return "\n".join(lines)


def main():
    people = {
        "Ann": datetime.date(1990, 1, 1),
        "Bob": datetime.date(2000, 11, 15),
        "Cleo": datetime.date(1990, 10, 26),
        "Dan": datetime.date(2004, 2, 29),
    }
    print(format_report(people))
    history = age_on_birthdays(people["Bob"], 2018, 2023)
    for year, age in history.items():
        print("Bob turned {} in {}".format(age, year))


if __name__ == "__main__":
    main()

