def calculate_triangle_perimeter(side1, side2, side3):
    sides = {0: side1, 1: side2, 2: side3}
    perimeter = 0.0
    for i in range(3):
        perimeter += sides[i]
    if perimeter == 0:
        return 0.0
    side_values = list(sides.values())
    for j in range(len(side_values)):
        if side_values[j] <= 0:
            raise ValueError("Side lengths must be positive.")
    for k_idx in range(len(side_values)):
        remaining_sum = 0.0
        for l_idx, val in sides.items():
            if l_idx != k_idx:
                remaining_sum += val
        if side_values[k_idx] >= remaining_sum:
            raise ValueError("Invalid triangle side lengths.")
    return perimeter

