MONTH_NAMES = {
    1: "January", 2: "February", 3: "March", 4: "April",
    5: "May", 6: "June", 7: "July", 8: "August",
    9: "September", 10: "October", 11: "November", 12: "December",
}

BASE_LENGTHS = {
    1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
    7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31,
}


def is_leap_year(year):
    """A year is a leap year if divisible by 4, except centuries not divisible by 400."""
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def count_days_in_month(year, month):
    """Return the number of days in the given month of the given year."""
    if month not in BASE_LENGTHS.keys():
        raise ValueError("month must be an integer from 1 to 12")
    if month == 2 and is_leap_year(year):
        return 29
    return BASE_LENGTHS[month]


def month_lengths_for_year(year):
    """Map every month number of the year to its actual length."""
    return {month: count_days_in_month(year, month) for month in BASE_LENGTHS.keys()}


def days_in_year(year):
    total = 0
    for month in range(1, 13):
        total += count_days_in_month(year, month)
    return total


def quarter_totals(year):
    """Return a dict mapping quarter number (1-4) to its number of days."""
    lengths = month_lengths_for_year(year)
    totals = {}
    for quarter in range(1, 5):
        first_month = 3 * quarter - 2
        totals[quarter] = sum(lengths[m] for m in range(first_month, first_month + 3))
    return totals


def format_year_table(year):
    lines = ["Calendar for %d (%d days)" % (year, days_in_year(year))]
    for month, length in month_lengths_for_year(year).items():
        lines.append("  %-9s %2d" % (MONTH_NAMES[month], length))
    for quarter, total in quarter_totals(year).items():
        lines.append("  Q%d total: %d" % (quarter, total))
    return "\n".join(lines)


def longest_months(year):
    """Names of the months that are as long as the longest month of the year."""
    lengths = month_lengths_for_year(year)
    longest = max(lengths.values())
    return [MONTH_NAMES[month] for month, length in lengths.items() if length == longest]


def main():
    print(count_days_in_month(2023, 2))
    print(count_days_in_month(2024, 2))
    print(count_days_in_month(2023, 1))
    for year in range(1999, 2002):
        print(format_year_table(year))
    print("Longest months of 2024: " + ", ".join(longest_months(2024)))


if __name__ == "__main__":
    main()

