def find_student_by_id(students_db, student_id):
    """Return the record whose 'id' equals student_id, or None."""
    for index in range(len(students_db)):
        record = students_db[index]
        if record.get('id') == student_id:
            return record
    return None


def build_id_index(students_db):
    """Map each student id to its position in the list."""
    index = {}
    for position in range(len(students_db)):
        index[students_db[position]['id']] = position
    return index


def find_duplicate_ids(students_db):
    """Return ids that appear more than once, in ascending order."""
    counts = {}
    for record in students_db:
        counts[record['id']] = counts.get(record['id'], 0) + 1
    duplicates = []
    for student_id, count in counts.items():
        if count > 1:
            duplicates.append(student_id)
    return sorted(duplicates)


def missing_fields(record):
    """Return the required keys that are absent or empty in a record."""
    required = ('id', 'name', 'major')
    gaps = []
    for key in required:
        if record.get(key) in (None, ''):
            gaps.append(key)
    return gaps


def group_by_major(students_db):
    """Group student names by major, keeping insertion order per major."""
    groups = {}
    for record in students_db:
        groups.setdefault(record.get('major', 'Undeclared'), []).append(record['name'])
    return groups


def format_record(record):
    parts = []
    for key, value in record.items():
        parts.append('{}={}'.format(key, value))
    return ' | '.join(parts)


def report(students_db, queried_ids):
    lines = []
    for student_id in queried_ids:
        found = find_student_by_id(students_db, student_id)
        if found is None:
            lines.append('id {}: not found'.format(student_id))
        else:
            lines.append('id {}: {}'.format(student_id, format_record(found)))
    for major, names in group_by_major(students_db).items():
        lines.append('{}: {}'.format(major, ', '.join(names)))
    return lines


def main():
    db = [
        {'id': 1, 'name': 'Alice', 'major': 'Physics'},
        {'id': 2, 'name': 'Bob', 'major': 'Physics'},
        {'id': 3, 'name': 'Cara', 'major': 'History'},
        {'id': 2, 'name': 'Bob Jr.', 'major': ''},
    ]
    for line in report(db, [2, 3, 7]):
        print(line)
    print('duplicate ids:', find_duplicate_ids(db))
    positions = build_id_index(db)
    for student_id in sorted(positions.keys()):
        print('id {} indexed at {}'.format(student_id, positions[student_id]))
    for record in db:
        gaps = missing_fields(record)
        if gaps:
            print('incomplete record {}: missing {}'.format(record['name'], ', '.join(gaps)))


if __name__ == '__main__':
    main()

