def calculate_future_value_simple(principal, rate, years):
    """Future value of a lump sum under simple interest compounded annually."""
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if years < 0:
        raise ValueError("years must be non-negative")
    return float(principal * (1 + rate * years))


def yearly_schedule(principal, rate, years):
    """Map each elapsed year (0..years) to the accumulated value at that point."""
    schedule = {}
    for year in range(years + 1):
        schedule[year] = calculate_future_value_simple(principal, rate, year)
    return schedule


def yearly_interest(schedule):
    """Interest credited during each year, derived from consecutive balances."""
    years = max(schedule.keys())
    gains = {}
    for year in range(1, years + 1):
        gains[year] = schedule[year] - schedule[year - 1]
    return gains


def compare_rates(principal, rates, years):
    """Future value for each candidate annual rate."""
    return {rate: calculate_future_value_simple(principal, rate, years) for rate in rates}


def best_rate(comparison):
    """The rate yielding the highest future value."""
    winner = None
    for rate, value in comparison.items():
        if winner is None or value > comparison[winner]:
            winner = rate
    return winner


def format_schedule(schedule):
    lines = []
    for year, value in schedule.items():
        lines.append("year {:>2}: {:>12,.2f}".format(year, value))
    return "\n".join(lines)


def schedule_summary(schedule):
    values = list(schedule.values())
    return {
        "start": min(values),
        "end": max(values),
        "growth": max(values) - min(values),
    }


def main():
    principal, rate, years = 1000.0, 0.05, 5
    schedule = yearly_schedule(principal, rate, years)
    print(format_schedule(schedule))

    for year, interest in yearly_interest(schedule).items():
        print("interest in year {}: {:,.2f}".format(year, interest))

    summary = schedule_summary(schedule)
    for name in summary.keys():
        print("{}: {:,.2f}".format(name, summary[name]))

    comparison = compare_rates(500.0, [0.02, 0.1, 0.075], 2)
    for rate in sorted(comparison.keys()):
        print("rate {:.3f} -> {:,.2f}".format(rate, comparison[rate]))
    print("best rate: {:.3f}".format(best_rate(comparison)))


if __name__ == "__main__":
    main()

