DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def digit_table(base):
    """Map every legal digit character of `base` to its numeric value."""
    if not isinstance(base, int) or not 2 <= base <= 36:
        raise ValueError("base must be an integer between 2 and 36")
    return {DIGITS[i]: i for i in range(base)}


def split_sign(num_str):
    """Split an optional leading sign from the digits of `num_str`."""
    text = num_str.strip().lower()
    negative = text.startswith("-")
    if negative or text.startswith("+"):
        text = text[1:]
    if not text:
        raise ValueError("no digits to convert")
    return negative, text


def base_n_to_base_10(num_str, base):
    """Convert `num_str`, written in `base`, to a base-10 integer."""
    table = digit_table(base)
    negative, text = split_sign(num_str)
    total = 0
    for char in text:
        if char not in table:
            raise ValueError("{0!r} is not a digit in base {1}".format(char, base))
        total = total * base + table[char]
    return -total if negative else total


def positional_terms(num_str, base):
    """Break a number into (digit, power, contribution) triples."""
    table = digit_table(base)
    negative, text = split_sign(num_str)
    sign = -1 if negative else 1
    terms = []
    for i in range(len(text)):
        power = len(text) - 1 - i
        terms.append((text[i], power, sign * table[text[i]] * base ** power))
    return terms


def base_10_to_base_n(value, base):
    """Write `value` using the digit symbols of `base`."""
    symbols = {digit: char for char, digit in digit_table(base).items()}
    if value == 0:
        return "0"
    rest, out = abs(value), []
    while rest:
        out.append(symbols[rest % base])
        rest //= base
    if value < 0:
        out.append("-")
    return "".join(reversed(out))


def convert_many(entries):
    """entries maps a number string to the base it is written in."""
    return {text: base_n_to_base_10(text, base) for text, base in entries.items()}


def canonical_forms(results, entries):
    """Re-encode each converted value to its canonical spelling."""
    return {text: base_10_to_base_n(value, entries[text]) for text, value in results.items()}


def format_report(entries, results):
    width = max(len(text) for text in results.keys())
    lines = []
    for text, value in results.items():
        lines.append("{0:>{2}} (base {1:>2}) -> {3}".format(text, entries[text], width, value))
    return "\n".join(lines)


def base_usage(entries):
    counts = {}
    for base in entries.values():
        counts[base] = counts.get(base, 0) + 1
    return counts


def main():
    entries = {"101": 2, "A": 16, "zz": 36, "0777": 8, "-ff": 16, "2024": 10}
    results = convert_many(entries)
    print(format_report(entries, results))
    print("sum of values:", sum(results.values()))
    for base, count in sorted(base_usage(entries).items()):
        print("base {0:>2}: {1} number(s)".format(base, count))
    for text, canon in sorted(canonical_forms(results, entries).items()):
        if canon != text.strip().lower():
            print("{0} normalises to {1}".format(text, canon))
    for char, power, part in positional_terms("2024", 10):
        print("digit {0} at power {1} contributes {2}".format(char, power, part))


if __name__ == "__main__":
    main()

